<h2 class="text-center text-blue-900 font-bold text-2xl sm:text-2xl md:text-2xl mt-6 mb-6">Предисловие<br>«Ратнагунасамчаягатха»: текст Праджняпарамиты и редакция Харибхадры</h2>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <!-- Раздел 1 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">1. Введение: стихотворное изложение Праджняпарамиты</h3>
    <div>
        <p><em>Ратнагунасамчаягатха</em> (санскр. <em>Ratnaguṇasaṃcayagāthā</em>, далее <em>Rgs</em>) — стихотворное изложение Праджняпарамиты, известное также как «Строфы собрания драгоценных качеств». Среди ранних махаянских текстов оно занимает особое место: в сжатых, стройных по ритму гатхах здесь представлены путь бодхисаттвы и совершенная мудрость (<em>prajñāpāramitā</em>). <em>Rgs</em> — краткая стихотворная версия «Аштасахасрики», «Праджняпарамиты в восьми тысячах [строф]»: главы поэмы отвечают разделам этой сутры, а колофон прямо говорит, что текст составлен «в соответствии с разделами» «Аштасахасрики».</p>
        <p>Стихотворная форма требует особого способа чтения. Краткость строф, повторы и парадоксальные обороты делают текст удобным для запоминания и созерцательного усвоения. Шуньята (<em>śūnyatā</em>) раскрывается в нём через неустановимость, необнаружимость дхарм (<em>anupalabdhi</em>, <em>anopalabdhi</em>), через отсутствие цепляния и неразделимость мудрости и сострадания. Постижение шуньяты не отменяет деятельности бодхисаттвы: оно позволяет действовать, не цепляясь умом за представления о деятеле, объекте и результате.</p>
        <p>До нас <em>Rgs</em> дошла прежде всего в редакции, связанной с именем Харибхадры. В ней текст разделён на 32 главы и соотнесён с восемью абхисамаями (<em>abhisamaya</em>) «Абхисамая-аланкары»; этот порядок стал основополагающим для последующей тибетской традиции. Однако история <em>Rgs</em> не сводится к трудам одного редактора: текст существовал в нескольких версиях, а его стихотворное ядро старше известной нам 32-главной редакции.<a href="#citation-1" id="ref-1" class="citation-mark"><sup>1</sup></a></p>
    </div>

    <!-- Раздел 2 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">2. Основные темы текста</h3>
    <div>
        <p>Средоточие <em>Rgs</em> — совершенная мудрость, постигающая шуньяту всех дхарм. Шуньята связана здесь с тем, что дхармы невозможно установить и обнаружить как нечто существующее само по себе. Поэтому одним из ключевых слов текста становится <em>anupalabdhi</em> — «не-нахождение», «неустановимость», «необнаружимость». Оно родственно <em>anutpāda</em>, невозникновению: дхармы не возникают в том смысле, который предполагал бы их самостоятельное бытие.</p>
        <p>Текст неоднократно возвращается к практике безопорности. Бодхисаттва осваивает трое врат освобождения: шуньяту, свободу от образов-знаков (<em>animitta</em>) и без-устремлённость (<em>apraṇihita</em>). Эти врата раскрывают разные стороны освобождения от цепляния: за существование, за воспринимаемые образы-знаки, за представление о достижении как о самостоятельно устанавливаемом результате. Сама безопорность выражена в тексте целым рядом слов: <em>anālaya</em> («без привязанности», 15.8), <em>aniketacārī</em> («странствующий без дома», 1.6, 1.10, 2.3), <em>asthāna</em> («без места», 20.19), <em>athānasthita</em> (27.5).</p>
        <p>Праджняпарамита выражает эту логику парадоксальными формулами. Обучение совершается без утверждения обучающегося; посвящение заслуги — без утверждения посвящающего; сострадание обращено к существам, хотя бодхисаттва не различает существо как нечто самостоятельное. Эти формулы не отвергают ни путь, ни практику: речь идёт о совершенном постижении и совершенном деянии.<a href="#citation-2" id="ref-2" class="citation-mark"><sup>2</sup></a></p>
        <p>В этом и состоит единство мудрости и сострадания. Мудрость освобождает от ложного схватывания дхарм, сострадание определяет направление действия. Единство их заложено в самом устройстве пути: бодхисаттва трудится ради блага существ, не превращая в нечто устойчивое и захватываемое ни себя, ни других, ни плод своего деяния.</p>
    </div>

    <!-- Раздел 3 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">3. Язык и стихотворная форма</h3>
    <div>
        <p><em>Rgs</em> написана на буддийском гибридном санскрите (<em>Buddhist Hybrid Sanskrit</em>, BHS), систематически описанном в грамматике и словаре Франклина Эджертона.<a href="#citation-3" id="ref-3" class="citation-mark"><sup>3</sup></a> Язык памятника хранит среднеиндийские черты, которые соседствуют с санскритскими формами и постепенно им уступают. Это видно, например, по <em>anopalabdhi</em> вместо ожидаемого <em>anupalabdhi</em> и по <em>raha</em> вместо <em>arhat</em>.</p>
        <p>Архаические формы важны для понимания текста. Их не всегда можно исправлять по правилам классического санскрита: исправление способно скрыть древние языковые особенности или нарушить метр строфы. Поэтому работа над переводом <em>Rgs</em> потребовала сопоставления санскритского текста с тибетским и китайским переводами и внимания к вариантам чтения.</p>
        <p>По мнению Э. Конзе, разделяемому рядом исследователей, первые две главы <em>Rgs</em> могут сохранять древнейший слой литературы Праджняпарамиты, относимый примерно к I в. до н. э. — I в. н. э. Эта датировка касается предполагаемого раннего слоя, а не окончательной редакции текста.<a href="#citation-4" id="ref-4" class="citation-mark"><sup>4</sup></a></p>
    </div>

    <!-- Раздел 4 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">4. Харибхадра: жизнь, эпоха, линия преемственности</h3>
    <div>
        <p>Харибхадра (санскр. <em>Haribhadra</em>, тиб. <em>Seng ge bzang po</em>, букв. «Благой Лев»; ок. 750–810 гг. н. э.) — выдающийся индийский буддийский мыслитель и комментатор эпохи империи Пала. Его труды определили каноническую форму истолкования литературы Праджняпарамиты и трактата «Абхисамая-аланкара». Единственной надёжной исторической опорой для датировки служит колофон главного его сочинения — «Абхисамая-аланкара-алоки» (<em>Abhisamayālaṃkārālokā</em>): в нём упомянуты царственный покровитель Харибхадры Дхармапала (ок. 775–812) и монастырь Трикатака (<em>Trikaṭuka-vihāra</em>), где он жил и преподавал.</p>
        <p>Дальнейшие сведения о его жизни сохранились в позднейших тибетских историографических сочинениях — у Бутона Ринчендуба и Таранатхи, — где исторические реалии переплетаются с житийным преданием. Согласно этим источникам, Харибхадра происходил из царского рода (кшатриев) Восточной Индии, рано принял монашество и получил блестящее образование в логике (прамана), Абхидхарме и праджняпарамитских сутрах. Главным своим философским наставником он почитал Шантаракшиту (ок. 725–788), у которого воспринял синтез йогачары и сватантрика-мадхьямаки; линию истолкования «Абхисамая-аланкары» он получил от наставника Вайрочанабхадры. По преданию, столкнувшись с разночтениями в предшествующих комментариях Асанги, Васубандху и Вимуктисены, Харибхадра удалился в затворничество в Кхасарпану (<em>Khasarpaṇa</em>; по тибетскому преданию, на востоке Индии), где после видения бодхисаттвы Майтреи в медитации составил свои знаменитые комментарии, согласовавшие устройство «Абхисамая-аланкары» с текстом «Аштасахасрики». Среди ближайших его учеников выделяется Буддхаджнянапада, также автор комментария на «Ратнагунасамчая-гатху».</p>
    </div>

    <!-- Раздел 5 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">5. Рецензия A и структура восьми абхисамай</h3>
    <div>
        <p>Главный вклад Харибхадры в историю <em>Rgs</em> связан с редакцией, известной как Рецензия A, где стихотворный текст разделён на 32 главы. Сама редакторская работа засвидетельствована в завершающих строфах Харибхадры (<em>praśasti</em>): он говорит в них о расхождениях рукописей и о необходимости упорядочить текст. Но подробности его труда — как собирались рукописи, как отсеивались вставки, как восстанавливался первоначальный порядок строф — нельзя считать установленными во всех деталях.</p>
        <p>Важнейшим принципом строения текста стало его соотнесение с «Абхисамая-аланкарой» (<em>Abhisamayālaṃkāra</em>) — трактатом, который по традиции приписывают Майтрее и считают переданным Асангой. В этой системе путь бодхисаттвы раскрывается через восемь абхисамай, «ясных постижений» (<em>abhisamaya</em>), и семьдесят тем.</p>
        <p>В тибетской традиции первые три главы <em>Rgs</em> названы по трём знаниям:</p>
        <ul class="list-disc pl-5 space-y-1 ml-8">
            <li class="my-2"><em>sarvākārajñatā</em> — знание всех аспектов;</li>
            <li class="my-2"><em>mārgajñatā</em> — знание пути;</li>
            <li class="my-2"><em>vastujñatā</em> — знание основ.</li>
        </ul>
        <p>В санскритской Рецензии A названия звучат иначе: лишь первая глава (<em>sarvākārajñatācaryāparivarta</em>, «Практика знания всех аспектов») сохраняет упоминание одного из трёх знаний; вторая носит имя <em>śakraparivarta</em> («Глава Шакры»), третья — <em>aprameyaguṇadhāraṇapāramitāstūpasatkāraparivarta</em> («Глава о парамите держания неизмеримых качеств и почитании ступ»). Соотнесение трёх первых глав с тремя знаниями — достояние тибетской традиции.</p>
        <p>Следующие главы разворачивают дальнейшие этапы пути. Завершающая, 32-я глава — <em>Parīndanāparivarta</em> — соотносится с седьмой и восьмой абхисамаями: <em>ekakṣaṇa-abhisamaya</em>, постижением в единый миг, и <em>dharmakāya</em>, Телом Дхармы. Так текст приходит от пути к его плоду.<a href="#citation-5" id="ref-5" class="citation-mark"><sup>5</sup></a></p>
        <p>Харибхадра не был единственным редактором или истолкователем <em>Rgs</em>. Современная текстология различает Рецензию A и Рецензию B, причём последняя отличается от 32-главной редакции. Рецензия A, связанная с именем Харибхадры и снабжённая его комментарием, получила широкое распространение в тибетской традиции; именно она положена в основу настоящего перевода.<a href="#citation-6" id="ref-6" class="citation-mark"><sup>6</sup></a></p>
    </div>

    <!-- Раздел 6 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">6. Философские труды и доктрина</h3>
    <div>
        <p>Харибхадра известен прежде всего комментариями к Праджняпарамите и «Абхисамая-аланкаре». Основной корпус его праджняпарамитских сочинений составляют четыре труда: большой сводный комментарий <em>Abhisamayālaṃkārālokā-nāma-prajñāpāramitopadeśaśāstra</em> (обычно <em>Ālokā</em>), систематически истолковывающий «Абхисамая-аланкару» в связи с «Аштасахасрикой»; краткий комментарий на коренные строфы «Абхисамая-аланкары» — <em>Abhisamayālaṃkāravṛtti</em> (<em>Sphuṭārthā</em>, «Ясный смысл»); редакция «Панчавимшатисахасрика-праджняпарамиты»; наконец, комментарий на «Ратнагунасамчая-гатху» — <em>Bhagavadratnaguṇasaṃcayagāthāpañjikā</em> (<em>Subodhinī</em>, тиб. <em>dka' 'grel rtogs sla ba</em>), где строфы сутры соотнесены со схемой восьми постижений (<em>abhisamaya</em>). Авторство Харибхадры для этого комментария ставилось под сомнение ещё в тибетской традиции (Обермиллер называет пандита Стхирапалу и переводчика Нгока Лодена Шераба), но Цонкапа считал его сочинением Харибхадры. В этих комментариях структурное прочтение текста сочетается с анализом познания, пути бодхисаттвы и плода практики.<a href="#citation-7" id="ref-7" class="citation-mark"><sup>7</sup></a></p>
        <p>Харибхадра последовательно отстаивал учение о «единой колеснице» (<em>ekayāna</em>): все живые существа обладают задатками пробуждения, а пути шраваков и пратьекабудд суть лишь промежуточные ступени, в конечном счёте ведущие к состоянию будды.</p>
        <p>Особое место занимает вопрос о четырёх Телах Будды (<em>caturkāya</em>). В восьмой главе «Абхисамая-аланкары» Харибхадра истолковывает буддовость через четыре Тела: <em>svābhāvikakāya</em>, <em>jñānadharmakāya</em>, <em>saṃbhogakāya</em> и <em>nirmāṇakāya</em>. Это прочтение стало предметом долгих споров в Индии и Тибете. В Гелуг его поддержал Цонкапа; ряд авторов Сакья, среди них Горампа, понимал восьмую главу иначе и отстаивал трёхчастную схему.<a href="#citation-8" id="ref-8" class="citation-mark"><sup>8</sup></a></p>
        <p>Поэтому позицию Харибхадры надо понимать как влиятельное толкование, ставшее нормативным в некоторых линиях тибетской традиции. Для других школ оно не было бесспорным, и представлять его единственно возможной интерпретацией нельзя.</p>
        <p>В историко-доктринальной классификации Харибхадру относят также к <em>alīkākāravāda</em> — взгляду, согласно которому образы познания (<em>ākāra</em>) ложны в отношении приписываемого им способа бытия; этим он отличается от Камалашилы, придерживавшегося <em>satyākāravāda</em>. Это обозначение связано с индийскими спорами о природе познавательных образов и различием между <em>satyākāravāda</em> и <em>alīkākāravāda</em>.<a href="#citation-9" id="ref-9" class="citation-mark"><sup>9</sup></a></p>
    </div>

    <!-- Раздел 7 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">7. О настоящем переводе</h3>
    <div>
        <p>В основу перевода положено санскритское издание П. Л. Вайдьи, воспроизводящее Рецензию A. Учитывались также тибетская версия из Кангьюра (D13) и китайский перевод Фасяня (法賢, он же Тяньсицзай 天息災 (Дхармабхадра); эпоха Северная Сун, ок. 991 г.; Т.229), которого не следует путать с паломником Фасянем (法顯, IV–V вв.). Эти параллели служили для проверки смысла, разрешения грамматических трудностей и выявления расхождений между версиями.<a href="#citation-10" id="ref-10" class="citation-mark"><sup>10</sup></a></p>
        <p>Санскритские термины, существенные для философского содержания, даются в скобках при первом употреблении, а далее переводятся последовательно. Когда санскритский текст допускает несколько прочтений, решение принимается с учётом тибетского соответствия и контекста строфы.</p>
    </div>
    <hr class="my-8 border-t-4 border-gray-500">
</div>

