<h2 class="text-center mt-6 mb-4 text-xl font-bold">Собрание драгоценных качеств в строфах (Ратнагунасамчаягатха)</h2>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Поклон Бхагавати — благородной «Праджняпарамите в строфах, содержащих собрание драгоценных качеств» (<em>om namo bhagavatyai āryaprajñāpāramitāratnaguṇasaṃcayagāthāyai</em>).</p>
    <p>Поклон благородному Манджушри (<em>namo āryamañjuśriye</em>).</p>
    <p>Затем Бхагаван, чтобы обрадовать четыре собрания и вновь ясно изложить эту Праджняпарамиту, в то время произнёс эти строфы.</p>

    <!-- Глава 1 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 1. Практика знания всех аспектов (<em>sarvākārajñātācaryāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.1</strong></li>
            <li>Утвердив в себе высшую любовь (<em>para-prema</em>),</li>
            <li>почтение (<em>gaurava</em>) и ясную веру (<em>prasāda</em>),</li>
            <li>отбросив покровы и омрачения (<em>āvaraṇa-kleśa</em>),</li>
            <li>миновав скверну (<em>mala</em>), —</li>
            <li>слушайте Праджняпарамиту кротких (<em>surata</em>),</li>
            <li>устремлённых к благу мира (<em>jagārtham abhiprasthita</em>),</li>
            <li>ту, в которой действуют герои (<em>śūra</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.2</strong></li>
            <li>Все реки, что текут здесь, в Джамбудвипе,</li>
            <li>взращивая плоды, цветы, целебные травы и деревья,</li>
            <li>опираются на владыку змеев (<em>bhujagendra</em>), повелителя нагов (<em>nāgapati</em>),</li>
            <li>обитающего в озере Анаватапте.<a href="#citation-11" id="ref-11" class="citation-mark"><sup>11</sup></a></li>
            <li>Это сила и слава (<em>anubhāvaśrī</em>) того владыки нагов.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.3</strong></li>
            <li>Сколько бы учений ни излагали ученики Победителя,</li>
            <li>сколько бы согласных с разумом (<em>yuktisahita</em>) объяснений</li>
            <li>ни произносили о действиях,</li>
            <li>ведущих к высшему благу (<em>paramārthasaukhya</em>),</li>
            <li>и о достижении их плода, — всё это сила Татхагаты (<em>puruṣakāra</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.4</strong></li>
            <li>Почему? То, что Победитель преподал как руководство в Дхарме (<em>dharmanetrī</em>),</li>
            <li>те, кто стал учениками Быка среди людей (<em>nararṣabhaśiṣya</em>),</li>
            <li>осваивают на практике (<em>abhiśikṣita</em>).</li>
            <li>Они учат тому, что сами непосредственно постигли (<em>sākṣātkṛtvā</em>) и освоили;</li>
            <li>это происходит благодаря могуществу Будды (<em>buddhānubhāva</em>),</li>
            <li>а не благодаря собственной силе учеников (<em>ātmabala</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.5</strong></li>
            <li>В ней высшая Праджняпарамита не обнаруживается (<em>anupalabdhi</em>);</li>
            <li>не обнаруживается (<em>anupalabdhi</em>) и бодхисаттва,</li>
            <li>не обнаруживается и мысль о пробуждении (<em>cittabodhi</em>).</li>
            <li>Кто, услышав так, не впадает в заблуждение (<em>na ca muhyati</em>)</li>
            <li>и не испытывает страха (<em>nāsti trāsa</em>), —</li>
            <li>тот бодхисаттва практикует мудрость Сугат (<em>sugatānāṃ prajñā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.6</strong></li>
            <li>Ни в форме (<em>rūpa</em>), ни в чувстве (<em>vedanā</em>), ни в распознавании (<em>saṃjñā</em>),</li>
            <li>ни в намерении (<em>cetanā</em>),<a href="#citation-12" id="ref-12" class="citation-mark"><sup>12</sup></a> ни в сознании (<em>vijñāna</em>)</li>
            <li>для него нет места [опоры] (<em>sthāna</em>) даже с пылинку (<em>aṇumātra</em>).</li>
            <li>Не имея опоры ни в одной из дхарм (<em>sarvadharma-asthita</em>),</li>
            <li>странствуя без обители (<em>aniketacārī</em>)</li>
            <li>и ничего не присваивая (<em>aparigṛhīta</em>),<a href="#citation-13" id="ref-13" class="citation-mark"><sup>13</sup></a></li>
            <li>он достигает пробуждения Сугат (<em>sugatānāṃ bodhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.7</strong></li>
            <li>У странствующего отшельника (<em>parivrājaka</em>) Шреники<a href="#citation-14" id="ref-14" class="citation-mark"><sup>14</sup></a></li>
            <li>нет установления знания (<em>jñānopalambha</em>)</li>
            <li>и нет распада скандх (<em>skandhavibhāvanā</em>).</li>
            <li>Так и бодхисаттва, постигающий (<em>parijānāti</em>) дхармы,</li>
            <li>не касается нирваны (<em>na nirvṛtiṃ spṛśati</em>),</li>
            <li>но пребывает в мудрости (<em>prajñām</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.8</strong></li>
            <li>Далее он исследует (<em>vyuparīkṣate</em>):</li>
            <li>что такое эта мудрость (<em>prajñā</em>), чья она и откуда [возникает],</li>
            <li>[видя, что] все эти дхармы шунья (<em>śūnyaka</em>).</li>
            <li>Исследуя так, он не падает духом (<em>na līyati</em>)</li>
            <li>и не знает страха (<em>nāsti trāsa</em>);</li>
            <li>такой бодхисаттва близок (<em>āsanna</em>) к пробуждению (<em>bodhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.9</strong></li>
            <li>Если бодхисаттва практикует в форме (<em>rūpa</em>), распознавании (<em>saṃjñā</em>),</li>
            <li>чувстве (<em>vedanā</em>), намерении (<em>cetanā</em>) и скандхе сознания (<em>vijñāna-skandha</em>),</li>
            <li>не понимая [их] (<em>aprajānamāna</em>), [или] выстраивает понятие (<em>parikalpayi</em>),</li>
            <li>что эти скандхи — шунья, —</li>
            <li>он всё же практикует, [связанный] образами-знаками (<em>nimitta</em>),</li>
            <li>не будучи привязанным (<em>asakta</em>) к состоянию невозникновения (<em>anutpāda-pada</em>).<a href="#citation-15" id="ref-15" class="citation-mark"><sup>15</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.10</strong></li>
            <li>Тот, кто не практикует в форме (<em>rūpa</em>), чувстве (<em>vedanā</em>), распознавании (<em>saṃjñā</em>),</li>
            <li>намерении (<em>cetanā</em>) и сознании (<em>vijñāna</em>), странствуя без обители (<em>aniketacārī</em>),</li>
            <li>не признаёт это практикой (<em>caratīti so na upagacchati</em>);</li>
            <li>опираясь на мудрость (<em>prajñādhārī</em>) и ничего не присваивая (<em>anupādadhī</em>),</li>
            <li>он соприкасается с высшим самадхи покоя (<em>śāntisamādhiśreṣṭhā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.11</strong></li>
            <li>Так пребывая здесь в собственном покое (<em>ātmaśānti</em>),</li>
            <li>бодхисаттва получает предсказание (<em>vyākṛta</em>)</li>
            <li>от прежних Татхагат (<em>pūrvaka tathāgata</em>).</li>
            <li>Он не думает: «я пребываю в самадхи»</li>
            <li>или «я вышел из него» (<em>samādhito vyutthita</em>) —</li>
            <li>ибо он вполне знает природу дхарм (<em>dharmaprakṛti</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.12</strong></li>
            <li>Так практикуя, он практикует мудрость Сугат (<em>sugatānāṃ prajñā</em>).</li>
            <li>Он не обнаруживает (<em>na labhati</em>) дхарм, среди которых практикует;</li>
            <li>поняв практику как не-практику (<em>caraṇaṃ acaraṇaṃ</em>),</li>
            <li>он осуществляет эту практику</li>
            <li>высшей Праджняпарамиты (<em>prajñāvarapāramitāya caryā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.13</strong></li>
            <li>То, чего нет, называется «несуществующим» (<em>avidyamāna</em>);</li>
            <li>глупец (<em>bāla</em>) умозрительно выстраивает понятия (<em>parikalpayati</em>) о нём</li>
            <li>как наличное и отсутствующее.<a href="#citation-16" id="ref-16" class="citation-mark"><sup>16</sup></a></li>
            <li>Наличие и отсутствие — оба суть несуществующие дхармы (<em>asanta dharma</em>);</li>
            <li>бодхисаттва, понимающий так, выходит [за пределы] (<em>niryāti</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.14</strong></li>
            <li>Тот, кто знает пять скандх (<em>pañca-skandha</em>) как подобные иллюзии (<em>māyopama</em>),</li>
            <li>не разделяя иллюзию и скандхи как различное,</li>
            <li>свободен от распознавания многообразия (<em>nānātva-saṃjñā-vigata</em>)</li>
            <li>и пребывает в умиротворении (<em>upaśāntacārin</em>), —</li>
            <li>такова практика высшей парамиты мудрости (<em>prajñā-vara-pāramitā-caryā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.15</strong></li>
            <li>У того, кто обладает благим другом (<em>kalyāṇamitra</em>)</li>
            <li>и обладает прозрением (<em>vipaśyaka</em>),</li>
            <li>не возникнет страха, когда он услышит Мать Победителей (<em>jinānāṃ mātṛ</em>).</li>
            <li>А тот, кто связан с дурным другом (<em>pāpamitra</em>)</li>
            <li>и ведом другими (<em>parapraṇeya</em>), разбивается,</li>
            <li>как необожжённый сосуд (<em>āmabhājana</em>), коснувшийся воды (<em>udakaspṛṣṭa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.16</strong></li>
            <li>Почему же его называют «бодхисаттва»?</li>
            <li>Он желает истощить всякую привязанность (<em>saṅga</em>) и отсечь её (<em>saṅgachedī</em>).</li>
            <li>Он коснётся (<em>spṛśiṣyati</em>) пробуждения Победителей,</li>
            <li>состояния без привязанности (<em>asaṅgabhūta</em>);</li>
            <li>поэтому он и получает имя «бодхисаттва».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.17</strong></li>
            <li>Почему же его называют «великим существом» (<em>mahasattva</em>)?</li>
            <li>Потому что он велик (<em>mahat</em>)</li>
            <li>и поднимается над массами существ (<em>sattvarāśi</em>);</li>
            <li>он отсекает великие неправильные взгляды (<em>dṛṣṭigata</em>)</li>
            <li>в мире существ (<em>sattvadhātu</em>).</li>
            <li>Поэтому его и называют «великим существом».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.18</strong></li>
            <li>Великий щедростью,<a href="#citation-17" id="ref-17" class="citation-mark"><sup>17</sup></a> великий разумом (<em>mahatabuddhi</em>),</li>
            <li>великий могуществом (<em>mahānubhāva</em>),</li>
            <li>взошедший на великую колесницу (<em>mahāyāna</em>)</li>
            <li>и самадхи высших Победителей (<em>uttamajinānāṃ samādhi</em>),</li>
            <li>облачённый в великие доспехи (<em>mahatā sanaddha</em>),</li>
            <li>он сокрушит коварного Намучи (<em>namuci śaṭha</em>).<a href="#citation-18" id="ref-18" class="citation-mark"><sup>18</sup></a></li>
            <li>Поэтому его и называют «великим существом».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.19</strong></li>
            <li>Подобно тому как фокусник (<em>māyākara</em>) на перекрёстке (<em>catuṣpatha</em>),</li>
            <li>сотворив (<em>nirmiṇitvā</em>) великую толпу,</li>
            <li>отсекает (<em>chindati</em>) десятки миллионов (<em>koṭī</em>) голов,</li>
            <li>так и бодхисаттва, осознавая, что они суть иллюзия (<em>māyā</em>),</li>
            <li>распознаёт (<em>jānati</em>) всех существ и весь мир</li>
            <li>как иллюзорное творение (<em>nirmāṇa</em>) и не испытывает страха (<em>trāsa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.20</strong></li>
            <li>Форма, распознавание, чувство, намерение и сознание</li>
            <li>не связаны и не освобождены.<a href="#citation-19" id="ref-19" class="citation-mark"><sup>19</sup></a></li>
            <li>Не привязываясь (<em>asaṅgabhūta</em>) и не падая духом (<em>na līnacitta</em>),</li>
            <li>[бодхисаттва] продвигается к пробуждению.</li>
            <li>Таковы доспехи (<em>saṃnāha</em>) лучших из людей (<em>varapudgalauttama</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.21</strong></li>
            <li>Почему это называют «колесницей пробуждения» (<em>bodhiyāna</em>)?</li>
            <li>Взойдя на неё (<em>āruhitva</em>), он приводит всех существ к нирване (<em>nirvāpayati</em>).</li>
            <li>Эта колесница подобна пространству (<em>ākāśatulya</em>),</li>
            <li>великому небесному дворцу (<em>mahāvimāna</em>);</li>
            <li>она — лучшая из колесниц (<em>yānaśreṣṭha</em>),</li>
            <li>ведущая к счастью, благу и покою (<em>sukhasaukhyakṣema</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.22</strong></li>
            <li>Невозможно установить (<em>na upalabhyate</em>), в каком направлении он движется,</li>
            <li>достигнув обители нирваны (<em>nirvāṇaokagamana</em>);</li>
            <li>его дальнейший путь (<em>gati</em>) не поддаётся установлению (<em>anupalabdhi</em>).</li>
            <li>Подобно тому как у погасшего огня (<em>agni nirvṛta</em>)</li>
            <li>невозможно обнаружить (<em>na upalabhyate</em>) движение (<em>gatipracāra</em>),</li>
            <li>так и по этой причине его именуют «угасшим» (<em>nirvṛti</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.23</strong></li>
            <li>Бодхисаттва не обнаруживается (<em>na upalabhyate</em>) ни в прошлом (<em>pūrvānta</em>),</li>
            <li>ни в будущем (<em>aparānta</em>), ни в настоящем (<em>pratyutpanna</em>).</li>
            <li>Он чист в трёх временах (<em>triyadhvaśuddha</em>),</li>
            <li>необусловлен<a href="#citation-20" id="ref-20" class="citation-mark"><sup>20</sup></a> и свободен от разрастания умопостроений (<em>niṣprapañca</em>).</li>
            <li>Это и есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.24</strong></li>
            <li>Когда в какое-либо время мудрый (<em>vidu</em>) бодхисаттва, так практикуя,</li>
            <li>размышляет о не-возникновении (<em>anupāda</em>),</li>
            <li>он порождает (<em>janeti</em>) великое сострадание (<em>karuṇā</em>),</li>
            <li>свободное от распознавания существ (<em>sattvasaṃjñā</em>)</li>
            <li>Это и есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.25</strong></li>
            <li>Если у него порождается (<em>upādayati</em>) распознавание существа и</li>
            <li>распознавание страдания (<em>dukhasaṃjñā</em>), и он думает:</li>
            <li>«Я устраню страдание, я принесу пользу миру», —</li>
            <li>такой бодхисаттва выстраивает понятия (<em>parikalpaka</em>) «себя» и «существ»;</li>
            <li>это не есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.26</strong></li>
            <li>Как [он понимает] себя, так понимает и всех существ (<em>sarvasattva</em>);</li>
            <li>как всех существ, так понимает и все дхармы (<em>sarvadharma</em>).</li>
            <li>Не-возникновение и возникновение (<em>anupāda-upāda</em>)</li>
            <li>он не различает как два (<em>avikalpamāna</em>).</li>
            <li>Это и есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.27</strong></li>
            <li>Сколько бы имён дхарм (<em>dharmanāma</em>) ни провозглашалось в мире,</li>
            <li>все они превзойдены и оставлены позади</li>
            <li>вместе с возникновением (<em>upāda</em>).</li>
            <li>Достигается бессмертное (<em>amṛta</em>) высшее знание (<em>jñāna</em>), иного нет.</li>
            <li>Поэтому единый смысл мудрости (<em>ekārtha prajñā</em>) —</li>
            <li>это и есть имя «парамита».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_1.28</strong></li>
            <li>Так практикуя, бодхисаттва не сомневается (<em>na kāṅkṣati</em>);</li>
            <li>его следует знать как пребывающего с мудростью</li>
            <li>и искусными средствами (<em>upāyaprajña</em>).</li>
            <li>Он понимает, что дхармы</li>
            <li>лишены собственной природы (<em>prakṛty-asanta</em>).</li>
            <li>Это и есть практика высшей Праджняпарамиты.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается первая глава, именуемая «Практика знания всех аспектов» (<em>Sarvākārajñātācaryāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 2 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 2. Шакра (<em>śakraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.1</strong></li>
            <li>Кто не утверждается в форме (<em>rūpa</em>),</li>
            <li>не утверждается в чувстве (<em>vedanā</em>),</li>
            <li>не утверждается в распознавании (<em>saṃjñā</em>),</li>
            <li>не утверждается в намерении (<em>cetanā</em>),</li>
            <li>кто не утверждается в сознании (<em>vijñāna</em>), —</li>
            <li>он утверждается в дхармате (<em>dharmatā</em>, природе дхарм).</li>
            <li>Он осуществляет эту практику высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.2</strong></li>
            <li>Ни в постоянстве и непостоянстве (<em>nitya-anitya</em>),</li>
            <li>ни в счастье и страдании (<em>sukha-duḥkha</em>),</li>
            <li>ни в прекрасном и безобразном (<em>śubha-aśubha</em>),</li>
            <li>ни в самости и не-самости (<em>ātman-anātman</em>),</li>
            <li>ни в таковости (<em>tathatā</em>), ни в шуньяте он не утверждается (<em>na sthita</em>).</li>
            <li>Не утверждается он и в достижении плода (<em>phala-prāpti</em>):</li>
            <li>ни на ступени архата (<em>arhat-bhūmi</em>), ни на ступени пратьекабудды (<em>pratyeka-bhūmi</em>),</li>
            <li>ни на ступени будды (<em>buddha-bhūmi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.3</strong></li>
            <li>Как Наставник (<em>nāyaka</em>) не пребывает (<em>asthitaka</em>)</li>
            <li>в сфере несоставного (<em>asaṃskṛta-dhātu</em>),</li>
            <li>так и в составном (<em>saṃskṛta</em>) он не пребывает (<em>athita</em>),</li>
            <li>странствуя без обители (<em>aniketacārī</em>).</li>
            <li>Так и бодхисаттва пребывает (<em>sthita</em>), не имея опоры (<em>sthānu athita</em>);</li>
            <li>это пребывание без опоры (<em>asthānu sthānu</em>)</li>
            <li>Победитель назвал пребыванием (<em>sthāna</em>).<a href="#citation-21" id="ref-21" class="citation-mark"><sup>21</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.4</strong></li>
            <li>Кто желает: «Да стану я учеником Сугаты (<em>sugata-śrāvaka</em>),</li>
            <li>да стану я пратьекабуддой или царём Дхармы (<em>dharma-rāja</em>)», —</li>
            <li>не сможет достичь [этого], не достигнув этого терпения (<em>kṣānti</em>).<a href="#citation-22" id="ref-22" class="citation-mark"><sup>22</sup></a></li>
            <li>Подобно тому как невозможно переправиться</li>
            <li>с ближнего берега на дальний (<em>āra-pāra-gamana</em>),</li>
            <li>не видя пред собою берегов (<em>atītadarśī</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.5</strong></li>
            <li>Тот, кто преподаёт Дхарму (<em>dharma-bhāṣyati</em>),</li>
            <li>тот, кто слушает её изложение (<em>bhāṣyamāṇam</em>),</li>
            <li>достигший плода (<em>phalaprāpta</em>), пратьекабудда (<em>pratyayajina</em>)</li>
            <li>и Защитник мира (<em>loka-nātha</em>),</li>
            <li>а также нирвана, достигнутая мудрыми и учёными (<em>vidu-paṇḍita</em>), —</li>
            <li>всё это Татхагата показал как иллюзорное.<a href="#citation-23" id="ref-23" class="citation-mark"><sup>23</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.6</strong></li>
            <li>Четыре вида личностей (<em>pudgala</em>) не устрашаются этого:</li>
            <li>сын Победителя (<em>jina-putra</em>), сведущий в истине (<em>satya-kuśala</em>);</li>
            <li>невозвратный (<em>avivartiya</em>); архат (<em>arhat</em>),</li>
            <li>стряхнувший скверну клеш (<em>mala-kleśa</em>)</li>
            <li>и отбросивший сомнение (<em>prahīṇa-kāṅkṣa</em>);</li>
            <li>и четвёртый — созревший</li>
            <li>благодаря благому другу (<em>kalyāṇamitra-paripācita</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.7</strong></li>
            <li>Так практикуя, мудрый и учёный (<em>vidu-paṇḍita</em>) бодхисаттва</li>
            <li>не обучается на уровне архата или пратьекабудды,</li>
            <li>но осваивает дхармы Будды (<em>buddha-dharma</em>)</li>
            <li>ради всеведения (<em>sarvajñatā</em>).</li>
            <li>Он не обучается ни обучению, ни не-обучению (<em>śikṣā-aśikṣā</em>), —</li>
            <li>таково его обучение.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.8</strong></li>
            <li>Он обучается не ради схватывания возрастания</li>
            <li>или убывания формы (<em>rūpa-vṛddhi-parihāṇi-parigraha</em>)<a href="#citation-24" id="ref-24" class="citation-mark"><sup>24</sup></a></li>
            <li>и не ради схватывания разнообразных дхарм (<em>vividha-dharma-parigraha</em>).<a href="#citation-25" id="ref-25" class="citation-mark"><sup>25</sup></a></li>
            <li>Обучаясь, он обретает всеведение (<em>sarvajñatāṃ parigṛhṇāti</em>)<a href="#citation-26" id="ref-26" class="citation-mark"><sup>26</sup></a></li>
            <li>и вступает на путь выхода (<em>niryāyati</em>).<a href="#citation-27" id="ref-27" class="citation-mark"><sup>27</sup></a></li>
            <li>Таково обучение тех, кто радуется качествам (<em>guṇe ratānām</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.9</strong></li>
            <li>Форма не есть мудрость (<em>prajñā</em>), и в форме нет мудрости.</li>
            <li>Сознание (<em>vijñāna</em>), распознавание (<em>saṃjñā</em>),</li>
            <li>чувство (<em>vedanā</em>) и намерение (<em>cetanā</em>) —</li>
            <li>они не есть мудрость, и мудрости в них нет.</li>
            <li>Мудрость подобна сфере пространства (<em>ākāśa-dhātu</em>);</li>
            <li>в ней нет различия (<em>bheda</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.10</strong></li>
            <li>Природа (<em>prakṛti</em>) объектов (<em>ārambaṇa</em>) беспредельна (<em>ananta-pārā</em>);</li>
            <li>природа существ (<em>sattva</em>) беспредельна;</li>
            <li>природа сферы пространства (<em>ākāśa-dhātu</em>) беспредельна;</li>
            <li>мудрость (<em>prajñā</em>) знающих мир (<em>loka-vidu</em>) также беспредельна.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.11</strong></li>
            <li>«Распознавание» (<em>saṃjñā</em>) Наставник [существ] (<em>nāyaka</em>)</li>
            <li>провозгласил лишь именем (<em>nāma</em>).</li>
            <li>Устранив распознавание (<em>saṃjñāṃ vibhāviya</em>),</li>
            <li>через оставление (<em>prahāṇa</em>) идут к тому берегу (<em>pāra</em>).</li>
            <li>Те, кто здесь достигает прекращения распознавания (<em>saṃjñā-vigama</em>),</li>
            <li>достигнув того берега, пребывают в парамите-совершенстве (<em>pāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.12</strong></li>
            <li>Если бы Наставник [существ] провозглашал слово «существо» (<em>sattva</em>)</li>
            <li>в течение кальп, равных [числу] песчинок Ганга, —</li>
            <li>как могло бы возникнуть (<em>upāda</em>) существо из этого,</li>
            <li>[если оно] изначально чисто (<em>ādiśuddha</em>)?</li>
            <li>Это и есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_2.13</strong></li>
            <li>Так говорит Победитель (<em>jino bhaṇati</em>),</li>
            <li>чья речь приятна и не вызывает неприятия (<em>apratikūla-bhāṇī</em>):<a href="#citation-28" id="ref-28" class="citation-mark"><sup>28</sup></a></li>
            <li>«Когда я пребывал в этой высшей парамите,</li>
            <li>тогда я получил предсказание</li>
            <li>от Высочайшего из людей прежнего [времени] (<em>parāpuruṣottamena</em>):<a href="#citation-29" id="ref-29" class="citation-mark"><sup>29</sup></a></li>
            <li>"Ты станешь буддой в будущем веке (<em>anāgata-adhvanasmin</em>)"».</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается вторая глава, именуемая «Шакра» (<em>Śakraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 3 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 3. О парамите держания неизмеримых качеств и почитании ступ (<em>aprameyaguṇadhāraṇapāramitāstūpasatkāraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.1</strong></li>
            <li>Кто будет держать и осваивать (<em>grahīṣyati, paryāpuṇāti</em>)</li>
            <li>эту [Праджняпарамиту], в которой странствуют Защитники (<em>nātha</em>), —</li>
            <li>тому не причинят вреда яд, огонь, оружие и вода;</li>
            <li>Мара и воинство Мары (<em>māra-pakṣa</em>) не смогут подступиться к нему (<em>avatāra</em>).<a href="#citation-30" id="ref-30" class="citation-mark"><sup>30</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.2</strong></li>
            <li>Если кто-либо воздвигнет ступы из семи драгоценностей</li>
            <li>в честь Сугаты, ушедшего в паринирвану, и почтит их:</li>
            <li>пусть тысячи коти мировых сфер (<em>kṣetra-sahasra-koṭi</em>)<a href="#citation-31" id="ref-31" class="citation-mark"><sup>31</sup></a></li>
            <li>заполнятся ступами Сугаты, числом равными песчинкам Ганга,</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.3</strong></li>
            <li>и пусть все существа, сколько их ни есть в этих мировых сферах,</li>
            <li>почитают эти ступы божественными цветами,</li>
            <li>превосходными благовониями и мазями</li>
            <li>на протяжении бесчисленных кальп — кальп трёх времён и даже дольше,</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.4</strong></li>
            <li>но если кто-либо запишет в книгу эту Мать Сугат (<em>sugata-mātṛ</em>),</li>
            <li>из которой возникают Предводители,</li>
            <li>обладающие десятью силами (<em>daśabala-vināyaka</em>),</li>
            <li>и станет хранить её, почитая цветами</li>
            <li>и благовонными мазями (<em>puṣpa-vilepana</em>),</li>
            <li>то его заслуга (<em>puṇya</em>) окажется столь велика,</li>
            <li>что заслуга от сооружения ступы и её почитания</li>
            <li>не составит и малой доли (<em>kalā</em>) [от его заслуги].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.5</strong></li>
            <li>Эта Праджняпарамита — великое ве́дение (<em>mahāvidyā</em>)<a href="#citation-32" id="ref-32" class="citation-mark"><sup>32</sup></a></li>
            <li>для живых существ (<em>janānāṃ</em>), умиротворяющее дхармы,</li>
            <li>которые ведут к скорби и страданию (<em>duḥkha-dharma-śoka-śamanī</em>),<a href="#citation-33" id="ref-33" class="citation-mark"><sup>33</sup></a></li>
            <li>в обширной сфере живых существ (<em>pṛthu-sattva-dhātu</em>).</li>
            <li>Те Защитники мира (<em>lokanātha</em>), что были в прошлом</li>
            <li>и [пребывают] в десяти направлениях, изучили это ве́дение (<em>vidyā</em>)</li>
            <li>и [стали] непревзойдёнными царями врачевателей (<em>anuttara-vaidya-rāja</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.6</strong></li>
            <li>Те мудрые (<em>vidu</em>), кто осуществляют здесь практику (<em>cariyā</em>)</li>
            <li>на благо [других] и с состраданием (<em>hita-sānukampā</em>),</li>
            <li>изучив здесь это ве́дение (<em>vidyā</em>), достигнут пробуждения.</li>
            <li>Всё составное счастье (<em>saṃskṛta</em>) и несоставное счастье (<em>asaṃskṛta</em>)</li>
            <li>следует знать как происходящее из неё, [Праджняпарамиты].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.7</strong></li>
            <li>Семена (<em>bīja</em>), рассеянные по земле (<em>prakīrṇa pṛthivī-sthita</em>),</li>
            <li>прорастают, когда складывается</li>
            <li>совокупность необходимых условий (<em>sāmagrī</em>),</li>
            <li>и дают разнообразные ростки (<em>aneka-rūpa</em>).</li>
            <li>Так и все качества пробуждения (<em>bodhi-guṇa</em>)</li>
            <li>и пять парамит произрастают из Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_3.8</strong></li>
            <li>По пути, которым следует царь-чакравартин, следуют</li>
            <li>и семь драгоценностей (<em>sapta ratana</em>), и всё его войско (<em>balakāya</em>).</li>
            <li>Так и все дхармы-качества (<em>sarva-guṇa-dharma</em>)</li>
            <li>собираются вместе на пути Праджняпарамиты Победителей.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается третья глава, именуемая «О парамите держания неизмеримых качеств и почитании ступ» (<em>Aprameyaguṇadhāraṇapāramitāstūpasatkāraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 4 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 4. Восхваление качеств (<em>guṇaparikīrtanaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.1</strong></li>
            <li>Шакра, отвечая на вопрос Победителя, сказал:</li>
            <li>«Если бы земли будд (<em>buddhakṣetra</em>), числом равные песчинкам Ганга,</li>
            <li>были целиком заполнены мощами Победителей (<em>jinadhātu</em>),</li>
            <li>сложенными в груды, я взял бы лишь эту высшую Праджняпарамиту.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.2</strong></li>
            <li>Почему? Я не испытываю неуважения к мощам (<em>śarīra</em>).</li>
            <li>Те, кто взращён мудростью (<em>prajñāparibhāvita</em>), почитают их.<a href="#citation-34" id="ref-34" class="citation-mark"><sup>34</sup></a></li>
            <li>Подобно тому как человек, опирающийся на царя (<em>rājaniśrita</em>),</li>
            <li>получает всяческие почести, так и мощи Будды (<em>buddhadhātu</em>),</li>
            <li>опираясь на Праджняпарамиту, удостаиваются почитания.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.3</strong></li>
            <li>Если в ларце (<em>karaṇḍaka</em>) находится драгоценный камень (<em>maṇiratna</em>),</li>
            <li>наделённый всеми качествами и бесценный (<em>anargha</em>),</li>
            <li>то и сам ларец достоин поклонения.</li>
            <li>Даже когда камень вынут, люди по-прежнему дорожат ларцом (<em>spṛhanti</em>),</li>
            <li>ибо эти качества принадлежат великой драгоценности (<em>mahāratana</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.4</strong></li>
            <li>Так и мощи Победителя, даже после его ухода в нирвану (<em>nirvṛta</em>),</li>
            <li>удостаиваются почитания (<em>pūjā</em>)</li>
            <li>благодаря качествам (<em>guṇa</em>) высшей Праджняпарамиты.</li>
            <li>Поэтому тот, кто желает обрести качества Победителей (<em>jinaguṇa</em>),</li>
            <li>пусть принимает Праджняпарамиту: это и есть освобождение (<em>mokṣa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.5</strong></li>
            <li>Мудрость (<em>prajñā</em>) — предводительница даяния (<em>dāna</em>),</li>
            <li>нравственности (<em>śīla</em>), терпения (<em>kṣānti</em>),</li>
            <li>усердия (<em>vīrya</em>) и созерцания (<em>dhyāna</em>).</li>
            <li>Она сохраняет благие дхармы (<em>kuśaladharma</em>) от утраты</li>
            <li>и единым способом показывает все дхармы (<em>sarvadharma</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.6</strong></li>
            <li>Подобно тому как в Джамбудвипе</li>
            <li>произрастают многие тысячи коти деревьев,</li>
            <li>различных видов и многообразных обликов,</li>
            <li>между их тенями (<em>chāyā</em>) нет никакого различия,</li>
            <li>за исключением того, что при исчислении</li>
            <li>они все именуются «тенями» (<em>chāyāgata-saṃkhyā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_4.7</strong></li>
            <li>Так и эти пять парамит Победителей именуются Праджняпарамитой.</li>
            <li>Когда все они направлены ко всеведению (<em>sarvajñatā</em>),</li>
            <li>все шесть сходятся здесь к единому пути (<em>ekanaya</em>)</li>
            <li>и именуются пробуждением (<em>bodhināmā</em>)».</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается четвёртая глава, именуемая «Восхваление качеств» (<em>Guṇaparikīrtanaparivarta</em>), в Бхагавати «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 5 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 5. О способе заслуги (<em>puṇyaparyāyaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.1</strong></li>
            <li>Если бодхисаттва показывает (<em>pariṇāmayi</em>) форму (<em>rūpa</em>),</li>
            <li>распознавание (<em>saṃjñā</em>), чувство (<em>vedanā</em>), намерение (<em>cetanā</em>)</li>
            <li>и сознание (<em>citta</em>) как непостоянные (<em>anitya</em>),</li>
            <li>он следует ложной [Праджняпарамите] (<em>prativarṇikā</em>), не понимая [этого].</li>
            <li>Ведь сведущий (<em>paṇḍita</em>) никогда не разрушает дхармы (<em>dharma-vināśa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.2</strong></li>
            <li>Там, где не обнаруживается (<em>na upalabdhi</em>)</li>
            <li>ни форма, ни чувство, ни распознавание, ни сознание, ни намерение,</li>
            <li>он познаёт (<em>jānati</em>) все дхармы</li>
            <li>способом невозникновения (<em>anutpāda</em>) и шуньи.<a href="#citation-35" id="ref-35" class="citation-mark"><sup>35</sup></a></li>
            <li>Такова практика (<em>caryā</em>) высшей Праджняпарамиты (<em>prajñāvarapāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.3</strong></li>
            <li>Сколько ни есть существ в мировых сферах (<em>kṣetra</em>),</li>
            <li>числом равных песчинкам Ганга, —</li>
            <li>и пусть кто-либо приведёт всех их к архатству (<em>arahant-vineya</em>);</li>
            <li>но тот, кто запишет эту Праджняпарамиту</li>
            <li>и передаст книгу другому существу,</li>
            <li>обретёт превосходящую заслугу (<em>viśiṣṭa-puṇya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.4</strong></li>
            <li>Почему? Обучившись здесь (<em>iha śikṣita</em>), наилучшие из наставников (<em>vādiśreṣṭha</em>)</li>
            <li>разъясняют здесь все без исключения дхармы</li>
            <li>в [свете] шуньяты.<a href="#citation-36" id="ref-36" class="citation-mark"><sup>36</sup></a></li>
            <li>Услышав её (<em>yāṃ śrutvā</em>), шраваки быстро (<em>śīghram</em>)</li>
            <li>соприкасаются (<em>spṛśanti</em>) с освобождением (<em>vimukti</em>),</li>
            <li>[иные] — с пробуждением пратьекабудд (<em>pratyekabodhi</em>),</li>
            <li>а [третьи] — с пробуждением будд (<em>buddhabodhi</em>).<a href="#citation-37" id="ref-37" class="citation-mark"><sup>37</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.5</strong></li>
            <li>Как без ростка (<em>aṅkura</em>) в мире не возникает (<em>saṃbhava</em>) дерево,</li>
            <li>откуда тогда взяться его ветвям, листьям, цветам и плодам?</li>
            <li>Так и без мысли о пробуждении (<em>bodhicitta</em>)</li>
            <li>в мире не возникает Победитель;</li>
            <li>откуда тогда взяться таким плодам, как Шакра и Брахма,</li>
            <li>и появлению шраваков (<em>śrāvaka-prādurbhāva</em>)?<a href="#citation-38" id="ref-38" class="citation-mark"><sup>38</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.6</strong></li>
            <li>Подобно тому как солнечный диск (<em>ādityamaṇḍala</em>),</li>
            <li>испуская сеть лучей (<em>prabhājāla</em>),</li>
            <li>побуждает существ к деятельности (<em>karmakriyāsu</em>),</li>
            <li>так и мысль о пробуждении (<em>bodhicitta</em>) Знающего мир (<em>lokavid</em>),</li>
            <li>познанная знанием (<em>jñāna</em>), соединяется с совокупностью</li>
            <li>всех качеств Дхарм (<em>sarvaguṇadharma</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.7</strong></li>
            <li>Если бы в озере Анаватапты не было владыки змеев (<em>bhujagādhipa</em>),</li>
            <li>откуда здесь, в Джамбудвипе, взяться течению рек (<em>nadī-prasrava</em>)?</li>
            <li>Без рек не возникли бы плоды и цветы, и в океанах не было бы</li>
            <li>драгоценностей многообразных видов (<em>aneka-rūpa-ratna</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.8</strong></li>
            <li>Так и без мысли о пробуждении Татхагаты</li>
            <li>откуда взяться здесь, во всём мире, течению знания (<em>jñāna-prasrava</em>)?</li>
            <li>Без знания (<em>jñāna</em>) не возрастают (<em>vṛddhi</em>) качества (<em>guṇa</em>),</li>
            <li>нет пробуждения (<em>bodhi</em>) и нет дхарм будды (<em>buddhadharma</em>),</li>
            <li>равных океану (<em>sāgara-sama</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_5.9</strong></li>
            <li>Сколько ни есть в мире светящихся существ (<em>jotika-prāṇabhūta</em>),</li>
            <li>все они излучают сияние (<em>prabhā</em>), чтобы освещать (<em>obhāsana</em>).</li>
            <li>Но даже весь свет (<em>sarva-ābhā</em>) сонма светлячков (<em>jyotika-gaṇa</em>)</li>
            <li>не составит и доли (<em>kalā</em>) одного луча (<em>eka-raśmi</em>),</li>
            <li>исходящего от превосходного солнечного диска (<em>vara-sūrya-maṇḍala</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается пятая глава, именуемая «О способе заслуги» (<em>Puṇyaparyāyaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» Праджняпарамиты (<em>bhagavatyāṃ ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 6 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 6. О сорадовании (<em>Anumodanāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.1</strong></li>
            <li>Сколько бы заслуг (<em>puṇya</em>) ни порождали сонмы шравак</li>
            <li>благодаря даянию (<em>dāna</em>), нравственности (<em>śīla</em>) и взращиванию (<em>bhāvanā</em>),<a href="#citation-39" id="ref-39" class="citation-mark"><sup>39</sup></a> —</li>
            <li>если бодхисаттва одним помыслом (<em>ekacitta</em>) сорадуется (<em>anumodana</em>),<a href="#citation-40" id="ref-40" class="citation-mark"><sup>40</sup></a></li>
            <li>то вся совокупность заслуг (<em>puṇyaskandha</em>) сонмов шравак</li>
            <li>не составит и доли его [заслуг].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.2</strong></li>
            <li>Сколько бы коти-ниют (<em>koṭi-niyuta</em>)<a href="#citation-41" id="ref-41" class="citation-mark"><sup>41</sup></a> будд ни ушло в прошлом (<em>purimā vyatītā</em>),</li>
            <li>сколько бы Защитников мира (<em>lokanātha</em>) ни пребывало</li>
            <li>в неисчислимых многих тысячах коти мировых сфер (<em>kṣetra</em>)</li>
            <li>и сколько бы ни ушло в паринирвану (<em>parinirvṛta</em>), —</li>
            <li>[все они] проповедуют драгоценную Дхарму (<em>dharmaratna</em>)</li>
            <li>ради полного прекращения страдания (<em>duḥkhasaṃkṣaya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.3</strong></li>
            <li>От первого порождения мысли (<em>cittotpāda</em>)</li>
            <li>о высшем пробуждении (<em>varabodhi</em>) и вплоть до времени</li>
            <li>угасания Дхармы (<em>dharmakṣayakāla</em>) Усмирителей (<em>vināyaka</em>) —</li>
            <li>заслуга всех тех Победителей, собранная воедино (<em>ciya</em>),</li>
            <li>вместе с парамитами и дхармами будды, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.4</strong></li>
            <li>и заслуги сынов будд (<em>buddhatanaya</em>) и шравак —</li>
            <li>обучающихся (<em>śaikṣa</em>) и завершивших обучение (<em>aśaikṣa</em>),</li>
            <li>благое омрачённое (<em>sāsrava</em>) и неомрачённое (<em>anāsrava</em>), —</li>
            <li>всему этому бодхисаттва, собрав воедино (<em>paripiṇḍayitva</em>),</li>
            <li>сорадуется (<em>anumodayi</em>) и посвящает (<em>nāmayi</em>) пробуждению (<em>bodhi</em>),</li>
            <li>ради блага мира (<em>jagārthanidāna</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.5</strong></li>
            <li>Если при посвящении (<em>pariṇāmanā</em>)<a href="#citation-42" id="ref-42" class="citation-mark"><sup>42</sup></a> возникает распознавание мысли (<em>cittasaṃjñā</em>)</li>
            <li>или если посвящение бодхисаттвы сопровождается</li>
            <li>распознаванием существа (<em>sattvasaṃjñā</em>),</li>
            <li>то [ум] пребывает в распознавании (<em>saṃjñā</em>), воззрении (<em>dṛṣṭi</em>) и мысли (<em>citta</em>),</li>
            <li>будучи связан тройной привязанностью (<em>trisaṅgayukta</em>).<a href="#citation-43" id="ref-43" class="citation-mark"><sup>43</sup></a></li>
            <li>Такое посвящение не является подлинным,</li>
            <li>пока оно обнаруживается [как доступное схватыванию] (<em>upalabhyamāna</em>).<a href="#citation-44" id="ref-44" class="citation-mark"><sup>44</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.6</strong></li>
            <li>Если же он знает так:</li>
            <li>«Эти дхармы прекратились (<em>nirudhyati</em>) и исчерпаны (<em>kṣīṇa</em>);<a href="#citation-45" id="ref-45" class="citation-mark"><sup>45</sup></a></li>
            <li>исчерпано и то, куда (чему) они посвящаются (<em>pariṇāmayiṣyanti</em>);</li>
            <li>дхарма никогда не посвящает дхарме (<em>dharma / dharmin</em>)», —</li>
            <li>то при таком понимании (<em>prajānamāna</em>)</li>
            <li>посвящение действительно совершается.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.7</strong></li>
            <li>Если он создаёт образ-знак (<em>nimitta</em>), то [такое посвящение] не совершается;</li>
            <li>если же посвящает без образов-знаков (<em>ānimitta</em>),</li>
            <li>то посвящение обращено к пробуждению.</li>
            <li>Как хорошо приготовленная (<em>kriyāpraṇīta</em>) пища,</li>
            <li>смешанная с ядом (<em>viṣasṛṣṭa</em>),<a href="#citation-46" id="ref-46" class="citation-mark"><sup>46</sup></a> [губительна], —</li>
            <li>так, по слову Победителя, [губительно]</li>
            <li>и установление чистых дхарм (<em>śukladharmaupalambha</em>)</li>
            <li>[как доступных схватыванию].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.8</strong></li>
            <li>Поэтому следует обучаться такому посвящению (<em>nāmapariṇāmanā</em>):</li>
            <li>как Победители мудро знают благое (<em>kuśala</em>) — каков его род (<em>jāti</em>),</li>
            <li>каково его происхождение (<em>prabhava</em>) и каков его признак (<em>lakṣaṇa</em>), —</li>
            <li>так и я сорадуюсь (<em>anumodamī</em>) и так посвящаю (<em>pariṇāmayāmi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_6.9</strong></li>
            <li>Так посвящая (<em>pariṇāmayamāna</em>) заслугу пробуждению,</li>
            <li>он не отвергает Будду,<a href="#citation-47" id="ref-47" class="citation-mark"><sup>47</sup></a> следуя словам Победителя (<em>jinauktavādin</em>).</li>
            <li>Сколько ни есть в мире бодхисаттв,</li>
            <li>опирающихся на обнаруживаемое (<em>upalambhika</em>),<a href="#citation-48" id="ref-48" class="citation-mark"><sup>48</sup></a> —</li>
            <li>всех их превосходит (<em>abhibhonti</em>) герой (<em>śūra</em>),</li>
            <li>совершающий посвящение таким образом.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается шестая глава, именуемая «О сорадовании» (<em>Anumodanāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 7 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 7. Об аде (<em>nirayaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.1</strong></li>
            <li>Коти-ниют (<em>koṭi-niyuta</em>) слепорождённых, без проводника,</li>
            <li>не знающих пути, — разве найдут вход в город?</li>
            <li>Так и эти пять парамит без мудрости (<em>prajñā</em>) — безглазы;</li>
            <li>без проводника они не способны достичь пробуждения.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.2</strong></li>
            <li>Только когда они охвачены мудростью (<em>pragṛhīta prajñā</em>),</li>
            <li>они обретают глаз (<em>labdhacakṣu</em>) — и [лишь тогда]</li>
            <li>получают это наименование [«парамита»].</li>
            <li>Это подобно завершённой живописи (<em>citrakarma-pariniṣṭhita</em>),</li>
            <li>которая, будучи без прорисовки глаз (<em>cakṣuhīno</em>),</li>
            <li>не приносит [художнику] награды (<em>puṇya</em>),<a href="#citation-49" id="ref-49" class="citation-mark"><sup>49</sup></a></li>
            <li>пока [он] не прорисовал глаза (<em>akaritva cakṣuḥ</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.3</strong></li>
            <li>Когда, исследуя посредством мудрости (<em>prajñā vibhāvamāna</em>),</li>
            <li>он не обнаруживает (<em>no labhati</em>) ни малейшей дхармы (<em>aṇumātra dharma</em>) —</li>
            <li>составной или несоставной (<em>saṃskṛta-asaṃskṛta</em>),</li>
            <li>тёмной или светлой (<em>kṛṣṇa-śukla</em>), —</li>
            <li>тогда в мире начинают говорить о Праджняпарамите,<a href="#citation-50" id="ref-50" class="citation-mark"><sup>50</sup></a></li>
            <li>[она подобна] пространству (<em>ākāśa</em>), где ничто не утверждено (<em>na pratiṣṭhita</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.4</strong></li>
            <li>Если он думает: «Я практикую мудрость (<em>prajñā</em>) Победителей,</li>
            <li>я освобожу ниюты существ, поражённых многими болезнями», —</li>
            <li>этот бодхисаттва умозрительно выстраивает</li>
            <li>распознавание существа (<em>sattvasaṃjñā</em>),</li>
            <li>и это не есть практика высшей Праджняпарамиты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.5</strong></li>
            <li>Тот бодхисаттва, кто осуществлял эту высшую парамиту,</li>
            <li>когда в прошлом совершал служение (<em>paricārikā</em>), —</li>
            <li>мудр и не сомневается.</li>
            <li>Услышав [её], он вновь обретёт распознавание Учителя (<em>śāstṛsaṃjñā</em>)</li>
            <li>и скоро постигнет спокойное пробуждение (<em>bodhi śāntā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.6</strong></li>
            <li>Хотя прежде почтительно служил ниютам будд,</li>
            <li>если он не имеет веры в Праджняпарамиту Победителей, —</li>
            <li>услышав [её], он, скудоумный, отбросит её;</li>
            <li>отбросив, он пойдёт в Авичи и не найдёт прибежища.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_7.7</strong></li>
            <li>Поэтому верьте в эту Мать Победителей (<em>jināna mātā</em>),</li>
            <li>если вы желаете достичь высшего знания будды (<em>uttamabuddhajñāna</em>).</li>
            <li>Не будьте как тот купец, который,</li>
            <li>отправившись на остров сокровищ (<em>ratnadvīpa</em>)</li>
            <li>и потеряв свой товар, вернулся [ни с чем].</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается седьмая глава, именуемая «Об аде» (<em>Nirayaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 8 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 8. О чистоте (<em>viśuddhiparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_8.1</strong></li>
            <li>Чистоту формы (<em>rūpaśuddhi</em>) следует знать как чистоту плода (<em>phalaśuddhi</em>).</li>
            <li>Чистоту плода и формы называют чистотой всеведения (<em>sarvajñatāśuddhi</em>).</li>
            <li>Чистота всеведения, чистота плода и чистота формы</li>
            <li>равны пространству (<em>ākāśadhātusamatā</em>):</li>
            <li>они нераздельны и нерассекаемы (<em>abhinnachinnāḥ</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_8.2</strong></li>
            <li>Бодхисаттвы, вышедшие за пределы трёх миров (<em>traidhātuka</em>),</li>
            <li>но не [пребывающие] в освобождении,<a href="#citation-51" id="ref-51" class="citation-mark"><sup>51</sup></a></li>
            <li>хотя омрачения (<em>kleśa</em>) устранены, являют рождение (<em>upapatti</em>);</li>
            <li>хотя они свободны от старости, болезни и смерти, являют кончину (<em>cyuti</em>) —</li>
            <li>в Праджняпарамите, где практикуют мудрые (<em>dhīra</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_8.3</strong></li>
            <li>Этот мир привязан к тине (<em>paṅka</em>) имени и формы (<em>nāma-rūpa</em>)</li>
            <li>и кружится в колесе сансары (<em>saṃsāracakra</em>),</li>
            <li>подобном колесу ветра (<em>anilacakra</em>).</li>
            <li>Познав заблуждающийся мир как сеть для оленей (<em>mṛgavāgura</em>),</li>
            <li>мудрые (<em>prajñāḥ</em>) странствуют, подобно птицам в пространстве.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_8.4</strong></li>
            <li>Тот, кто совершенно чисто практикует (<em>pariśuddhacārī</em>)</li>
            <li>и не практикует ни в форме (<em>rūpa</em>), ни в сознании (<em>vijñāna</em>),</li>
            <li>ни в распознавании (<em>saṃjñā</em>), ни в чувстве (<em>vedanā</em>), ни в намерении (<em>cetanā</em>), —</li>
            <li>так практикуя, он оставляет все привязанности (<em>sarvasaṅga</em>);</li>
            <li>освободившись от привязанности, он практикует мудрость (<em>prajñā</em>) Сугат.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается восьмая глава, именуемая «О чистоте» (<em>Viśuddhiparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 9 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 9. О восхвалении (<em>stutiparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_9.1</strong></li>
            <li>Так практикуя, мудрый и учёный (<em>vidu-paṇḍita</em>) бодхисаттва,</li>
            <li>отсёкши привязанности (<em>saṅga</em>), странствует в мире необременённым (<em>asakta</em>),</li>
            <li>ярко сияя, подобно солнцу (<em>sūrya</em>),</li>
            <li>освободившемуся от захвата Раху (<em>rāhugrahamukta</em>),</li>
            <li>или подобно пылающему огню,</li>
            <li>сжигающему траву, хворост и лес (<em>tṛṇakāṣṭhavana</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_9.2</strong></li>
            <li>Бодхисаттва видит (<em>paśyati</em>), что все дхармы и Праджняпарамита<a href="#citation-52" id="ref-52" class="citation-mark"><sup>52</sup></a></li>
            <li>чисты по природе и всецело чисты (<em>prakṛtīya śuddha pariśuddhimi</em>);</li>
            <li>он не обнаруживает (<em>na labhati</em>) ни видящего (<em>paśyaka</em>),<a href="#citation-53" id="ref-53" class="citation-mark"><sup>53</sup></a></li>
            <li>ни самих дхарм.</li>
            <li>Это и есть практика (<em>caryā</em>) высшей Праджняпарамиты.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается девятая глава, именуемая «О восхвалении» (<em>Stutiparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 10 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 10. О качествах дхарани (<em>Dhāraṇīguṇaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.1</strong></li>
            <li>Шакра, царь богов (<em>devarāja</em>), вопрошает Победителя:</li>
            <li>«Как бодхисаттва, практикуя мудрость (<em>caramāṇa prajñā</em>),</li>
            <li>посвящает себя [этой практике] (<em>yujyati</em>)?»</li>
            <li>«Тот, кто ни в малейшей степени (<em>aṇumātra</em>)</li>
            <li>не вовлекается (<em>na yujyati</em>) в скандхи и дхату (<em>skandha-dhātu</em>), —</li>
            <li>именно тот, кто так посвящает себя [практике] (<em>yujyati</em>),</li>
            <li>и есть бодхисаттва».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.2</strong></li>
            <li>Следует знать (<em>vedayitavya</em>), что это существо</li>
            <li>давно вступило на великую колесницу</li>
            <li>и совершило служение при многих коти-ниютах будд.</li>
            <li>Услышав, что эти дхармы</li>
            <li>подобны магическим творениям и иллюзии (<em>nirmitamāyakalpa</em>),</li>
            <li>оно не испытывает сомнений и, обучаясь (<em>śikṣamāṇaḥ</em>),</li>
            <li>усердно посвящает себя практике (<em>prayujyati</em>).<a href="#citation-54" id="ref-54" class="citation-mark"><sup>54</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.3</strong></li>
            <li>Человек, идущий по пустынной дороге на протяжении многих йоджан,<a href="#citation-55" id="ref-55" class="citation-mark"><sup>55</sup></a></li>
            <li>увидев пастухов (<em>gopāla</em>), пограничные межи (<em>sīmā</em>)</li>
            <li>и богатые лесные угодья (<em>vana-saṃpad</em>), переводит дыхание</li>
            <li>и у него не остаётся страха [перед разбойниками]:<a href="#citation-56" id="ref-56" class="citation-mark"><sup>56</sup></a></li>
            <li>ведь это признаки (<em>nimitta</em>) близости деревни или города.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.4</strong></li>
            <li>Точно так же тот, кто, ища пробуждения</li>
            <li>услышав эту высшую Праджняпарамиту Победителей,<a href="#citation-57" id="ref-57" class="citation-mark"><sup>57</sup></a></li>
            <li>переводит дыхание и больше не испытывает страха —</li>
            <li>ни перед ступенью архата,</li>
            <li>ни перед ступенью пратьекабудды.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.5</strong></li>
            <li>Подобно человеку, который отправился посмотреть</li>
            <li>на воды великого океана (<em>sāgarajala</em>),</li>
            <li>если он ещё видит деревья, лес и горы, то океан далеко;</li>
            <li>когда же эти знаки (<em>nimitta</em>) перестают быть видны,</li>
            <li>он освобождается от сомнения и понимает:</li>
            <li>«Великий океан близко, он совсем недалеко».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.6</strong></li>
            <li>Так же следует знать о том,</li>
            <li>кто устремился к высшему пробуждению (<em>bodhivaraprasthita</em>):</li>
            <li>слушая эту Праджняпарамиту Победителей, —</li>
            <li>хотя Наставник (<em>nāyaka</em>) ещё не предсказал ему</li>
            <li>пробуждение лично (<em>saṃmukha vyākṛta</em>), —</li>
            <li>он вскоре достигнет пробуждения будды.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.7</strong></li>
            <li>В прекрасную весеннюю пору (<em>suvasanti kāli</em>),</li>
            <li>когда появились травы, листья и ветви,<a href="#citation-58" id="ref-58" class="citation-mark"><sup>58</sup></a></li>
            <li>вскоре появляются листья, плоды и цветы.</li>
            <li>Так и тот, кто получил в руки эту Праджняпарамиту,</li>
            <li>вскоре достигнет высшего пробуждения Наставников.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.8</strong></li>
            <li>Подобно тому как следует знать, что для беременной женщины (<em>gurvī</em>),</li>
            <li>испытывающей боли (<em>vedanā</em>), наступило время родов (<em>prajāyanakāla</em>),</li>
            <li>так и бодхисаттва, услышав мудрость (<em>prajñā</em>) Победителей</li>
            <li>и взирая на неё с радостью (<em>rati</em>) и устремлённостью (<em>chanda</em>),</li>
            <li>вскоре (<em>śīghram</em>) достигнет пробуждения.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.9</strong></li>
            <li>Когда йогин, практикуя высшую Праджняпарамиту, не видит (<em>na ... paśyati</em>)</li>
            <li>ни возрастания формы (<em>rūpavṛddhi</em>), ни её убывания (<em>pārihāṇi</em>),</li>
            <li>не видит (<em>[na] paśyati</em>)<a href="#citation-59" id="ref-59" class="citation-mark"><sup>59</sup></a> ни дхарм (<em>dharma</em>), ни не-дхарм (<em>adharma</em>),</li>
            <li>ни сферы Дхармы (<em>dharmadhātu</em>) и не касается нирваны (<em>nirvṛti</em>), —</li>
            <li>тогда он пребывает (<em>viharāti</em>) в мудрости (<em>prajñā</em>).<a href="#citation-60" id="ref-60" class="citation-mark"><sup>60</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_10.10</strong></li>
            <li>Тот, кто, практикуя здесь, не выстраивает в понятиях (<em>kalpayi</em>)</li>
            <li>дхармы будды, силы (<em>bala</em>), основы сверхобычных способностей (<em>ṛddhipāda</em>)</li>
            <li>и спокойное пробуждение (<em>bodhi śāntā</em>), —</li>
            <li>не-различающий (<em>avikalpa</em>), свободный от умопостроений (<em>kalpavigata</em>),</li>
            <li>он практикует при благословляющей поддержке (<em>adhiṣṭhāna</em>).</li>
            <li>Такова практика (<em>caryā</em>) высшей Праджняпарамиты.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается десятая глава, именуемая «О качествах дхарани» (<em>Dhāraṇīguṇaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 11 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 11. О делах Мары (<em>mārakarmaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.1</strong></li>
            <li>Субхути вопрошает Будду, Луну среди говорящих (<em>vādicandra</em>):<a href="#citation-61" id="ref-61" class="citation-mark"><sup>61</sup></a></li>
            <li>«Сколько препятствий (<em>antarāya</em>) возникнет</li>
            <li>для тех, кто радуется качествам (<em>guṇe ratānām</em>)?»</li>
            <li>— «Много будет препятствий, — говорит Учитель (<em>śāstṛ</em>), —</li>
            <li>но из них я возвещу лишь малую часть (<em>alpamātra</em>)».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.2</strong></li>
            <li>Когда переписывается (<em>likhamāna</em>) эта Праджняпарамита Победителей,</li>
            <li>будут возникать (<em>upapadyiṣyanti</em>) многочисленные и разнообразные</li>
            <li>вспышки красноречия и находчивости (<em>pratibhāna</em>);<a href="#citation-62" id="ref-62" class="citation-mark"><sup>62</sup></a></li>
            <li>однако эти [вспышки] быстро угасают (<em>parihāyiṣyanti</em>),</li>
            <li>подобно молнии, не принеся пользы (<em>artha</em>) миру.</li>
            <li>Это деяние Мары (<em>mārakarma</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.3</strong></li>
            <li>Некоторые (<em>keṣaci</em>) испытают сомнение (<em>kāṅkṣā</em>)</li>
            <li>во время изложения учения (<em>bhāṣamāṇe</em>):</li>
            <li>«Наставник (<em>nāyaka</em>) не назвал здесь моего имени (<em>nāma</em>),</li>
            <li>не назвал ни моего рождения (<em>jāti</em>),</li>
            <li>ни места [рождения] (<em>bhūmi</em>), ни рода (<em>gotra</em>)».</li>
            <li>Из-за этого они не станут слушать (<em>na śruṇiṣyati</em>)</li>
            <li>и отвергнут [учение] (<em>kṣipiṣyanti</em>).</li>
            <li>Это деяние Мары.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.4</strong></li>
            <li>Так они, неразумные (<em>ajānamāna</em>), оставив корень (<em>mūla</em>),</li>
            <li>в заблуждении (<em>mūḍha</em>) станут искать ветви и листья (<em>śākhāpalāśa</em>);</li>
            <li>как тот, кто нашёл слона,<a href="#citation-63" id="ref-63" class="citation-mark"><sup>63</sup></a> ищет след слона,</li>
            <li>так и тот, кто услышал Праджняпарамиту, ищет [другие] сутры.<a href="#citation-64" id="ref-64" class="citation-mark"><sup>64</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.5</strong></li>
            <li>Подобно тому как кто-нибудь, обретя пищу ста вкусов (<em>śatarasa</em>)</li>
            <li>и лучшее из блюд (<em>bhojanāgrya</em>), искал бы простую пищу,<a href="#citation-65" id="ref-65" class="citation-mark"><sup>65</sup></a></li>
            <li>так и бодхисаттва, обретя эту парамиту,</li>
            <li>стал бы искать пробуждения на ступени архата.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.6</strong></li>
            <li>Желая почестей (<em>satkārakāma</em>) и приобретений (<em>lābhakāma</em>),</li>
            <li>с умом, полным ожиданий (<em>sāpekṣacitta</em>),</li>
            <li>связанные близкими отношениями с семьями,</li>
            <li>они оставят Дхарму и станут совершать недолжные деяния.</li>
            <li>Покинув путь, они свернут на ложную стезю.</li>
            <li>Это деяние Мары.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.7</strong></li>
            <li>Когда те, кто в это время (<em>tasmiṃ samaye</em>)</li>
            <li>породит стремление (<em>chandika</em>) и веру (<em>śraddhā</em>),</li>
            <li>желая услышать эту высшую Дхарму (<em>dharmaśreṣṭha</em>),</li>
            <li>узнав, что проповедник Дхармы (<em>dharmabhāṇaka</em>)</li>
            <li>занят [другим] делом (<em>kāryayukta</em>),<a href="#citation-66" id="ref-66" class="citation-mark"><sup>66</sup></a></li>
            <li>уйдут, лишённые радости и глубоко опечаленные, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.8</strong></li>
            <li>это и будут деяния Мары, которые проявятся в то время,</li>
            <li>а также многие другие разнообразные</li>
            <li>и многочисленные препятствия (<em>antarāya</em>).</li>
            <li>Будучи ими смущены, многие монахи там</li>
            <li>не смогут удерживать эту Праджняпарамиту.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.9</strong></li>
            <li>Как те драгоценности (<em>ratna</em>), что бесценны (<em>anargha</em>), труднодоступны (<em>durlabha</em>)</li>
            <li>и всегда имеют многих противников (<em>bahu-pratyarthika</em>), —</li>
            <li>так и эта мудрость (<em>prajñā</em>), высшая парамита (<em>vara-pāramitā</em>) Победителей,</li>
            <li>является труднодоступной драгоценностью Дхармы,</li>
            <li>[сопряжённой] со многими препятствиями (<em>upadrava</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_11.10</strong></li>
            <li>Когда существо, недавно вступившее на колесницу (<em>navayānaprasthita</em>)</li>
            <li>и обладающее ограниченным разумом (<em>parīttabuddhi</em>),</li>
            <li>обретает (<em>parāpuṇanti</em>)<a href="#citation-67" id="ref-67" class="citation-mark"><sup>67</sup></a> эту труднодоступную</li>
            <li>драгоценность Дхармы (<em>durlabha-dharmaratna</em>),</li>
            <li>Мара будет ревностно (<em>utsuka</em>) чинить ему препятствия (<em>antarāya</em>).</li>
            <li>Но будды десяти направлений</li>
            <li>будут оказывать ему поддержку (<em>parigrahasaṃprayuktāḥ</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается одиннадцатая глава, именуемая «О делах Мары» (<em>Mārakarmaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 12 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 12. Раскрытие мира (<em>Lokasaṃdarśanaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.1</strong></li>
            <li>Если мать, имеющая много сыновей, заболевает,</li>
            <li>все они, опечаленные, стали бы заботиться о ней.</li>
            <li>Так и будды в мирах десяти направлений</li>
            <li>помышляют об этой Праджняпарамите как о матери.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.2</strong></li>
            <li>Те, кто был в прошлом (<em>atīta</em>), и те Защитники мира,</li>
            <li>что пребывают в десяти направлениях, —</li>
            <li>все они произошли (<em>prasūta</em>) от неё,</li>
            <li>и будущие (<em>anāgata</em>) [тоже произойдут от неё].</li>
            <li>Она — раскрывающая мир (<em>lokasya darśikā</em>), родительница (<em>janetrī</em>),</li>
            <li>мать Победителей, и она раскрывает (<em>nidarśitā</em>)</li>
            <li>образ мыслей и склонности ума (<em>citta-carita</em>) других существ.<a href="#citation-68" id="ref-68" class="citation-mark"><sup>68</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.3</strong></li>
            <li>Таковость мира (<em>lokasya tathatā</em>), таковость архатов (<em>tathatārhat</em>),</li>
            <li>таковость пратьекабудд (<em>pratyekabuddhatathatā</em>),</li>
            <li>таковость Победителей (<em>tathatā jinānām</em>) —</li>
            <li>это одна-единственная таковость (<em>ekaiva tathatā</em>),</li>
            <li>свободная от бытия (<em>bhāvavigatā</em>) и неизменная (<em>ananyā</em>).</li>
            <li>Праджняпарамита познана Татхагатой как эта единая таковость.<a href="#citation-69" id="ref-69" class="citation-mark"><sup>69</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.4</strong></li>
            <li>Пребывают ли (<em>tiṣṭhantu</em>) знающие мир (<em>lokavid</em>) [в мире]</li>
            <li>или ушли в паринирвану (<em>parinirvṛta</em>), —</li>
            <li>этот установленный порядок дхарматы (<em>dharmatā-niyāma</em>)</li>
            <li>остаётся неизменным: «дхармы — шунья» (<em>śūnya-dharma</em>).</li>
            <li>Эту таковость (<em>tathatā</em>) постигают (<em>anubudhyanti</em>) бодхисаттвы;</li>
            <li>поэтому будды получили имя «Татхагата» (<em>tathāgata</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.5</strong></li>
            <li>Это — сфера (<em>gocara</em>) Предводителей,</li>
            <li>обладающих десятью силами (<em>daśabalāna vināyakānām</em>),</li>
            <li>пребывающих в отрадном лесу (<em>ramyavana</em>) Праджняпарамиты.</li>
            <li>Они вызволяют страдающих существ (<em>duḥkhita-sattva</em>)</li>
            <li>от трёх неблагих уделов (<em>tri-apāya</em>),</li>
            <li>но распознавание существа (<em>sattva-saṃjñā</em>) никогда не возникает у них.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.6</strong></li>
            <li>Как лев (<em>siṃha</em>), находясь в горной пещере (<em>girikandara</em>),</li>
            <li>рычит бесстрашно (<em>achambhi</em>), устрашая малых зверей (<em>mṛga-kṣudraka</em>), —</li>
            <li>так и Лев среди людей (<em>narāṇāṃ siṃha</em>),</li>
            <li>найдя опору в Праджняпарамите, рычит бесстрашно,</li>
            <li>устрашая многочисленных приверженцев иных учений (<em>pṛthutīrthika</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.7</strong></li>
            <li>Как лучи солнца (<em>sūryaraśmi</em>), опираясь на пространство (<em>ākāśaniśrita</em>),</li>
            <li>иссушают (<em>tāpeti</em>) эту землю (<em>dharaṇī</em>) и являют (<em>darśayate</em>) формы (<em>rūpa</em>), —</li>
            <li>так и Царь Дхармы, опираясь на Праджняпарамиту (<em>prajñāpāramitāniśrita</em>),</li>
            <li>иссушает (<em>tāpeti</em>) реку жажды (<em>tṛṣṇānadī</em>) и показывает дхарму.<a href="#citation-70" id="ref-70" class="citation-mark"><sup>70</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.8</strong></li>
            <li>Где нет видения (<em>adarśana</em>) формы, нет видения чувства,</li>
            <li>нет видения распознавания, нет видения намерения (<em>cetanā</em>),</li>
            <li>где нет видения (<em>anudarśana</em>) сознания, мысли (<em>citta</em>) и ума (<em>manas</em>), —</li>
            <li>то названо (<em>nidiṣṭa</em>) Татхагатой видением дхармы (<em>dharma-darśana</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_12.9</strong></li>
            <li>Существа провозглашают (<em>pravyāharanti</em>):</li>
            <li>«Мы видим пространство (<em>ākāśa-dṛṣṭi</em>)», —</li>
            <li>но как вообще возможно видение неба (<em>nabha-darśana</em>)?</li>
            <li>Обдумайте (<em>vimṛśatha</em>) этот смысл!</li>
            <li>Точно так же и видение дхармы (<em>dharma-darśana</em>)</li>
            <li>провозглашено Татхагатой:</li>
            <li>это видение невозможно выразить (<em>bhaṇitu</em>)</li>
            <li>посредством [внешнего] указания или примера (<em>nidarśana</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двенадцатая глава, именуемая «Раскрытие мира» (<em>Lokasaṃdarśanaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 13 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 13. О непостижимом (<em>acintyaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_13.1</strong></li>
            <li>Кто видит так (<em>eva paśyati</em>), тот видит все дхармы.</li>
            <li>Подобно тому как царь пребывает в равностности (<em>upekṣya</em>),</li>
            <li>[предоставляя] министрам совершать их дела (<em>amātya-kriyā</em>),</li>
            <li>так и Праджняпарамита совершает (<em>karoti</em>)</li>
            <li>все деяния будды (<em>buddha-kriyā</em>) и дхармату шраваков (<em>dharmata śrāvakāṇāṃ</em>).<a href="#citation-71" id="ref-71" class="citation-mark"><sup>71</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_13.2</strong></li>
            <li>Царь, не отправляясь в деревни (<em>grāma</em>) и области (<em>rājyarāṣṭra</em>),</li>
            <li>собирает (<em>ādadati</em>) весь доход (<em>āya</em>) со своих владений (<em>viṣaya</em>);</li>
            <li>так и бодхисаттва, нигде не покидая дхарматы (<em>na calate… dharmatāyām</em>),</li>
            <li>собирает (<em>ādadati</em>) все качества (<em>guṇa</em>) дхарм будды (<em>buddhadharma</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается тринадцатая глава, именуемая «О непостижимом» (<em>Acintyaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 14 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 14. О сравнениях (<em>aupamyaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.1</strong></li>
            <li>Бодхисаттва, у кого есть твёрдая вера (<em>śraddhā</em>) в Сугату</li>
            <li>и расположение ума (<em>āśaya</em>), соединённое с высшей Праджняпарамитой,</li>
            <li>преодолев две ступени (<em>bhūmidvaya</em>) шраваков и пратьекабудд,</li>
            <li>вскоре достигнет неодолимого (<em>anabhibhūta</em>) пробуждения Победителей.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.2</strong></li>
            <li>Когда морской корабль разбит,</li>
            <li>человек, не ухватившийся за труп (<em>bhṛtaka</em>),<a href="#citation-72" id="ref-72" class="citation-mark"><sup>72</sup></a> траву или дерево,</li>
            <li>погибает посреди воды, не достигнув берега;</li>
            <li>ухватившийся же достигает дальнего берега.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.3</strong></li>
            <li>Так и те, кто, обладая верой (<em>śraddhā</em>) и обретя ясность (<em>prasāda</em>),</li>
            <li>оставляют Мать-Праджняпарамиту,</li>
            <li>будут всегда блуждать (<em>saṃsaranti</em>) в океане сансары (<em>saṃsārasāgara</em>),</li>
            <li>в разбивающихся волнах рождения, старости, смерти и скорби (<em>jātījarāmaraṇaśoka</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.4</strong></li>
            <li>Те же, кого охватила высшая Праджняпарамита (<em>varaprajñāparigṛhīta</em>),</li>
            <li>кто сведущ в собственной природе явлений (<em>bhāvasvabhāvakuśala</em>)<a href="#citation-73" id="ref-73" class="citation-mark"><sup>73</sup></a></li>
            <li>и видит высший смысл (<em>paramārthadarśin</em>),</li>
            <li>чьи корабли-колесницы (<em>yānapātra</em>) нагружены</li>
            <li>богатством заслуги и знания (<em>puṇyajñānadhana</em>),</li>
            <li>вскоре касаются дивного (<em>paramādbhuta</em>) пробуждения Сугаты.<a href="#citation-74" id="ref-74" class="citation-mark"><sup>74</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.5</strong></li>
            <li>Если кто-нибудь понесёт воду в необожжённом кувшине,</li>
            <li>следует знать: этот [кувшин] быстро разобьётся из-за непрочности;</li>
            <li>несущий же воду в обожжённом кувшине</li>
            <li>не боится того, что кувшин в пути разломается,</li>
            <li>и благополучно приходит домой.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.6</strong></li>
            <li>Даже если бодхисаттва исполнен веры (<em>śraddhābahula</em>),</li>
            <li>но лишён мудрости (<em>prajñāvihīna</em>), он вскоре приходит к гибели (<em>vilaya</em>);</li>
            <li>когда же его вера охвачена мудростью,<a href="#citation-75" id="ref-75" class="citation-mark"><sup>75</sup></a></li>
            <li>он, преодолев две ступени (<em>bhūmidvaya</em>),<a href="#citation-76" id="ref-76" class="citation-mark"><sup>76</sup></a></li>
            <li>достигнет высшего пробуждения (<em>agrabodhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.7</strong></li>
            <li>Как не подготовленный должным образом корабль</li>
            <li>терпит крушение в океане вместе с грузом и купцами,</li>
            <li>а тот же корабль, хорошо подготовленный</li>
            <li>и снаряжённый, не разбивается и со всем грузом достигает берега, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.8</strong></li>
            <li>так и бодхисаттва, взращённый верой (<em>śraddhāparibhāvita</em>),</li>
            <li>но лишённый мудрости (<em>prajñāvihīna</em>),</li>
            <li>быстро отдаляется от пробуждения (<em>bodhim upaiti hānim</em>),<a href="#citation-77" id="ref-77" class="citation-mark"><sup>77</sup></a></li>
            <li>а тот же бодхисаттва, если он соединён</li>
            <li>с высшей Праджняпарамитой (<em>prajñavarapāramitāsuyukta</em>),</li>
            <li>невредимый (<em>akṣata</em>) и неповреждённый (<em>anupahata</em>),</li>
            <li>достигает пробуждения Победителей.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.9</strong></li>
            <li>Человек дряхлый, страдающий, ста двадцати лет (<em>śataviṃśavarṣa</em>),</li>
            <li>хотя бы и поднялся, сам идти не может;</li>
            <li>но когда его с левой и с правой стороны поддерживают</li>
            <li>двое людей, он не боится падения и идёт легко.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_14.10</strong></li>
            <li>Так и бодхисаттва, слабый в мудрости (<em>prajñā durbala</em>),</li>
            <li>хотя и устремился в путь (<em>prasthihati</em>),</li>
            <li>ломается на полпути (<em>bhajyati antareṇa</em>).<a href="#citation-78" id="ref-78" class="citation-mark"><sup>78</sup></a></li>
            <li>Но если он поддерживается</li>
            <li>силой искусных средств и мудростью (<em>upāyabala-prajñā-parigṛhīta</em>),</li>
            <li>он не ломается (<em>na ca bhajyate</em>)</li>
            <li>и достигает (<em>spṛśati</em>) пробуждения Быков среди людей (<em>bodhi nararṣabhāṇām</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается четырнадцатая глава, именуемая «О сравнениях» (<em>Aupamyaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 15 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 15. О богах (<em>Devaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.1</strong></li>
            <li>Бодхисаттвам, пребывающим на ступени начинающих (<em>ādikarma-sthita-bhūmi</em>)</li>
            <li>и устремившимся (<em>prasthita</em>) с решительным намерением (<em>adhyāśaya</em>)<a href="#citation-79" id="ref-79" class="citation-mark"><sup>79</sup></a></li>
            <li>к высшему пробуждению Будды (<em>vara-buddhabodhi</em>), —</li>
            <li>как добрым ученикам, исполненным почтения к учителю (<em>guru-gaurava</em>), —</li>
            <li>этим мудрым (<em>vijña</em>) следует всегда служить благому другу (<em>kalyāṇamitra</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.2</strong></li>
            <li>По какой причине? От них возникают качества мудрых (<em>guṇāgama</em>),</li>
            <li>ибо они наставляют (<em>anuśāsayanti</em>) в Праджняпарамите.</li>
            <li>Так говорит Победитель, обладатель высших качеств:</li>
            <li>«Дхармы будды опираются на благого друга (<em>kalyāṇamitra</em>)».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.3</strong></li>
            <li>Даяние (<em>dāna</em>), нравственность (<em>śīla</em>), терпение (<em>kṣānti</em>),</li>
            <li>усердие (<em>vīrya</em>), дхьяна и мудрость (<em>prajñā</em>)</li>
            <li>следует посвящать (<em>pariṇāmayitavya</em>) пробуждению.</li>
            <li>Но, рассматривая пробуждение как скандху (<em>bodhiskandha</em>),<a href="#citation-80" id="ref-80" class="citation-mark"><sup>80</sup></a></li>
            <li>не следует за него хвататься (<em>parāmṛśeyā</em>);</li>
            <li>однако начинающих (<em>ādikarmika</em>) так наставлять не следует.<a href="#citation-81" id="ref-81" class="citation-mark"><sup>81</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.4</strong></li>
            <li>Так практикуя, океаны качеств (<em>guṇasāgara</em>),</li>
            <li>луны среди говорящих (<em>vādicandra</em>),</li>
            <li>они становятся защитой (<em>trāṇa</em>) мира,</li>
            <li>прибежищем (<em>śaraṇa</em>) и пристанищем (<em>lena</em>),</li>
            <li>путём (<em>gati</em>), разумом (<em>buddhi</em>), островом (<em>dvīpa</em>)</li>
            <li>и руководителями (<em>pariṇāyaka</em>), желающими блага (<em>arthakāma</em>);</li>
            <li>они — светочи (<em>pradyota</em>), факелы (<em>ulka</em>),</li>
            <li>проповедники высшей Дхармы (<em>varadharmakathin</em>)</li>
            <li>и нерушимые (<em>akṣobhya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.5</strong></li>
            <li>Великославные (<em>mahāyaśas</em>) [бодхисаттвы] облачаются в доспехи</li>
            <ul>для трудновыполнимого деяния (<em>duṣkara-saṃnāha</em>);<a href="#citation-82" id="ref-82" class="citation-mark"><sup>82</sup></a></ul>li>
            <li>их доспех — не скандхи, дхату и аятаны.</li>
            <li>Они свободны от распознавания трёх колесниц (<em>triyānasaṃjñā</em>),</li>
            <li>ничем не удерживаемы (<em>aparigṛhīta</em>), невозвратны (<em>avivartika</em>),<a href="#citation-83" id="ref-83" class="citation-mark"><sup>83</sup></a></li>
            <li>непоколебимы (<em>acalita</em>) и незыблемы по природе (<em>akopyadharma</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.6</strong></li>
            <li>Наделённые дхармой (<em>dharmasamudāgata</em>),</li>
            <li>свободные от разрастания умопостроений (<em>niṣprapañca</em>),</li>
            <li>избавленные от сомнений (<em>kāṅkṣā</em>), колебаний (<em>vilekha</em>)<a href="#citation-84" id="ref-84" class="citation-mark"><sup>84</sup></a></li>
            <li>и неуверенности (<em>vimati</em>), стремящиеся к благу (<em>arthayukta</em>),</li>
            <li>они, услышав Праджняпарамиту, не впадают в уныние (<em>na sīdayanti</em>).</li>
            <li>Следует знать, что они не могут быть уведены другими</li>
            <li>с пути (<em>aparapraṇeya</em>) и являются невозвратными (<em>avivartika</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.7</strong></li>
            <li>Глубока (<em>gambhīra</em>) эта Дхарма Наставников, трудна для восприятия (<em>durdṛśa</em>);</li>
            <li>никто её не постиг (<em>adhigata</em>) и не достигает (<em>prāpuṇanti</em>).</li>
            <li>Поэтому Благодетельный и Сострадательный (<em>hitānukampin</em>),</li>
            <li>обретя пробуждение, не проявляет рвения (<em>alpotsuka</em>)<a href="#citation-85" id="ref-85" class="citation-mark"><sup>85</sup></a> [проповедовать],</li>
            <li>размышляя: «Кто из множества существ (<em>sattvakāya</em>) сможет понять это?»</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_15.8</strong></li>
            <li>Существа радуются привязанности (<em>ālayarata</em>),</li>
            <li>жаждут объектов чувств (<em>viṣayābhilāṣin</em>),</li>
            <li>пребывают в схватывании (<em>sthita agrahe</em>),</li>
            <li>будучи неразумными (<em>abudha</em>)</li>
            <li>и погруженными в великую слепоту (<em>mahāndhabhūta</em>).</li>
            <li>Дхарму же надлежит постигать как не имеющую привязанности (<em>anālaya</em>)</li>
            <li>и не подлежащую схватыванию (<em>anāgraha</em>);</li>
            <li>отсюда возникает столкновение (<em>vigraha</em>) с миром.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается пятнадцатая глава, именуемая «О богах» (<em>Devaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 16 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 16. О таковости (<em>tathatāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.1</strong></li>
            <li>Пространство (<em>ākāśadhātu</em>) в восточном направлении (<em>pūrvādiś</em>),</li>
            <li>в южном (<em>dakṣiṇa</em>), также в западном и северном (<em>paścima-uttara</em>) —</li>
            <li>безгранично (<em>anantapāra</em>). Вверху и внизу (<em>upara-adhara</em>),</li>
            <li>в десяти направлениях (<em>daśaddiś</em>), сколько ни есть, —</li>
            <li>многообразия (<em>nānātva</em>) нет, и различия (<em>viśeṣa</em>) не существует.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.2</strong></li>
            <li>Таковость (<em>tathatā</em>) прошлого (<em>atikrānta</em>), таковость не наступившего (<em>aprāpta</em>),</li>
            <li>таковость настоящего (<em>pratyutpanna</em>), таковость архатов (<em>tathatārhatānām</em>),</li>
            <li>таковость всех дхарм (<em>sarvadharmatathatā</em>), таковость Победителей<a href="#citation-86" id="ref-86" class="citation-mark"><sup>86</sup></a> —</li>
            <li>всё это таковость дхарм (<em>sarveṣāṃ dharmatathatā</em>):</li>
            <li>различия не существует (<em>na viśeṣaprāptā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.3</strong></li>
            <li>Бодхисаттва, который желает достичь (<em>prāpuṇetu</em>) пробуждения Сугат,</li>
            <li>свободного от множественности дхарм (<em>nānātvadharmavigata</em>), —</li>
            <li>пусть соединится (<em>yujyatu</em>) с Праджняпарамитой,</li>
            <li>будучи наделён искусными средствами (<em>upāyayukto</em>);<a href="#citation-87" id="ref-87" class="citation-mark"><sup>87</sup></a></li>
            <li>без мудрости (<em>prajñā</em>) нет постижения (<em>adhigama</em>) у Наставников людей.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.4</strong></li>
            <li>Птица с огромным телом — в сто пятьдесят йоджан,</li>
            <li>с ослабевшими и истощёнными крыльями, —</li>
            <li>если она бросится из обителей Тридцати трёх в Джамбудвипу,</li>
            <li>то придёт (<em>vrajeyā</em>) к погибели (<em>vilaya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.5</strong></li>
            <li>Даже если бы кто-либо накапливал (<em>samudānayeyā</em>)</li>
            <li>эти пять парамит Победителей в течение многих коти-ниют кальп</li>
            <li>и постоянно заботился (<em>sevya</em>) о мире,</li>
            <li>исполняя бесконечные и обширные обеты (<em>praṇidhī-ananta-vipula</em>), —</li>
            <li>без искусных средств (<em>anupāya</em>), лишённый мудрости (<em>prajñā-vikala</em>),</li>
            <li>он падает (<em>pari</em>) в состояние шраваки (<em>śrāvakattva</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_16.6</strong></li>
            <li>Кто желает (<em>icchati</em>) выйти (<em>niryāyanāya</em>) к знанию Будды (<em>buddhajñāna</em>),</li>
            <li>[тот пусть имеет] равностный ум (<em>samacitta</em>) ко всему миру (<em>sarva-jagatī</em>)</li>
            <li>и распознавание [всех существ] как отца и матери (<em>pitṛ-mātṛ-saṃjñā</em>).</li>
            <li>С мыслью о благе (<em>hitacitta</em>) и дружелюбным умом (<em>maitra-manas</em>)</li>
            <li>пусть он проявляет усердие (<em>parākrameyā</em>),</li>
            <li>безупречно искренний (<em>akhila-ārjava</em>),</li>
            <li>и с мягкой речью (<em>mṛdu-gir</em>) пусть устремляется [вперед].</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается шестнадцатая глава, именуемая «О таковости» (<em>Tathatāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 17 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 17. Об отличительных чертах и облике невозвратных (<em>Avinivartanīyaliṅgākāraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.1</strong></li>
            <li>Достопочтимый Субхути вопрошает Защитника мира:</li>
            <li>«Поведай об отличительных чертах (<em>liṅga</em>)<a href="#citation-88" id="ref-88" class="citation-mark"><sup>88</sup></a> безмятежных (<em>araṇa</em>),<a href="#citation-89" id="ref-89" class="citation-mark"><sup>89</sup></a></li>
            <li>[этих] океанов качеств (<em>guṇasāgara</em>), и о том,</li>
            <li>как обладающие великим могуществом (<em>mahānubhāva</em>)</li>
            <li>становятся невозвратными (<em>avivartiya</em>).</li>
            <li>Изъясни (<em>vyākuruṣva</em>), о Победитель, их качества</li>
            <li>хотя бы в общих чертах (<em>pradeśamātra</em>)».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.2</strong></li>
            <li>«Свободные от распознавания многообразия (<em>nānātvasaṃjñāvigata</em>),</li>
            <li>говорящие разумную речь (<em>yuktabhāṇī</em>),<a href="#citation-90" id="ref-90" class="citation-mark"><sup>90</sup></a></li>
            <li>не опирающиеся на иных шраманов и брахманов,</li>
            <li>мудрые (<em>vidu</em>), всегда (<em>sadākālam</em>) избегающие трёх неблагих уделов (<em>triyapāya</em>)</li>
            <li>и усердные в десяти путях благих действий (<em>daśa-kuśalakarmapatha</em>),</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.3</strong></li>
            <li>не преследующие корыстных целей (<em>nirāmiṣa</em>),</li>
            <li>наставляющие мир живых существ (<em>jagat</em>) в Дхарме,</li>
            <li>неизменно утверждённые в ней (<em>ekāntadharmaniyata</em>)</li>
            <li>и всегда мягкие в речи (<em>snigdhavākya</em>),<a href="#citation-91" id="ref-91" class="citation-mark"><sup>91</sup></a></li>
            <li>стоя, прохаживаясь, лёжа и сидя</li>
            <li>осознающие происходящее (<em>susaṃprajāna</em>),</li>
            <li>смотрящие на расстояние ярма (<em>yugamātraprekṣin</em>)<a href="#citation-92" id="ref-92" class="citation-mark"><sup>92</sup></a></li>
            <li>и идущие с умом, не знающим заблуждения (<em>abhrāntacinta</em>),<a href="#citation-93" id="ref-93" class="citation-mark"><sup>93</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.4</strong></li>
            <li>чистые, в чистых одеждах (<em>śuciśaucāmbaradhara</em>),<a href="#citation-94" id="ref-94" class="citation-mark"><sup>94</sup></a></li>
            <li>очищенные тройным уединением (<em>trivivekaśuddha</em>),<a href="#citation-95" id="ref-95" class="citation-mark"><sup>95</sup></a></li>
            <li>не испытывающие жажды стяжания (<em>lābhakāma</em>),<a href="#citation-96" id="ref-96" class="citation-mark"><sup>96</sup></a></li>
            <li>эти быки (<em>vṛṣabha</em>), всегда устремлённые к Дхарме (<em>dharmakāma</em>),</li>
            <li>вышедшие за пределы владений Мары (<em>mārasyatītaviṣaya</em>),</li>
            <li>и другие не могут сбить их с пути (<em>aparapraṇeya</em>),</li>
            <li>сосредоточенные в четырёх дхьянах (<em>catudhyānadhyāyi</em>),</li>
            <li>но не опирающиеся на эти дхьяны (<em>na ca niśrita tatra dhyāne</em>),</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.5</strong></li>
            <li>не жаждущие славы (<em>kīrtikāma</em>),</li>
            <li>с умом, не охваченным гневом (<em>krodhaparītacitta</em>),</li>
            <li>даже став домохозяевами (<em>gṛhibhūta</em>),</li>
            <li>никогда не привязывающиеся (<em>anadhyoṣita</em>)</li>
            <li>ни к какому имуществу (<em>vastu</em>),<a href="#citation-97" id="ref-97" class="citation-mark"><sup>97</sup></a></li>
            <li>не ищущие чувственных наслаждений ради средств к жизни (<em>jīvikāviṣayabhoga</em>),<a href="#citation-98" id="ref-98" class="citation-mark"><sup>98</sup></a></li>
            <li>не прибегающие к вредоносным заклинаниям (<em>abhicāramantra</em>)<a href="#citation-99" id="ref-99" class="citation-mark"><sup>99</sup></a></li>
            <li>и любовным чарам (<em>strīprayogamantra</em>),<a href="#citation-100" id="ref-100" class="citation-mark"><sup>100</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.6</strong></li>
            <li>не делающие предсказаний (<em>ādiśanti</em>) для мужчин и женщин</li>
            <li>об исполнении желаний (<em>iccha-karmāṃ</em>),<a href="#citation-101" id="ref-101" class="citation-mark"><sup>101</sup></a></li>
            <li>уединённые (<em>pravivikta</em>), усердные в высшей Праджняпарамите,</li>
            <li>свободные от ссор и споров (<em>kalahavivādavigata</em>),</li>
            <li>с твёрдым дружелюбным умом (<em>dṛḍhamaitracitta</em>),</li>
            <li>желающие всеведения (<em>sarvajñakāma</em>),</li>
            <li>всегда склонные к учению (<em>śāsane nimnacitta</em>),</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_17.7</strong></li>
            <li>избегающие пограничных областей,</li>
            <li>населённых варварскими племенами,</li>
            <li>свободные от сомнений</li>
            <li>относительно своей ступени (<em>svakabhūmikāṅkṣāvigata</em>)</li>
            <li>и всегда подобные горе Меру (<em>merukalpa</em>),</li>
            <li>ради Дхармы (<em>dharmārtha</em>) отдающие жизнь (<em>jīvita tyajanti</em>),</li>
            <li>усердные в практике (<em>prayuktayoga</em>), —</li>
            <li>эти [качества] следует знать (<em>prajānitavyā</em>)</li>
            <li>как отличительные черты (<em>liṅga</em>) невозвратных (<em>avivartiya</em>)».</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается семнадцатая глава, именуемая «Об отличительных чертах и облике невозвратных» (<em>Avinivartanīyaliṅgākāraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 18 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 18. О шуньяте (<em>śūnyatāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.1</strong></li>
            <li>Глубоки форма, чувство, намерение (<em>cetanā</em>),</li>
            <li>сознание и распознавание (<em>saṃjñā</em>) —</li>
            <li>по природе (<em>prakṛti</em>) лишённые образов-знаков (<em>animitta</em>)</li>
            <li>и умиротворённые (<em>śānta</em>).</li>
            <li>Как ищущий глубину (<em>gādha</em>) океана (<em>sāgara</em>)</li>
            <li>с помощью шеста (<em>kāṇḍa</em>) [не обнаруживает дна], —</li>
            <li>так и исследовавший (<em>vimṛṣya</em>) скандхи мудростью (<em>prajñā</em>)</li>
            <li>не находит [предела] их глубины (<em>alabdhagādha</em>).<a href="#citation-102" id="ref-102" class="citation-mark"><sup>102</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.2</strong></li>
            <li>Тот бодхисаттва, который постигает (<em>budhyati</em>)</li>
            <li>эти дхармы глубокой колесницы (<em>gambhīrayāna</em>)</li>
            <li>как в высшем смысле (<em>paramārtha</em>) неоскверняемые (<em>nirupalepa</em>),<a href="#citation-103" id="ref-103" class="citation-mark"><sup>103</sup></a> —</li>
            <li>[понимает, что] в них нет ни скандх, ни аятан, ни дхату.</li>
            <li>Как же тогда может быть у него какое-либо достижение</li>
            <li>собственной заслуги (<em>svapuṇyasamudāgama</em>)?</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.3</strong></li>
            <li>Как человек, увлечённый страстью (<em>rāgadharmacarita</em>),</li>
            <li>назначив свидание женщине, но не встретив её (<em>alabhanta</em>),</li>
            <li>предаётся [мыслям] (<em>vivartayeyā</em>), —</li>
            <li>сколько движений ума (<em>cittacarita</em>) возникает у него за день,</li>
            <li>столько кальп бодхисаттва идёт к пробуждению (<em>anubudhyati</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.4</strong></li>
            <li>Если бы бодхисаттва на протяжении многих тысяч коти кальп</li>
            <li>приносил безупречные дары (<em>vimala dāna</em>)</li>
            <li>и соблюдал нравственность (<em>śīla</em>),</li>
            <li>а другой проповедовал бы Дхарму,</li>
            <li>устремлённый к высшей Праджняпарамите, —</li>
            <li>заслуга от даяния и нравственности не составила бы и доли [той заслуги].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.5</strong></li>
            <li>Бодхисаттва, взрастив в созерцании (<em>vibhāvayanta</em>)</li>
            <li>высшую мудрость (<em>varaprajñā</em>)</li>
            <li>и выйдя из этого [созерцания] (<em>tata utthita</em>),<a href="#citation-104" id="ref-104" class="citation-mark"><sup>104</sup></a> проповедует (<em>kathayi</em>)</li>
            <li>неоскверняемую Дхарму (<em>nirupalepa-dharma</em>)</li>
            <li>и посвящает [заслугу от этого] пробуждению</li>
            <li>ради блага мира (<em>jagad-artha-nidāna</em>).</li>
            <li>Нет в трёх мирах (<em>triloka</em>) блага (<em>śubha</em>), равного этому.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.6</strong></li>
            <li>И эта самая заслуга (<em>puṇya</em>) вновь провозглашается пустой (<em>rikta</em>),</li>
            <li>шуньей (<em>śūnya</em>), ничтожной (<em>tuccha</em>),</li>
            <li>ничего не стоящей (<em>vaśika</em>) и лишённой сердцевины (<em>asāraka</em>).</li>
            <li>Так практикуя (<em>carat</em>), он практикует мудрость (<em>prajñā</em>) Сугат;</li>
            <li>практикуя так, он обретает (<em>parigṛhṇāti</em>)</li>
            <li>неизмеримую (<em>aprameya</em>) заслугу.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.7</strong></li>
            <li>Он знает (<em>jānāti</em>) все эти дхармы</li>
            <li>как лишь словесное выражение (<em>abhilāpamātra</em>) —</li>
            <li>[дхармы], преподанные (<em>deśita</em>), применяемые (<em>prayukta</em>)</li>
            <li>и раскрытые (<em>prakāśita</em>) Буддой.</li>
            <li>Хотя он излагает их в течение</li>
            <li>многих коти-ниюта кальп (<em>kalpa-koṭi-niyuta</em>),</li>
            <li>дхармадхату не истощается (<em>na kṣīyate</em>) и не возрастает (<em>na vivardhati</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_18.8</strong></li>
            <li>И эти пять парамит Победителей —</li>
            <li>эти дхармы также провозглашены (<em>parikīrtita</em>)</li>
            <li>как лишь имена (<em>nāmamātra</em>).</li>
            <li>Бодхисаттва, который посвящает [заслуги] (<em>pariṇāmayāti</em>)</li>
            <li>и ничего не полагает (<em>na ca manyati</em>),</li>
            <li>не терпит ущерба (<em>na hīyate</em>) и достигает (<em>spṛśati</em>)</li>
            <li>высшего пробуждения будды (<em>uttamabuddhabodhi</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается восемнадцатая глава, именуемая «О шуньяте» (<em>Śūnyatāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 19 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 19. Сестра Гангадева (<em>gaṅgadevābhaginīparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.1</strong></li>
            <li>Фитиль горящего масляного светильника</li>
            <li>не сжигается [дотла] при первом соприкосновении [с пламенем],</li>
            <li>но и без этого первого [соприкосновения] он не сжигается;</li>
            <li>не сжигается фитиль и при последнем соприкосновении пламени,</li>
            <li>но и без этого последнего [соприкосновения]</li>
            <li>фитиль светильника не сжигается.<a href="#citation-105" id="ref-105" class="citation-mark"><sup>105</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.2</strong></li>
            <li>Первой мыслью (<em>prathama-citta</em>) не достигают (<em>na spṛśati</em>)</li>
            <li>высшего пробуждения (<em>agrabodhi</em>);</li>
            <li>и без неё достичь его невозможно.</li>
            <li>Последняя мысль (<em>paścima-citta</em>) также не достигает блага (<em>śiva</em>);</li>
            <li>и без неё достижение его невозможно.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.3</strong></li>
            <li>Из семени (<em>bīja</em>) возникают стебель (<em>stamba</em>),</li>
            <li>плод (<em>phala</em>) и цветок (<em>puṣpa</em>);</li>
            <li>если семя пресеклось (<em>niruddha</em>) или же вовсе отсутствует (<em>asat</em>),</li>
            <li>дерева (<em>vṛkṣa</em>) из него не будет.<a href="#citation-106" id="ref-106" class="citation-mark"><sup>106</sup></a></li>
            <li>Так и первая мысль [о пробуждении] (<em>prathama-citta</em>)</li>
            <li>есть основание (<em>nidāna</em>) пробуждения (<em>bodhi</em>):</li>
            <li>если она пресеклась или же вовсе отсутствует —</li>
            <li>пробуждения из неё не будет.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.4</strong></li>
            <li>В зависимости от семени возникают ячмень, рис и прочее;</li>
            <li>соответствующие плоды не существуют [в семени</li>
            <li>как уже готовые] и не являются совершенно несуществующими.</li>
            <li>Когда возникает пробуждение Победителей,</li>
            <li>оно есть иллюзия (<em>māyā</em>), лишённая</li>
            <li>собственной природы явлений (<em>bhāvasvabhāvavigatā</em>).<a href="#citation-107" id="ref-107" class="citation-mark"><sup>107</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.5</strong></li>
            <li>Капли воды (<em>udaka-bindu</em>) постепенно (<em>anupūrva</em>) наполняют сосуд (<em>kumbha</em>),</li>
            <li>одна за другой, от первой до последней.</li>
            <li>Точно так же первая мысль (<em>prathama-citta</em>) —</li>
            <li>причина (<em>hetu</em>) высшего пробуждения (<em>varabodhi</em>);</li>
            <li>постепенно (<em>anupūrva</em>) становятся буддами,</li>
            <li>исполненными светлых качеств (<em>śuklaguṇa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.6</strong></li>
            <li>Практикуя (<em>caramāṇu</em>) дхармы как шунью,</li>
            <li>лишённые образов-знаков (<em>animitta</em>) и устремлений (<em>apraṇihita</em>),</li>
            <li>он не касается (<em>na spṛśati</em>) нирваны (<em>nirvṛti</em>)</li>
            <li>и не следует за образами-знаками (<em>na nimittacārī</em>).<a href="#citation-108" id="ref-108" class="citation-mark"><sup>108</sup></a></li>
            <li>Подобно искусному лодочнику,</li>
            <li>который переправляется с этого берега на тот (<em>āra-pāram</em>),</li>
            <li>он не пребывает ни у одного из двух берегов (<em>ubhayānta</em>)</li>
            <li>и не останавливается посреди великого океана (<em>arṇava</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.7</strong></li>
            <li>Так практикующий бодхисаттва не думает (<em>na manyati</em>):</li>
            <li>«Я предсказан Обладателями десяти сил (<em>daśabala</em>);</li>
            <li>да достигну (<em>spṛśeya</em>) я пробуждения!»</li>
            <li>Он не страшится, поскольку здесь нет ничего.</li>
            <li>Так практикуя, он практикует мудрость (<em>prajñā</em>) Сугат.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_19.8</strong></li>
            <li>Увидев (<em>paśyitva</em>) мир как путь через пустошь,</li>
            <li>полный голода (<em>durabhikṣa</em>) и болезней (<em>savyādhi</em>),</li>
            <li>они не испытывают страха (<em>na bhaya</em>)</li>
            <li>и облачаются в доспехи (<em>uttari saṃnahante</em>).</li>
            <li>Знающие (<em>prajānamāna</em>), постоянно устремлённые</li>
            <li>вплоть до предела будущего (<em>aparānta-koṭi</em>),<a href="#citation-109" id="ref-109" class="citation-mark"><sup>109</sup></a></li>
            <li>они не допускают в уме (<em>manas</em>) ни малейшей усталости (<em>aṇumātra kheda</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается девятнадцатая глава, именуемая «Сестра Гангадева» (<em>Gaṅgadevābhaginīparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 20 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 20. Об исследовании искусных средств (<em>upāyakauśalyamīmāṃsāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.1</strong></li>
            <li>Бодхисаттва, практикующий (<em>caramāṇu</em>)</li>
            <li>мудрость (<em>prajñā</em>) Победителей,</li>
            <li>знает эти скандхи как невозникшие (<em>anupāda</em>)</li>
            <li>и как изначальную шунью (<em>ādiśūnya</em>).</li>
            <li>Даже когда он, не пребывая в сосредоточении (<em>asamāhita</em>),</li>
            <li>взирает с состраданием (<em>karuṇā</em>) на мир существ (<em>sattvadhātu</em>),</li>
            <li>он не утрачивает дхарм будды (<em>buddhadharma</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.2</strong></li>
            <li>Подобно тому как человек, искусный (<em>kuśala</em>),</li>
            <li>наделённый всеми качествами (<em>sarvaguṇa</em>), сильный (<em>balavān</em>),</li>
            <li>неодолимый (<em>dudharṣu</em>), прошедший выучку (<em>kṛtayogya</em>),</li>
            <li>сведущий в искусствах (<em>kalāvidhijña</em>),</li>
            <li>достигший совершенства в стрельбе из лука (<em>iṣvastrapāramigata</em>),</li>
            <li>владеющий многими ремёслами (<em>pṛthuśilpayukta</em>),</li>
            <li>высочайший знаток действий иллюзии (<em>māyāvidhijñaparama</em>)</li>
            <li>и желающий блага миру (<em>jagadarthakāma</em>), —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.3</strong></li>
            <li>взяв мать и отца вместе с сыновьями и женой,</li>
            <li>вступает на путь через труднопроходимую местность (<em>kāntāramārga</em>),</li>
            <li>где много врагов (<em>bahū amitro</em>); и там, сотворив [магией]</li>
            <li>множество храбрых и доблестных мужей (<em>śūravīra</em>),</li>
            <li>он благополучно проходит этот путь и вновь возвращается домой (<em>geha</em>), —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.4</strong></li>
            <li>так и мудрый (<em>vidu</em>) бодхисаттва, охватывая (<em>upabandhati</em>)</li>
            <li>великим дружелюбием (<em>mahāmaitrī</em>)<a href="#citation-110" id="ref-110" class="citation-mark"><sup>110</sup></a> весь мир существ (<em>sattvadhātu</em>),</li>
            <li>одолев (<em>atikramya</em>) четырёх Мар</li>
            <li>и преодолев две ступени (<em>bhūmidvaya</em>),</li>
            <li>пребывает в этом самадхи, но не касается (<em>na spṛśāti</em>)</li>
            <li>[окончательного] пробуждения (<em>bodhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.5</strong></li>
            <li>Опираясь на пространство (<em>ākāśa-niśrita</em>),</li>
            <li>[пребывает] ветер (<em>samīraṇa</em>);</li>
            <li>опираясь на него — масса вод (<em>āpaskandha</em>);</li>
            <li>опираясь на неё — эта великая земля (<em>mahāpṛthivī</em>) и мир [существ] (<em>jagat</em>).</li>
            <li>Основание переживания плодов кармы (<em>karma-upabhoga-nidāna</em>) существ —</li>
            <li>[вся эта взаимосвязь], установленная в пространстве (<em>ākāśasthānu</em>):</li>
            <li>как это охватить мыслью (<em>cintayi</em>)?<a href="#citation-111" id="ref-111" class="citation-mark"><sup>111</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.6</strong></li>
            <li>Так и этот [бодхисаттва], утвердившийся в шуньяте (<em>śūnyatā-pratiṣṭhita</em>),</li>
            <li>являет (<em>darśayate</em>) миру многообразные (<em>vividha</em>)</li>
            <li>и разнообразные (<em>vicitra</em>) деяния (<em>kriyā</em>).</li>
            <li>Опираясь на знание и обеты</li>
            <li>[принятые ради] существ (<em>jñāna-praṇidhāna-adhiṣṭhāna</em>),<a href="#citation-112" id="ref-112" class="citation-mark"><sup>112</sup></a></li>
            <li>он не касается (<em>na spṛśati</em>) нирваны (<em>nirvṛti</em>):</li>
            <li>шуньята — не место утверждения (<em>sthāna</em>).<a href="#citation-113" id="ref-113" class="citation-mark"><sup>113</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.7</strong></li>
            <li>Когда мудрый и учёный бодхисаттва</li>
            <li>практикует (<em>carati</em>) это высшее (<em>pravara</em>),</li>
            <li>умиротворённое (<em>śānta</em>) самадхи шуньяты (<em>śūnyasamādhi</em>),</li>
            <li>в это время не следует взращивать (<em>prabhāvitavya</em>)</li>
            <li>образ-знак (<em>nimitta</em>) и не следует утверждаться</li>
            <li>в лишённом образа-знака (<em>ānimitta</em>):</li>
            <li>он практикует (<em>cārī</em>) спокойно (<em>śānta</em>)</li>
            <li>и всецело умиротворённо (<em>praśānta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.8</strong></li>
            <li>У птицы, летящей в небе (<em>antarīkṣa</em>), нет следа (<em>pada</em>);</li>
            <li>она не стоит (<em>sthitu</em>) там и не падает (<em>patāti</em>) на землю (<em>bhūmi</em>).</li>
            <li>Так и бодхисаттва, практикующий (<em>caramāṇu</em>)</li>
            <li>врата освобождения (<em>vimokṣadvāra</em>),<a href="#citation-114" id="ref-114" class="citation-mark"><sup>114</sup></a></li>
            <li>не касается (<em>na spṛśati</em>) нирваны (<em>nirvṛti</em>)</li>
            <li>и не следует за образами-знаками (<em>na nimittacārī</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.9</strong></li>
            <li>Подобно тому как человек, обученный стрельбе из лука,</li>
            <li>выпустив стрелу вверх, пускает вслед за ней следующую стрелу, —</li>
            <li>и не даёт первой возможности упасть на землю,<a href="#citation-115" id="ref-115" class="citation-mark"><sup>115</sup></a></li>
            <li>до тех пор пока по желанию самого этого человека</li>
            <li>стрела [наконец] не упадёт, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.10</strong></li>
            <li>точно так же и тот, кто практикует высшую Праджняпарамиту,</li>
            <li>применяя (<em>vicāramāṇa</em>) мудрость (<em>prajñā</em>),</li>
            <li>искусные средства (<em>upāya</em>), силы (<em>bala</em>)</li>
            <li>и чудесные способности (<em>ṛddhi</em>), —</li>
            <li>до тех пор он не достигает этой высшей шуньяты (<em>paramaśūnyatā</em>),</li>
            <li>пока его благие корни (<em>kuśalamūla</em>)</li>
            <li>не станут совершенно полными (<em>pūrṇa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.11</strong></li>
            <li>Подобно тому как монах (<em>bhikṣu</em>), наделённый (<em>upeta</em>)</li>
            <li>высшей силой чудесных способностей (<em>parama-ṛddhi-bala</em>),</li>
            <li>пребывая в небе (<em>gagana-sthita</em>),</li>
            <li>являет (<em>kurvati</em>) парные чудеса (<em>yamaka-prātihārya</em>),</li>
            <li>показывая (<em>nidarśayāti</em>) хождение (<em>gati</em>),</li>
            <li>движение взад и вперёд (<em>caṃkrama</em>),</li>
            <li>лежание (<em>śayana</em>) и сидение (<em>niṣadya</em>),</li>
            <li>он не отступает (<em>na nivartate</em>) и не устаёт (<em>na khidyati</em>),</li>
            <li>сколько бы времени ни продолжалось</li>
            <li>это [действие] (<em>yāva tatra</em>), —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.12</strong></li>
            <li>так и мудрый (<em>vidu</em>) бодхисаттва,</li>
            <li>утвердившийся в шуньяте (<em>śūnyatā-sthita</em>),</li>
            <li>достигший совершенства в знании (<em>jñāna</em>)</li>
            <li>и чудесных способностях (<em>ṛddhi</em>),</li>
            <li>странствующий без дома (<em>aniketacārī</em>),</li>
            <li>являет (<em>darśayate</em>) миру бесконечное множество</li>
            <li>разнообразных деяний (<em>ananta vividha kriyā</em>);</li>
            <li>он не ломается (<em>na bhajyati</em>) и не устаёт (<em>na khidyati</em>)</li>
            <li>в течение коти кальп (<em>kalpa-koṭi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.13</strong></li>
            <li>Как некие люди, встав у высокой пропасти,</li>
            <li>взяв в обе руки два зонта (<em>chattradvay</em>),<a href="#citation-116" id="ref-116" class="citation-mark"><sup>116</sup></a></li>
            <li>бросаются вниз (<em>upakṣayeyyā</em>)<a href="#citation-117" id="ref-117" class="citation-mark"><sup>117</sup></a></li>
            <li>и, доверившись ветру в пространстве над великой пропастью,<a href="#citation-118" id="ref-118" class="citation-mark"><sup>118</sup></a></li>
            <li>не падают [на дно], пока [пребывают] там,<a href="#citation-119" id="ref-119" class="citation-mark"><sup>119</sup></a> —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.14</strong></li>
            <li>так и мудрый бодхисаттва,</li>
            <li>утвердившись (<em>sthitvā</em>) в сострадании (<em>karuṇā</em>),</li>
            <li>охваченный (<em>parigṛhīta</em>) двумя зонтами</li>
            <li>мудрости (<em>prajñā</em>) и искусных средств (<em>upāya</em>),</li>
            <li>рассматривает (<em>vimṛṣāti</em>) дхармы</li>
            <li>как шунью, как лишённые образов-знаков (<em>animitta</em>)</li>
            <li>и как без-устремлённые (<em>apraṇihita</em>);</li>
            <li>он не касается (<em>na spṛśati</em>) нирваны (<em>nirvṛti</em>),</li>
            <li>но видит (<em>paśyati</em>) дхармы, практикует Дхарму (<em>dharmacārī</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.15</strong></li>
            <li>Подобно тому как человек, жаждущий драгоценностей,</li>
            <li>отправившись на остров сокровищ</li>
            <li>и обретя их, вновь возвращается домой, —</li>
            <li>и хотя сам купец живёт там в полном счастье,</li>
            <li>в его мыслях (<em>manasi bhoti</em>) его страдающие родичи,<a href="#citation-120" id="ref-120" class="citation-mark"><sup>120</sup></a> —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.16</strong></li>
            <li>так и бодхисаттва, отправившись</li>
            <li>на этот остров сокровищ шуньяты</li>
            <li>и обретя там дхьяны, силы (<em>bala</em>) и способности (<em>indriya</em>), —</li>
            <li>хотя он и мог бы коснуться (<em>spṛśet</em>) нирваны (<em>nirvṛti</em>),</li>
            <li>всецело наслаждаясь (<em>abhinandamāna</em>) ею, —</li>
            <li>в его мыслях (<em>manasī bhavanti</em>)</li>
            <li>все страдающие существа.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.17</strong></li>
            <li>Как купец, [ищущий] выгоды (<em>kāmārtha</em>),</li>
            <li>ходит по городам, торговым посадам</li>
            <li>и деревням, чтобы узнать [их], —</li>
            <li>но не останавливается ни там,</li>
            <li>ни на острове драгоценностей, ни в [своем] доме,</li>
            <li>таким образом этот мудрый и знающий [проводник] (<em>vijña</em>)</li>
            <li>становится искусен в пути (<em>mārgikuśala</em>), —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.18</strong></li>
            <li>так и мудрый бодхисаттва становится искусным (<em>kuśala</em>) во всём —</li>
            <li>в знании (<em>jñāna</em>) и освобождении (<em>vimukti</em>) шраваков и пратьекабудд;</li>
            <li>но он не останавливается ни там, ни в знании будды (<em>buddhajñāna</em>),</li>
            <li>ни в составном (<em>saṃskṛta</em>);</li>
            <li>он знает путь (<em>mārgavid</em>) и знает метод (<em>vidhijña</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.19</strong></li>
            <li>Когда он, связав (<em>anubandhayitvā</em>) мир дружелюбием (<em>maitrī</em>),</li>
            <li>практикует (<em>carate</em>) самадхи шуньяты, отсутствия образов-знаков</li>
            <li>и без-устремлённости (<em>śūnyānimitta-apraṇihita</em>),<a href="#citation-121" id="ref-121" class="citation-mark"><sup>121</sup></a> —</li>
            <li>совершенно невозможно (<em>asthānam eva</em>),<a href="#citation-122" id="ref-122" class="citation-mark"><sup>122</sup></a></li>
            <li>чтобы он достиг (<em>prāpuṇeyā</em>) нирваны (<em>nirvṛti</em>)</li>
            <li>или чтобы его можно было обозначить (<em>prajñapanāya śakyaḥ</em>)</li>
            <li>как составное (<em>saṃskṛta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.20</strong></li>
            <li>Как магически сотворённый (<em>nirmita</em>) человек</li>
            <li>или [человек] с невидимым телом (<em>adṛśyakāya</em>)</li>
            <li>может быть обозначен (<em>prajñapanāya śakyaḥ</em>)</li>
            <li>[лишь] по имени (<em>nāmena</em>), —</li>
            <li>так и бодхисаттва, практикующий (<em>caramāṇu</em>)</li>
            <li>врата освобождения (<em>vimokṣadvāra</em>),</li>
            <li>может быть обозначен (<em>prajñapanāya śakyaḥ</em>)</li>
            <li>[лишь] по имени (<em>nāmena</em>).<a href="#citation-123" id="ref-123" class="citation-mark"><sup>123</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.21</strong></li>
            <li>Если, будучи спрошен (<em>pṛcchamāna</em>)</li>
            <li>о практике (<em>cari</em>) и способностях (<em>indriya</em>),</li>
            <li>бодхисаттва не разъясняет (<em>paridīpana no karoti</em>)</li>
            <li>глубокие дхармы (<em>gambhīradharma</em>) —</li>
            <li>шуньяту и свободу от образов-знаков (<em>śūnyānimitta</em>),</li>
            <li>и не излагает<a href="#citation-124" id="ref-124" class="citation-mark"><sup>124</sup></a> дхармы</li>
            <li>невозвратного пробуждения (<em>avivartiya-bodhidharma</em>), —</li>
            <li>такого не следует признавать (<em>veditavya</em>)</li>
            <li>получившим предсказание [к пробуждению] (<em>vyākṛta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.22</strong></li>
            <li>Ни ступени архата, ни ступени пратьекабудды,</li>
            <li>ни тройного мира он не касается даже во сне.</li>
            <li>И он видит будд и проповедует людям дхарму:</li>
            <li>такого следует знать как предсказанного невозвратным (<em>avivartiya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.23</strong></li>
            <li>Узрев во сне существ, попавших в три неблагих удела,</li>
            <li>он в тот же миг даёт обет: «Пусть я иссушу неблагие уделы!» —</li>
            <li>и силой утверждения истины (<em>satyādhiṣṭhāna</em>)</li>
            <li>он умиротворяет массу огня:</li>
            <li>такого следует знать как предсказанного невозвратным.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_20.24</strong></li>
            <li>Одержимых духами и [страдающих] различными болезнями</li>
            <li>в мире смертных он, благодетельный и сострадательный (<em>hitānukampī</em>),</li>
            <li>умиротворяет (<em>praśameti</em>) силой утверждения истины (<em>satyādhiṣṭhāna</em>).</li>
            <li>И от этого у него не возникает ни самомнения (<em>manyana</em>), ни гордости (<em>māna</em>):</li>
            <li>такого следует знать как предсказанного невозвратным.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцатая глава, именуемая «Об исследовании искусных средств» (<em>Upāyakauśalyamīmāṃsāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 21 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 21. О делах Мары (<em>mārakarmaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.1</strong></li>
            <li>Если в нём возникает самомнение (<em>manyana</em>):</li>
            <li>«Я предсказан, и благословением истины (<em>satyādhiṣṭhāna</em>)</li>
            <li>свершаются разные [деяния]», —</li>
            <li>если бодхисаттва, предсказанный другим [буддой],<a href="#citation-125" id="ref-125" class="citation-mark"><sup>125</sup></a></li>
            <li>преисполняется самомнения, следует знать,</li>
            <li>что он пребывает в самомнении, малоразумный (<em>alpabuddhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.2</strong></li>
            <li>Опираясь на силу имени (<em>nāmādhiṣṭhāna</em>),<a href="#citation-126" id="ref-126" class="citation-mark"><sup>126</sup></a></li>
            <li>Мара, приблизившись, скажет ему так: «Это твоё имя».</li>
            <li>Он перечислит родословную матери и отца на семь поколений назад</li>
            <li>[и возвестит]: «Когда ты станешь буддой, это будет твоё имя».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.3</strong></li>
            <li>[Мара скажет]: «Каким подвижником (<em>dhutavṛtta</em>)</li>
            <li>и усердным йогином (<em>yuktayogī</em>) ты станешь!</li>
            <li>Ведь и прежде ты обладал такими же качествами».</li>
            <li>Бодхисаттва, который, услышав это,</li>
            <li>преисполняется самомнения (<em>abhimanyati</em>), —</li>
            <li>следует знать, что он одержим Марой и малоразумен.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.4</strong></li>
            <li>Если бодхисаттва, удалившись от деревень и городов,</li>
            <li>обитает в горных пещерах,</li>
            <li>в лесах (<em>araṇya</em>) и уединённых обителях (<em>vivikta vanaprastha</em>),</li>
            <li>но при этом возвеличивает себя и хулит других,</li>
            <li>следует знать, что он одержим Марой и малоразумен.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.5</strong></li>
            <li>Пусть они постоянно живут в деревнях (<em>grāma</em>), столицах (<em>rāṣṭra</em>)</li>
            <li>и торговых городах (<em>nigama</em>), — они не стремятся там [к покою]<a href="#citation-127" id="ref-127" class="citation-mark"><sup>127</sup></a></li>
            <li>архатов и пратьекабудд;</li>
            <li>а всецело посвящают себя созреванию существ и пробуждению.</li>
            <li>Именно это названо истинным уединением (<em>viveka</em>) сынов Сугаты.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.6</strong></li>
            <li>Даже если бодхисаттва долгие коти лет живёт в горных пещерах</li>
            <li>на [протяжении] пятисот йоджан, кишащих хищниками (<em>vyālāvakīrṇa</em>), —</li>
            <li>но не знает этого уединения (<em>viveka</em>)</li>
            <li>он пребывает в омрачённом смешении (<em>saṃkīrṇa</em>),</li>
            <li>исполненный высокомерия (<em>adhimānaprāpta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.7</strong></li>
            <li>И если он превозносится над бодхисаттвами (<em>abhimanyate</em>),</li>
            <li>усердными ради блага мира<a href="#citation-128" id="ref-128" class="citation-mark"><sup>128</sup></a> и достигшими сил (<em>bala</em>),</li>
            <li>дхьян, способностей (<em>indriya</em>), освобождений (<em>vimokṣa</em>) и самадхи,</li>
            <li>[говоря]: «Они не практикуют лесного уединения,</li>
            <li>уединение не входит в сферу их практики (<em>vivekagocara</em>)», —</li>
            <li>о таком Победитель сказал, что он пребывает в сфере Мары.<a href="#citation-129" id="ref-129" class="citation-mark"><sup>129</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_21.8</strong></li>
            <li>Живёт ли он близ деревни или в лесу, —</li>
            <li>если свободен от мысли о двух колесницах</li>
            <li>и утверждён в высшем пробуждении (<em>agrabodhi</em>),</li>
            <li>то это подлинное уединение (<em>viveka</em>) тех,</li>
            <li>кто устремился ради блага мира;</li>
            <li>такого бодхисаттву, чьё «я» истощено,</li>
            <li>следует оценивать [как достойного признания].<a href="#citation-130" id="ref-130" class="citation-mark"><sup>130</sup></a></li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать первая глава, именуемая «О делах Мары» (<em>Mārakarmaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 22 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 22. О благом друге (<em>kalyāṇamitraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.1</strong></li>
            <li>Посему учёный (<em>paṇḍita</em>), искоренивший в себе гордыню (<em>māna</em>),</li>
            <li>с несокрушимой устремлённостью (<em>guru-āśaya</em>) ищущий</li>
            <li>высшее пробуждение (<em>varabodhi</em>), должен неустанно (<em>atandrita</em>)</li>
            <li>прибегать (<em>bhajitavya</em>) к благому другу (<em>kalyāṇamitra</em>),<a href="#citation-131" id="ref-131" class="citation-mark"><sup>131</sup></a></li>
            <li>подобно тому как [прибегают] к врачу ради исцеления больного от недугов.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.2</strong></li>
            <li>Будды, бодхисаттвы, устремлённые</li>
            <li>к высшему пробуждению (<em>bodhivara-prasthita</em>),</li>
            <li>и сами эти совершенства (<em>pāramitā</em>)</li>
            <li>названы (<em>nidiṣṭa</em>) благими друзьями (<em>kalyāṇamitra</em>).</li>
            <li>Именно они наставляют (<em>anuśāsaka</em>)<a href="#citation-132" id="ref-132" class="citation-mark"><sup>132</sup></a></li>
            <li>в этой ступени практики (<em>pratipattibhūmi</em>),</li>
            <li>и по двум причинам (<em>duvi kāraṇena</em>)<a href="#citation-133" id="ref-133" class="citation-mark"><sup>133</sup></a> [благого друга и парамит]</li>
            <li>бодхисаттвы [быстро] постигают (<em>anubudhyati</em>)<a href="#citation-134" id="ref-134" class="citation-mark"><sup>134</sup></a> пробуждение будды.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.3</strong></li>
            <li>Прошлые (<em>atikrānta</em>) и будущие (<em>anāgata</em>) Победители, а также</li>
            <li>[будды,] пребывающие ныне во всех направлениях (<em>diśāsu sarveṣu</em>),</li>
            <li>все они шествуют этим путём (<em>mārga</em>) —</li>
            <li>[путём] парамит-совершенств, иного нет (<em>ananya</em>).<a href="#citation-135" id="ref-135" class="citation-mark"><sup>135</sup></a></li>
            <li>Как сияние (<em>obhāsa</em>), факел (<em>ulka</em>), свет (<em>āloka</em>) и Учитель (<em>śāstri</em>)</li>
            <li>описаны (<em>pradiṣṭa</em>) эти парамиты-совершенства для тех,</li>
            <li>кто устремился (<em>prasthita</em>) к высшему пробуждению (<em>varabodhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.4</strong></li>
            <li>Как признак Праджняпарамиты — шуньята (<em>śūnyatā-lakṣaṇa</em>),</li>
            <li>так и он познаёт (<em>jānāti</em>) все дхармы</li>
            <li>как имеющие этот признак (<em>tathālakṣaṇā</em>).</li>
            <li>Постигая (<em>prajānayamāna</em>) дхармы как шунью (<em>śūnya</em>)</li>
            <li>и как лишённые признаков (<em>analakṣaṇa</em>),</li>
            <li>он, шествуя так (<em>evaṃ carat</em>),</li>
            <li>практикует (<em>carati</em>) мудрость (<em>prajñā</em>) Сугат.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.5</strong></li>
            <li>Существа, жаждущие пищи (<em>āhārakāma</em>),</li>
            <li>предающиеся выстраиванию понятий (<em>parikalpayamāna</em>),</li>
            <li>с умом, привязанным к сансаре (<em>saṃsāri-yukta-manas</em>),</li>
            <li>постоянно блуждают (<em>saṃsaranti</em>) — «Я» (<em>ahaṃ</em>) и «моё» (<em>mama</em>) —</li>
            <li>эти дхармы мнимы (<em>abhūta</em>) и шунья:</li>
            <li>глупец (<em>bāla</em>) сам завязал узел</li>
            <li>в пространстве (<em>ākāśa-gaṇṭhi</em>) своим «я» (<em>ātmana</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.6</strong></li>
            <li>Подобно тому как человек, заподозривший (<em>śaṅkita</em>) [, что его отравили]</li>
            <li>и [потому] представляющий «яд» (<em>viṣa-saṃjñata</em>),</li>
            <li>испытывает страдания (<em>abhyupaiti</em>) и падает,</li>
            <li>хотя яд (<em>viṣa</em>) и не попал в его желудок, —</li>
            <li>так и глупец, допустивший (<em>upagata</em>) [в себя] «я» (<em>ahaṃ</em>) и «моё» (<em>mama</em>),</li>
            <li>из-за этого мнимого (<em>abhūta</em>) представления «я» (<em>ahaṃ-saṃjñin</em>)</li>
            <li>рождается (<em>jāyi</em>) и умирает (<em>mriyate</em>) вновь и вновь (<em>sadā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.7</strong></li>
            <li>Насколько есть схватывание (<em>udgraha</em>),</li>
            <li>настолько явлено омрачение<a href="#citation-136" id="ref-136" class="citation-mark"><sup>136</sup></a> —</li>
            <li>необнаружение<a href="#citation-137" id="ref-137" class="citation-mark"><sup>137</sup></a> «я» и «моё»<a href="#citation-138" id="ref-138" class="citation-mark"><sup>138</sup></a> названо очищением.<a href="#citation-139" id="ref-139" class="citation-mark"><sup>139</sup></a></li>
            <li>Ибо здесь нет никого,</li>
            <li>кто омрачался бы (<em>kliśyati</em>) или очищался (<em>śudhyate</em>):</li>
            <li>[так] бодхисаттва постигает Праджняпарамиту.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.8</strong></li>
            <li>Сколько бы существ ни было здесь, во всей Джамбудвипе, —</li>
            <li>если бы все они, породив мысль</li>
            <li>о высшем пробуждении (<em>bodhivara-citta</em>),</li>
            <li>совершали даяние (<em>dāna</em>) многие тысячи коти лет</li>
            <li>и всё это посвящали пробуждению ради блага мира, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.9</strong></li>
            <li>а кто-либо, преданный высшей Праджняпарамите,</li>
            <li>хотя бы один день будет следовать ей, —</li>
            <li>эта масса даяния (<em>dānaskandha</em>) не составила бы</li>
            <li>и доли (<em>kalā</em>) [заслуги от практики Праджняпарамиты].</li>
            <li>Поэтому неустанно (<em>atandrita</em>) следует всегда (<em>sadā</em>)</li>
            <li>погружаться (<em>osaritavya</em>) в мудрость (<em>prajñā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.10</strong></li>
            <li>Когда йогин практикует высшую Праджняпарамиту,</li>
            <li>он порождает великое сострадание (<em>mahatī karuṇā</em>),</li>
            <li>свободный от распознавания существа (<em>sattvasaṃjñā</em>).</li>
            <li>Тогда мудрый (<em>vidu</em>) становится</li>
            <li>достойным подношений (<em>dakṣiṇīya</em>) всего мира:</li>
            <li>он всегда не напрасно (<em>amogha</em>) вкушает подаяние страны.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.11</strong></li>
            <li>Бодхисаттва, желающий освободить</li>
            <li>долго связанных [сансарой]<a href="#citation-140" id="ref-140" class="citation-mark"><sup>140</sup></a> богов и людей,</li>
            <li>а также существ трёх неблагих уделов</li>
            <li>и явить миру широкий путь к другому берегу,</li>
            <li>должен днём и ночью быть предан Праджняпарамите.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.12</strong></li>
            <li>Подобно тому как человек,</li>
            <li>впервые обретший драгоценность,</li>
            <li>которой прежде не имел, радуется обретению,</li>
            <li>но, потеряв её по собственной беспечности,</li>
            <li>скорбит и постоянно жаждет обрести её вновь, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_22.13</strong></li>
            <li>точно так же йогин, устремлённый к высшему пробуждению,</li>
            <li>не должен расставаться с Праджняпарамитой, подобной драгоценности.</li>
            <li>Обретя эту драгоценность и держа её, не ослабевая в усердии,</li>
            <li>он быстро постигает (<em>anubuddhayati</em>)<a href="#citation-141" id="ref-141" class="citation-mark"><sup>141</sup></a> и достигает блага (<em>śiva</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать вторая глава, именуемая «О благом друге» (<em>Kalyāṇamitraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 23 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 23. Шакра (<em>śakraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_23.1</strong></li>
            <li>Когда восходит солнце, [освободившееся от облаков]<a href="#citation-142" id="ref-142" class="citation-mark"><sup>142</sup></a></li>
            <li>и раскинувшее венец лучей, рассеивая всю густую тьму,</li>
            <li>оно затмевает всех светлячков,</li>
            <li>весь сонм звёзд и даже сияние луны.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_23.2</strong></li>
            <li>Так и мудрый (<em>vidu</em>) бодхисаттва,</li>
            <li>практикуя (<em>caranta</em>) высшую Праджняпарамиту,</li>
            <li>шуньяту и [свободу от] образов-знаков (<em>śūnyānimitta</em>),</li>
            <li>рассеяв (<em>vidhamitva</em>) дебри воззрений (<em>dṛṣṭi-gahana</em>),</li>
            <li>затмевает (<em>abhibhonti</em>) весь мир,</li>
            <li>а также архатов и пратьекабудд, — великий (<em>pṛthu</em>) бодхисаттва.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_23.3</strong></li>
            <li>Как царевич (<em>rājaputra</em>), раздающий богатство (<em>dhanadāyaka</em>)</li>
            <li>ради блага (<em>arthakāma</em>), становится первым среди всех,</li>
            <li>и к нему обращаются: он уже теперь освобождает существ,<a href="#citation-143" id="ref-143" class="citation-mark"><sup>143</sup></a></li>
            <li>тем более когда утвердится в царстве, венценосец (<em>paṭṭadhārin</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_23.4</strong></li>
            <li>Так и мудрый бодхисаттва, практикующий мудрость,</li>
            <li>дарующий [учение] бессмертия (<em>amṛtasya dāyaka</em>)</li>
            <li>и любимый (<em>priya</em>) богами и людьми (<em>maru-mānuṣa</em>),</li>
            <li>он уже теперь усерден ради счастья существ,</li>
            <li>тем более когда утвердится как Царь Дхармы.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать третья глава, именуемая «Шакра» (<em>Śakraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 24 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 24. О гордыне (<em>abhimānaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.1</strong></li>
            <li>В то время и Мара словно уязвлён занозой:</li>
            <li>он скорбит (<em>śoka</em>), мучается (<em>duḥkhita</em>),</li>
            <li>недоволен (<em>anantamana</em>) и слаб (<em>alpasthāma</em>).</li>
            <li>Чтобы устрашить, он являет зарево на горизонте</li>
            <li>и мечет метеор, думая: «Как бы сделать так,</li>
            <li>чтобы этот бодхисаттва пал духом (<em>dīna-manas</em>)!»</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.2</strong></li>
            <li>[Когда мудрые (<em>vidu</em>), соединённые с устремлением (<em>āśaya-saṃprayukta</em>),</li>
            <li>днём и ночью видят смысл высшей Праджняпарамиты],<a href="#citation-144" id="ref-144" class="citation-mark"><sup>144</sup></a></li>
            <li>тогда их тело и ум (<em>kāya-citta</em>)<a href="#citation-145" id="ref-145" class="citation-mark"><sup>145</sup></a> становятся подобны птице в небе.</li>
            <li>Как же Родственник Тьмы (<em>kṛṣṇa-bandhu</em>) найдёт [к ним] доступ?<a href="#citation-146" id="ref-146" class="citation-mark"><sup>146</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.3</strong></li>
            <li>Когда бодхисаттвы вступают в ссоры и споры,</li>
            <li>и их умы становятся враждебными и гневными (<em>ruṣṭa-citta</em>) друг к другу,</li>
            <li>тогда Мара радуется и приходит в величайший восторг,</li>
            <li>[думая]: «Оба они окажутся далеко от знания Победителей».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.4</strong></li>
            <li>«Оба они будут далеко, подобны пишачам;</li>
            <li>оба навлекут на себя утрату обета (<em>pratijñā-hāni</em>).</li>
            <li>У злых (<em>duṣṭa</em>), лишённых терпения (<em>kṣānti-vikala</em>),</li>
            <li>откуда пробуждение?» —</li>
            <li>тогда Мара радуется вместе со своей свитой.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.5</strong></li>
            <li>Если бодхисаттва, [ещё] не получивший предсказания,<a href="#citation-147" id="ref-147" class="citation-mark"><sup>147</sup></a></li>
            <li>осквернит ум (<em>cittaṃ pradūṣayi</em>) [злобой]</li>
            <li>на получившего предсказание (<em>vyākṛta</em>) и затеет спор, —</li>
            <li>сколько мгновений ума (<em>citta-kṣaṇika</em>)</li>
            <li>он пребывает в пороке ожесточённости (<em>khila-doṣa-yukta</em>),<a href="#citation-148" id="ref-148" class="citation-mark"><sup>148</sup></a></li>
            <li>столько кальп ему придётся вновь облачаться [в доспехи].</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_24.6</strong></li>
            <li>Затем у него возникает мысль (<em>mati upadyati</em>):</li>
            <li>«Это неблагое (<em>aśobhana</em>);</li>
            <li>ведь через совершенство терпения (<em>kṣānti-pāramitā</em>)</li>
            <li>будды достигают пробуждения».</li>
            <li>Он открыто признаёт [свой проступок],</li>
            <li>впредь соблюдает дисциплину (<em>saṃvarāṇi</em>)</li>
            <li>или отвращается [от содеянного] (<em>apayāti</em>),<a href="#citation-149" id="ref-149" class="citation-mark"><sup>149</sup></a> —</li>
            <li>так он обучается (<em>śikṣati</em>) здесь дхарме будды.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать четвёртая глава, именуемая «О гордыне» (<em>Abhimānaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 25 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 25. Об обучении (<em>Śikṣāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.1</strong></li>
            <li>Обучающийся (<em>śikṣamāṇa</em>), который</li>
            <li>ни к какому обучению (<em>śikṣā</em>) не приступает (<em>na upaiti</em>),</li>
            <li>не обнаруживает (<em>na labhati</em>) ни обучающегося (<em>śikṣaka</em>),</li>
            <li>ни дхарм обучения (<em>śikṣadharma</em>)</li>
            <li>и не различает (<em>avikalpamāna</em>) ни обучения, ни не-обучения (<em>aśikṣā</em>), —</li>
            <li>кто так обучается (<em>śikṣate</em>),</li>
            <li>тот обучается (<em>śikṣati</em>) здесь дхарме будды.<a href="#citation-150" id="ref-150" class="citation-mark"><sup>150</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.2</strong></li>
            <li>Бодхисаттва, который таким образом познаёт (<em>jānati</em>) это обучение (<em>śikṣā</em>),</li>
            <li>никогда не имеет изъяна в обучении (<em>śikṣā-vikala</em>),</li>
            <li>и не становится нарушителем нравственности (<em>duśīla</em>).</li>
            <li>[Стремясь снискать благоволение Будд] (<em>ārādhiteṣu</em>),<a href="#citation-151" id="ref-151" class="citation-mark"><sup>151</sup></a></li>
            <li>он обучается (<em>śikṣati</em>) здесь дхарме будды,</li>
            <li>искусный (<em>kuśala</em>) в обучении и высшем обучении (<em>śikṣātiśikṣa</em>),</li>
            <li>без схватывания (<em>nirupalambha</em>).<a href="#citation-152" id="ref-152" class="citation-mark"><sup>152</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.3</strong></li>
            <li>Обучаясь так (<em>śikṣantu eva</em>) мудрости (<em>prajñā</em>) светоносцев (<em>prabhaṃkarāṇām</em>),</li>
            <li>у мудрых (<em>vidu</em>) не возникает даже одной неблагой (<em>akuśala</em>) мысли (<em>ekacittam</em>), —</li>
            <li>подобно тому как не остаётся тьмы перед солнцем, движущимся</li>
            <li>по небу и пространству, и излучающим лучи (<em>raśmīgata</em>).<a href="#citation-153" id="ref-153" class="citation-mark"><sup>153</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.4</strong></li>
            <li>Для тех, кто обучился (<em>śikṣita</em>)<a href="#citation-154" id="ref-154" class="citation-mark"><sup>154</sup></a> Праджняпарамите,</li>
            <li>все [прочие] парамиты-совершенства здесь</li>
            <li>оказываются заключёнными в ней.</li>
            <li>Подобно тому как в воззрении об индивидуальности (<em>satkāya-dṛṣṭi</em>)<a href="#citation-155" id="ref-155" class="citation-mark"><sup>155</sup></a></li>
            <li>заключены все шестьдесят два воззрения,</li>
            <li>точно так же [в совершенстве мудрости] заключены эти совершенства.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.5</strong></li>
            <li>Подобно тому как при прекращении (<em>niruddhi</em>)</li>
            <li>жизненной способности (<em>jīvitendriya</em>)</li>
            <li>прекращаются (<em>niruddha</em>) и все прочие способности (<em>indriya</em>),</li>
            <li>какие бы ни были (<em>yāvad asti</em>), —</li>
            <li>точно так же, когда лучшие из мудрых (<em>vidu uttamānām</em>)</li>
            <li>практикуют мудрость (<em>prajñācarite</em>),</li>
            <li>говорится, что все эти парамиты-совершенства</li>
            <li>здесь заключены [в ней] (<em>saṃgṛhītā</em>).<a href="#citation-156" id="ref-156" class="citation-mark"><sup>156</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_25.6</strong></li>
            <li>Всем качествам (<em>guṇa</em>) шраваков и точно так же [качествам] пратьекабудд</li>
            <li>мудрый (<em>vidu</em>) бодхисаттва обучается (<em>śikṣitu</em>).</li>
            <li>Однако он не пребывает (<em>sthihata</em>) в них и не стремится (<em>spṛheti</em>) к ним.</li>
            <li>«И этому мне надлежит обучиться (<em>śikṣitavya</em>)», —</li>
            <li>так он обучается (<em>śikṣati</em>) этому смыслу.<a href="#citation-157" id="ref-157" class="citation-mark"><sup>157</sup></a></li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать пятая глава, именуемая «Об обучении» (<em>Śikṣāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 26 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 26. Подобие иллюзии (<em>Māyopamaparivarta</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.1</strong></li>
            <li>Если кто-либо с чистым внутренним устремлением (<em>āśayena</em>)</li>
            <li>сорадуется (<em>anumoditu</em>) порождению мысли (<em>cittotpāda</em>) у бодхисаттвы,</li>
            <li>вступившего на путь высшего пробуждения (<em>varabodhi-prasthita</em>)</li>
            <li>и ставшего невозвратным (<em>avivartiya</em>), —</li>
            <li>даже если можно было бы взвесить (<em>tulayitvā</em>)</li>
            <li>гору Меру в трёхтысячном великом тысячном мире (<em>trisāhasra</em>),</li>
            <li>благо (<em>kuśala</em>), возникающее от такого сорадования (<em>anumodanā</em>),</li>
            <li>всё же не поддаётся измерению.<a href="#citation-158" id="ref-158" class="citation-mark"><sup>158</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.2</strong></li>
            <li>Сорадуясь скоплению заслуг (<em>puṇya-rāśi</em>) всех существ,</li>
            <li>стремящихся к благому (<em>kuśalārthika</em>)</li>
            <li>и желающих освобождения (<em>mokṣa-kāma</em>), —</li>
            <li>они, радея о благе существ (<em>sattvārthin</em>),</li>
            <li>обретя бесконечные качества (<em>ananta-guṇa</em>) Победителя,</li>
            <li>будут даровать (<em>dāsyanti</em>) Дхарму миру</li>
            <li>ради полного прекращения страдания (<em>duḥkha-saṃkṣaya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.3</strong></li>
            <li>Тот бодхисаттва, который, не различая (<em>avikalpaka</em>),</li>
            <li>постигает (<em>parijānati</em>) все дхармы как шунья,</li>
            <li>лишённые образов-знаков (<em>animitta</em>)</li>
            <li>и свободные от разрастания умопостроений (<em>niṣprapañca</em>),</li>
            <li>и не ищет умышленно (<em>na parieṣati</em>) пробуждения</li>
            <li>посредством мудрости (<em>prajñā</em>),<a href="#citation-159" id="ref-159" class="citation-mark"><sup>159</sup></a> —</li>
            <li>тот йогин соединён с высшей Праджняпарамитой.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.4</strong></li>
            <li>Небо не создаёт препятствия (<em>virodha</em>) пространству (<em>ākāśadhātu</em>) —</li>
            <li>да и как (<em>kutu</em>), где и кем могло бы быть встречено такое [препятствие]?</li>
            <li>Точно так же мудрый (<em>vidu</em>) бодхисаттва,</li>
            <li>шествующий в мудрости (<em>prajñā-carita</em>),</li>
            <li>подобен открытому простору (<em>abhyavakāśa-sadṛśa</em>)</li>
            <li>и шествует в умиротворении (<em>upaśānta-cārī</em>).<a href="#citation-160" id="ref-160" class="citation-mark"><sup>160</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.5</strong></li>
            <li>Подобно тому как сотворённый магом человек (<em>māyākāra-puruṣa</em>)</li>
            <li>не думает: «Я порадую<a href="#citation-161" id="ref-161" class="citation-mark"><sup>161</sup></a> этих людей», —</li>
            <li>но всё же выполняет своё дело (<em>kārya</em>),</li>
            <li>зрители видят, как он показывает разнообразные действия,</li>
            <li>хотя у него нет ни тела (<em>kāya</em>), ни ума (<em>citta</em>), ни имени (<em>nāmadheya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.6</strong></li>
            <li>Точно так же тот, кто практикует мудрость (<em>prajñā-carita</em>),</li>
            <li>никогда не думает: «Познав пробуждение, я освобожу мир».</li>
            <li>В своих различных рождениях</li>
            <li>он являет разнообразные действия (<em>kriyā-saṃprayoga</em>),</li>
            <li>подобные магической иллюзии (<em>māyā-sadṛśa</em>),</li>
            <li>не прибегая к различающему мышлению (<em>vikalpa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.7</strong></li>
            <li>Как магическое творение Будды (<em>buddha-nirmita</em>)</li>
            <li>вершит дела Будды (<em>buddha-kārya</em>) —</li>
            <li>и ни тени упоения (<em>mada</em>) не возникает в нём, —</li>
            <li>так и мудрый бодхисаттва (<em>vidu bodhisattva</em>),</li>
            <li>практикующий мудрость (<em>prajñā-carita</em>),</li>
            <li>являет (<em>darśeti</em>) все деяния (<em>sarva-kriyā</em>),</li>
            <li>подобные магической иллюзии (<em>nirmita-māyā-tulya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_26.8</strong></li>
            <li>Как искусный и опытный плотник</li>
            <li>изготавливает деревянную механическую куклу (<em>dāru-yantra</em>),</li>
            <li>и та, подобно мужчине или женщине (<em>puruṣe strī-tulya</em>),</li>
            <li>исполняет все действия (<em>sarva-kārya</em>), —</li>
            <li>так и мудрый бодхисаттва, практикующий мудрость,</li>
            <li>посредством знания (<em>jñāna</em>) совершает все деяния (<em>sarva-kriyā</em>),</li>
            <li>свободный от различения (<em>nirvikalpa</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать шестая глава, именуемая «Подобие иллюзии» (<em>Māyopamaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 27 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 27. О сердцевине (<em>Sāraparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.1</strong></li>
            <li>Многочисленные сонмы богов,</li>
            <li>сложив ладони, склоняются и совершают поклоны</li>
            <li>тому мудрому (<em>vidu</em>), кто так практикует;</li>
            <li>и все будды, сколько их ни есть</li>
            <li>в мирах десяти направлений,</li>
            <li>произносят гирлянду восхвалений его качеств.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.2</strong></li>
            <li>Если бы все существа, сколько их ни есть</li>
            <li>в мировых сферах, равных [числом] песчинкам Ганга,</li>
            <li>допустим, стали бы Марами,</li>
            <li>а [каждый из них] из каждой волосинки</li>
            <li>создал бы столько же [Мар], —</li>
            <li>все они не смогли бы причинить мудрому препятствия.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.3</strong></li>
            <li>По четырём причинам<a href="#citation-162" id="ref-162" class="citation-mark"><sup>162</sup></a> мудрый бодхисаттва</li>
            <li>становится обладающим силой (<em>balavān</em>), неодолимым<a href="#citation-163" id="ref-163" class="citation-mark"><sup>163</sup></a></li>
            <li>и непоколебимым четырьмя Марами:</li>
            <li>он пребывает в шуньяте, не оставляет существ,</li>
            <li>поступает согласно сказанному (<em>yathāvādin</em>)</li>
            <li>и пребывает с состраданием к существам.<a href="#citation-164" id="ref-164" class="citation-mark"><sup>164</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.4</strong></li>
            <li>Тот бодхисаттва, кто проникается доверием (<em>adhimucyati</em>)</li>
            <li>к этой Праджняпарамите, матери Татхагат (<em>tathāgata-mātṛ</em>),</li>
            <li>когда её излагают (<em>bhāṣyamāṇā</em>),</li>
            <li>и с устремлением (<em>āśayena</em>) усердно предаётся практике, —</li>
            <li>его следует знать как устремившегося к всеведению.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.5</strong></li>
            <li>Он не утверждается в таковости дхармадхату (<em>dharmadhātu-tathatā</em>):</li>
            <li>пребывающий без опоры (<em>athānasthita</em>),</li>
            <li>он легко [движется] в пространстве, —</li>
            <li>как видьядхара, что, стремясь к лесу,</li>
            <li>летит по небу, не имея опоры (<em>abhilambhu</em>),</li>
            <li>и силой заклинания (<em>mantra-bala-adhiṣṭhāna</em>)</li>
            <li>заставляет дерево расцветать не в свой срок.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.6</strong></li>
            <li>Мудрый и сведущий (<em>vidu-paṇḍita</em>) бодхисаттва, практикующий так,</li>
            <li>не обнаруживает (<em>na labhati</em>) ни постигающего (<em>budhyaka</em>), ни дхарм будды,</li>
            <li>ни наставляющего (<em>deśika</em>), ни видящего дхармату (<em>paśyaka dharmatāyām</em>).</li>
            <li>Это обитель (<em>vihāra</em>) стремящихся к умиротворению (<em>śāntaiṣin</em>)</li>
            <li>и радующихся драгоценным качествам (<em>guṇe ratānām</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.7</strong></li>
            <li>Сколько ни есть обителей (<em>vihāra</em>) шраваков и пратьекабудд —</li>
            <li>умиротворённых, исполненных покоя самадхи (<em>samādhi-praśama</em>)</li>
            <li>и блаженства (<em>sukha-saṃprayukta</em>), —</li>
            <li>кроме освобождения Архатов-Татхагат (<em>arhanvimokṣa tathāgatānām</em>),<a href="#citation-165" id="ref-165" class="citation-mark"><sup>165</sup></a></li>
            <li>эта обитель [в Праджняпарамите]<a href="#citation-166" id="ref-166" class="citation-mark"><sup>166</sup></a> —</li>
            <li>высшая (<em>agra</em>) из всех и непревзойдённая (<em>niruttara</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.8</strong></li>
            <li>Как птица, пребывая в небе, не падает,</li>
            <li>как рыба, пребывая в воде, не гибнет,</li>
            <li>так и бодхисаттва, достигший другого берега</li>
            <li>благодаря силам дхьяны (<em>dhyāna-bala-pāraga</em>),</li>
            <li>пребывает в шуньяте (<em>śūnyā-vihāri</em>)</li>
            <li>и не достигает нирваны (<em>na nirvṛti prāpuṇāti</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_27.9</strong></li>
            <li>Кто хочет достичь вершины качеств</li>
            <li>всех существ (<em>sarva-sattva-guṇa-agra</em>),</li>
            <li>коснуться высшего,</li>
            <li>поразительного знания Будды (<em>paramādbhuta buddha-jñāna</em>),</li>
            <li>даровать высший,</li>
            <li>превосходный дар Дхармы (<em>uttama-dharma-dāna</em>), —</li>
            <li>пусть прибегнет к этой высшей обители (<em>agraṃ vihāra</em>) тех,</li>
            <li>кто приносит благо (<em>hitaṃkarāṇām</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать седьмая глава, именуемая «О сердцевине» (<em>Sāraparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 28 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 28. О рассыпанных цветах (<em>Avakīrṇakusumaparivarta</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.1</strong></li>
            <li>Из всех обучений (<em>śikṣā</em>), провозглашённых Наставником,</li>
            <li>это обучение — высшее (<em>agra</em>) и непревзойдённое (<em>niruttara</em>).</li>
            <li>Кто, зная все обучения (<em>sarvaśikṣavid</em>),</li>
            <li>желает достичь другого берега (<em>pāraṃ gantum</em>),</li>
            <li>тот обучается (<em>śikṣati</em>) этой Праджняпарамите —</li>
            <li>обучению Будды (<em>buddhaśikṣā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.2</strong></li>
            <li>Это высшее сокровище (<em>agra nidhāna</em>),</li>
            <li>сокровищница Высшей Дхармы (<em>uttama-dharma-kośa</em>),</li>
            <li>порождение рода Будд (<em>buddha-gotra-janana</em>),</li>
            <li>сокровищница счастья и блаженства (<em>sukha-saukhya-gañja</em>).</li>
            <li>Защитники мира прошлого, будущего и десяти направлений</li>
            <li>произошли (<em>prasūta</em>) из неё, —</li>
            <li>а дхармадхату (<em>dharmadhātu</em>) не истощается.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.3</strong></li>
            <li>Сколько ни есть деревьев, плодов, цветов и лесных растений,</li>
            <li>все они возникают и произрастают из земли.</li>
            <li>Но земля не истощается и не возрастает,</li>
            <li>не утомляется и не скудеет,</li>
            <li>[пребывая] свободной от различения (<em>nirvikalpā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.4</strong></li>
            <li>Сыны Будд (<em>buddhasama</em>),<a href="#citation-167" id="ref-167" class="citation-mark"><sup>167</sup></a> шраваки, пратьекабудды, боги</li>
            <li>и все дхармы счастья и блаженства всего мира —</li>
            <li>всё это возникло (<em>prasūta</em>) из высшей Праджняпарамиты,</li>
            <li>Сама же мудрость (<em>prajñā</em>) никогда не истощается</li>
            <li>и не возрастает.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.5</strong></li>
            <li>Все существа — низшие, средние и высшие в мире —</li>
            <li>все они, как изрёк Сугата, возникают из неведения (<em>avidyā-prabhava</em>).</li>
            <li>При полноте условий (<em>sāmagrī-pratyaya</em>)</li>
            <li>приводится в движение (<em>pravartate</em>) механизм страдания (<em>duḥkha-yantra</em>),</li>
            <li>но механизм не истощается,</li>
            <li>и неведение (<em>avidyā</em>) не возрастает (<em>na vṛddhi</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.6</strong></li>
            <li>Сколько ни есть дверей и методов познания (<em>jñāna-naya-dvāra</em>),</li>
            <li>корней искусных средств (<em>upāya-mūla</em>),</li>
            <li>всё это возникло (<em>prasūta</em>) из высшей Праджняпарамиты.</li>
            <li>При полноте условий (<em>sāmagrī-pratyaya</em>)</li>
            <li>приводится в движение (<em>pravartate</em>) механизм познания (<em>jñāna-yantra</em>),</li>
            <li>но Праджняпарамита не возрастает (<em>vardhate</em>) и не убывает (<em>hīyate</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_28.7</strong></li>
            <li>Бодхисаттва, который постигает (<em>budhyati</em>)</li>
            <li>зависимое возникновение (<em>pratītyasamutpāda</em>)</li>
            <li>как не-возникновение (<em>anudbhava</em>),</li>
            <li>а эту мудрость (<em>prajñā</em>) — как неисчерпаемую (<em>akṣayataḥ</em>),</li>
            <li>подобно солнцу, чьи лучи освободились (<em>mukta-raśmi</em>)</li>
            <li>от облачного покрова (<em>abhra-paṭala</em>),</li>
            <li>рассеяв покров неведения (<em>avidyā-paṭala</em>),</li>
            <li>становится Самовозникшим [Буддой] (<em>svayaṃbhū</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать восьмая глава, именуемая «О рассыпанных цветах» (<em>Avakīrṇakusumaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 29 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 29. О следовании (<em>Anugamaparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.1</strong></li>
            <li>Обладающие великим могуществом (<em>mahānubhāva</em>) [бодхисаттвы]</li>
            <li>пребывают (<em>viharanti</em>) в четырёх дхьянах,</li>
            <li>но не создают из них ни пристанища (<em>ālaya</em>), ни опоры-зависимости (<em>niśraya</em>).</li>
            <li>Однако, в свою очередь, эти четыре дхьяны со своими факторами (<em>sāṅga</em>)</li>
            <li>станут опорой (<em>āśraya</em>)<a href="#citation-168" id="ref-168" class="citation-mark"><sup>168</sup></a> для достижения высшего,</li>
            <li>наилучшего пробуждения (<em>bodhivara-uttama-prāpaṇa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.2</strong></li>
            <li>Пребывая в дхьяне (<em>dhyāna-sthita</em>),</li>
            <li>он обретает высшую мудрость (<em>vara-prajñā-lābhī</em>)</li>
            <li>и переживает четыре превосходных</li>
            <li>бесформенных самадхи (<em>ārūpyarūpi samādhi catasra śreṣṭhā</em>).<a href="#citation-169" id="ref-169" class="citation-mark"><sup>169</sup></a></li>
            <li>Эти дхьяны служат содействием (<em>upakāribhūta</em>)</li>
            <li>высочайшему пробуждению (<em>varāgra-bodhi</em>),</li>
            <li>однако бодхисаттва обучается им</li>
            <li>не ради исчерпания притоков (<em>āsrava-kṣaya</em>).<a href="#citation-170" id="ref-170" class="citation-mark"><sup>170</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.3</strong></li>
            <li>Удивительно и чудесно это собрание драгоценных качеств (<em>guṇa-saṃcaya</em>):</li>
            <li>пребывая в дхьяне и самадхи,</li>
            <li>[бодхисаттвы] полностью свободны от образов-знаков (<em>nimitta nāsti</em>).</li>
            <li>И если у пребывающих в этом состоянии разрушается тело (<em>ātmabhāva</em>),</li>
            <li>они вновь рождаются в мире чувственных желаний (<em>kāmadhātu</em>) —</li>
            <li>согласно своему волеизъявлению (<em>yathābhiprāya</em>).<a href="#citation-171" id="ref-171" class="citation-mark"><sup>171</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.4</strong></li>
            <li>Подобно тому как человек из Джамбудвипы,</li>
            <li>прежде не достигавший (<em>alabdhapūrva</em>)</li>
            <li>высших небесных городов богов (<em>deva-uttama-pura</em>),</li>
            <li>достигнув их и увидев те владения (<em>viṣaya</em>), впечатлённый [ими] (<em>parigṛhīta</em>),</li>
            <li>возвращается и не делает их опорой-зависимостью (<em>niśraya</em>),<a href="#citation-172" id="ref-172" class="citation-mark"><sup>172</sup></a> —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.5</strong></li>
            <li>так и высшие бодхисаттвы, носящие качества (<em>guṇadhara</em>),</li>
            <li>пребыв (<em>viharitva</em>) в дхьяне и самадхи, усердные в йоге,</li>
            <li>вновь оказываются в мире желаний, неоскверняемыми (<em>anopalipta</em>),</li>
            <li>подобно лотосу в воде, не опираясь на дхармы глупцов.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.6</strong></li>
            <li>Великие духом (<em>mahātman</em>) не стремятся</li>
            <li>к рождению в мире без-форм —</li>
            <li>разве только ради созревания существ (<em>sattvaparipācana</em>),</li>
            <li>очищения земли [будды] (<em>kṣetraśodhī</em>)<a href="#citation-173" id="ref-173" class="citation-mark"><sup>173</sup></a></li>
            <li>и доведения до полноты (<em>paripūraṇa</em>) этих парамит:</li>
            <li>ведь там (в мире без форм) [их ждёт] утрата</li>
            <li>качеств пробуждения и парамит (<em>bodhiguṇa-pāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.7</strong></li>
            <li>Подобно тому как некий человек,</li>
            <li>найдя сокровищницу драгоценностей,</li>
            <li>не порождает к ней мысли о стяжательстве,</li>
            <li>а в другое время, один,</li>
            <li>взяв [из неё] и принеся в дом,</li>
            <li>не становится алчным, —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.8</strong></li>
            <li>точно так и мудрые бодхисаттвы,</li>
            <li>обретя четыре дхьяны и</li>
            <li>умиротворённое самадхи (<em>samādhi śānta</em>),</li>
            <li>дарующие радость и блаженство (<em>prīti-sukha-da</em>),</li>
            <li>оставив (<em>avasṛjya</em>) обретение (<em>lābha</em>) блаженства</li>
            <li>и радости дхьяны и самадхи (<em>dhyāna-sukha-prīti-samādhi</em>),</li>
            <li>вновь входят в мир желаний, сострадая миру.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.9</strong></li>
            <li>Если бодхисаттва, пребывая в сосредоточении дхьян (<em>samādhi-dhyāna</em>),</li>
            <li>порождает мысль о стяжательстве (<em>spṛhā-buddhi</em>)<a href="#citation-174" id="ref-174" class="citation-mark"><sup>174</sup></a></li>
            <li>к [колеснице] архатов и пратьекабудд, —</li>
            <li>он становится несосредоточенным (<em>asamāhita</em>),</li>
            <li>его ум возбуждён и рассеян (<em>uddhata-kṣipta-citta</em>),</li>
            <li>и он утрачивает качества Будды (<em>parihīna-buddhiguṇa</em>),</li>
            <li>подобно мореходу, чей корабль разбит.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.10</strong></li>
            <li>Даже если этот безграничный (<em>ananta</em>) бодхисаттва<a href="#citation-175" id="ref-175" class="citation-mark"><sup>175</sup></a></li>
            <li>наслаждается (<em>bhogī</em>) пятью качествами чувственного желания (<em>kāma-guṇa</em>) —</li>
            <li>формой, звуком, запахом, вкусом и осязанием, —</li>
            <li>[и при этом] свободен от колесницы архатов и пратьекабудд,</li>
            <li>он должен быть признан (<em>prajānayitavya</em>) героем (<em>śūra</em>),</li>
            <li>постоянно пребывающим в сосредоточении (<em>satataṃ samāhita</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.11</strong></li>
            <li>Чистые существа (<em>viśuddhasattvā</em>), преданные</li>
            <li>парамите усердия и духовной силы (<em>vīrya-bala-pāramitā</em>),</li>
            <li>действуют (<em>vicaranti</em>)<a href="#citation-176" id="ref-176" class="citation-mark"><sup>176</sup></a> ради других существ и личностей.<a href="#citation-177" id="ref-177" class="citation-mark"><sup>177</sup></a></li>
            <li>Подобно тому как служанка с кувшином,<a href="#citation-178" id="ref-178" class="citation-mark"><sup>178</sup></a></li>
            <li>будучи лишённой собственной воли (<em>avaśā</em>),</li>
            <li>находится во власти (<em>vaśa</em>) своего господина (<em>bhartṛka</em>),<a href="#citation-179" id="ref-179" class="citation-mark"><sup>179</sup></a></li>
            <li>так и стойкие мудрецы (<em>dhīra</em>) оказываются во власти</li>
            <li>всех живых существ (<em>sarva-sattva-vaśatām upayānti</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.12</strong></li>
            <li>Служанка (<em>dāsī</em>) не возражает своему господину,</li>
            <li>даже если её бранят или постоянно бьют,</li>
            <li>с умом, полным ужаса, охваченная страхом,</li>
            <li>она думает: «Он непременно убьёт меня за это».</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.13</strong></li>
            <li>Так и бодхисаттва, устремившийся к высшему пробуждению,</li>
            <li>должен пребывать среди всех существ как слуга.<a href="#citation-180" id="ref-180" class="citation-mark"><sup>180</sup></a></li>
            <li>Отсюда [приходят] обретение пробуждения (<em>bodhi-āgama</em>)</li>
            <li>и полнота качеств (<em>pāripūrī</em>): огонь, возникший из травы и хвороста,</li>
            <ul>сжигает их самих.<a href="#citation-181" id="ref-181" class="citation-mark"><sup>181</sup></a></ul>li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_29.14</strong></li>
            <li>Оставив собственное благо (<em>ātmasukha</em>),<a href="#citation-182" id="ref-182" class="citation-mark"><sup>182</sup></a></li>
            <li>днём и ночью усердный в делах других существ,</li>
            <li>с умом, не ждущим воздаяния (<em>niṣpratikāṅkṣa</em>),</li>
            <li>как мать, заботящаяся о своём единственном ребёнке,</li>
            <li>он пребывает (<em>upasthiheti</em>) в устремлении (<em>adhyāśaya</em>),</li>
            <li>не зная усталости (<em>na parikhinna</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается двадцать девятая глава, именуемая «О следовании» (<em>Anugamaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 30 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 30. О Садапрарудите (<em>Sadāpraruditaparivartaḥ</em>)<a href="#citation-183" id="ref-183" class="citation-mark"><sup>183</sup></a></h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.1</strong></li>
            <li>Бодхисаттва с решимостью долго странствовать</li>
            <li>по кругу рождений (<em>cira-saṃsaraṇa-abhiprāya</em>) ради блага существ,</li>
            <li>йогин, преданный очищению [своей] земли [будды] (<em>kṣetrapariśodhana</em>),</li>
            <li>не порождает (<em>na upādiyāti</em>) ни малейшей (<em>aṇumātra</em>) мысли</li>
            <li>об усталости (<em>kheda-buddhi</em>).</li>
            <li>Он наделён (<em>yukta</em>) совершенством усердия (<em>vīryapāramitā</em>)</li>
            <li>и неутомим (<em>atandrita</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.2</strong></li>
            <li>Если неразумный (<em>avidu</em>)<a href="#citation-184" id="ref-184" class="citation-mark"><sup>184</sup></a> бодхисаттва подсчитывает коти кальп,</li>
            <li>полагая, что до пробуждения ещё долго (<em>cirasaṃjñā</em>),</li>
            <li>он из-за этого испытывает страдание;</li>
            <li>долго мучаясь в практике Дхармы,</li>
            <li>он оказывается лишённым парамиты усердия (<em>vīryapāramitā-hīna</em>),</li>
            <li>становясь ленивым по своей сути (<em>kusīdarūpa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.3</strong></li>
            <li>Начиная с первого порождения мысли о высшем пробуждении</li>
            <li>и вплоть до достижения непревзойдённого блага (<em>anuttaraśiva</em>)</li>
            <li>он должен непрестанно (<em>rātriṃdiva</em>), с однонаправленным умом (<em>ekamanasā</em>),</li>
            <li>утверждаться в ней (<em>adhiṣṭhiheyā</em>): так следует знать</li>
            <li>мудрого и сведущего, предпринявшего усердие (<em>ārambhavīrya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.4</strong></li>
            <li>Если бы кто-нибудь сказал: «Сокруши гору Сумеру,</li>
            <li>и затем достигнешь высшего пробуждения», —</li>
            <li>и бодхисаттва породил бы мысль об усталости (<em>khedabuddhi</em>)</li>
            <li>и мысль об ограниченности [сил и способностей] (<em>pramāṇabuddhi</em>),</li>
            <li>тогда он был бы ленив (<em>kausīdyaprāpta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.5</strong></li>
            <li>А если бы у него возникает мысль (<em>mati</em>): «Разве это трудно?</li>
            <li>В одно мгновение (<em>kṣaṇamātra</em>) гора Меру рассыплется в прах»,</li>
            <li>то тогда мудрый бодхисаттва был бы [исполнен]</li>
            <li>усердия-начинания (<em>ārambhavīrya</em>) и вскоре достиг бы</li>
            <li>высшего пробуждения (<em>bodhivara</em>) Наставников.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.6</strong></li>
            <li>Если он будет усердствовать телом, умом и речью (<em>kāya-citta-vacasā</em>), полагая:</li>
            <li>«Я доведу существ до зрелости, я принесу мира благо»,</li>
            <li>оставаясь в распознавании «я» (<em>ātmasaṃjñā</em>), он был бы ленив</li>
            <li>и далёк от взращивания [постижения] отсутствия «я» (<em>nairātmabhāvanā</em>),</li>
            <li>как небо от земли.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.7</strong></li>
            <li>Когда у бодхисаттвы нет распознавания (<em>saṃjñā</em>)<a href="#citation-185" id="ref-185" class="citation-mark"><sup>185</sup></a></li>
            <li>ни тела, ни ума (<em>citta</em>), ни существа,</li>
            <li>и когда он, отвернувшись от распознавания (<em>saṃjñāvivartin</em>),</li>
            <li>пребывает (<em>sthita</em>), шествуя в недвойственной Дхарме,</li>
            <li>и стремится к умиротворённому (<em>śiva</em>), незыблемому (<em>acyuta</em>),</li>
            <li>высшему пробуждению, —</li>
            <li>это Благодетель назвал совершенством усердия (<em>vīryapāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.8</strong></li>
            <li>Услышав от другого грубые слова, дурную речь,</li>
            <li>мудрый бодхисаттва остаётся вполне довольным и счастливым.</li>
            <li>[Он думает:] «Кто говорит (<em>ko bhāṣate</em>)? Кто слышит (<em>ka śṛṇute</em>)?</li>
            <li>Откуда (<em>kutu</em>)? Чьё (<em>kasya</em>)? Чем (<em>kena</em>)?» —</li>
            <li>[так] сведущий (<em>vijña</em>) соединён (<em>yukta</em>)</li>
            <li>с высшей парамитой терпения (<em>kṣānti-varapāramitā</em>).<a href="#citation-186" id="ref-186" class="citation-mark"><sup>186</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.9</strong></li>
            <li>Если бодхисаттва, наделённый благими дхармами,</li>
            <li>терпит (<em>kṣamate</em>), — а кто-либо отдал бы [весь]</li>
            <li>трёхтысячный великий тысячный мир (<em>trisahasra</em>),<a href="#citation-187" id="ref-187" class="citation-mark"><sup>187</sup></a></li>
            <li>наполненный драгоценностями (<em>ratnabharita</em>), буддам, знающим мир,</li>
            <li>архатам и пратьекабуддам, — эта масса даяния (<em>dānaskandha</em>)</li>
            <li>не составит и доли заслуги (<em>kalāpuṇya</em>).<a href="#citation-188" id="ref-188" class="citation-mark"><sup>188</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.10</strong></li>
            <li>Телесный облик (<em>ātmabhāva</em>) пребывающего в терпении (<em>kṣāntisthita</em>)</li>
            <li>полностью очищается (<em>pariśudhyati</em>):</li>
            <li>[он наделяется] беспредельной (<em>anantapāra</em>) силой</li>
            <li>тридцати двух признаков [великого мужа].<a href="#citation-189" id="ref-189" class="citation-mark"><sup>189</sup></a></li>
            <li>Он возвещает (<em>niśāmayāti</em>) существам</li>
            <li>высшую Дхарму шуньяты (<em>śūnya-varadharma</em>),</li>
            <li>и этот терпеливый мудрец (<em>kṣamamāṇa vijña</em>)</li>
            <li>становится дорог (<em>priya</em>) всему миру.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.11</strong></li>
            <li>Если кто-либо возьмёт корзину</li>
            <li>с сандаловым порошком (<em>candanapuṭa</em>)</li>
            <li>и с глубоким почтением и любовью (<em>guruprema</em>)</li>
            <li>осыплет им бодхисаттву,</li>
            <li>а другой бросит ему на голову горящие угли,</li>
            <li>[бодхисаттва] должен породить (<em>upāditavya</em>) [в себе]</li>
            <li>равный (<em>tulya</em>) ум (<em>manas</em>) к обоим (<em>ubhayatra</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.12</strong></li>
            <li>Так проявив терпение, мудрый и сведущий бодхисаттва</li>
            <li>посвящает (<em>pariṇāmayi</em>) это порождение мысли</li>
            <li>высшему пробуждению (<em>agrabodhi</em>).</li>
            <li>Герой (<em>śūra</em>), терпеливый ко всему миру (<em>sarvajagatī kṣamamāṇa</em>),</li>
            <li>превосходит (<em>abhibhoti</em>) [всех] архатов и пратьекабудд,</li>
            <li>сколько их ни есть в мире существ.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.13</strong></li>
            <li>Сохраняющий терпение должен вновь породить (<em>upāditavya</em>)</li>
            <li>такую мысль (<em>citta</em>):</li>
            <li>«В адах, среди животных и в мире Ямы —</li>
            <li>множество страданий.</li>
            <li>Из-за чувственных услад (<em>kāmaguṇa-hetu</em>)</li>
            <li>их приходится испытывать помимо воли (<em>akāmakāra</em>).</li>
            <li>Так почему же сегодня ради пробуждения (<em>bodhi-nidāna</em>)</li>
            <li>мне не сохранить терпение [добровольно]?»</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_30.14</strong></li>
            <li>«Плеть, палка, меч, убийство, оковы и удары,</li>
            <li>отсечение головы, ушей, ног, рук и носа —</li>
            <li>сколько бы страданий ни было в мире, я всё это вытерплю».</li>
            <li>[Когда он мыслит так], бодхисаттва пребывает</li>
            <li>в парамите терпения (<em>kṣānti-pāramitā</em>).</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается тридцатая глава, именуемая «Садапрарудита» (<em>Sadāpraruditaparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 31 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 31. Дхармодгата (<em>Dharmodgataparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.1</strong></li>
            <li>Благодаря нравственности (<em>śīla</em>) возвышаются те,</li>
            <li>кто стремится к самадхи (<em>samādhikāṅkṣin</em>),</li>
            <li>пребывая в сфере Обладающего десятью силами,</li>
            <li>нерушимые в нравственности (<em>akhaṇḍaśīla</em>).</li>
            <li>Какие бы действия по сдерживанию (<em>saṃvarakriyā</em>) они ни соблюдали,</li>
            <li>всё это они посвящают пробуждению ради блага всех существ.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.2</strong></li>
            <li>Если он порождает стремление к пробуждению архатов и пратьекабудд,</li>
            <li>он становится безнравственным (<em>duḥśīla</em>), неразумным (<em>aviduṣ</em>)<a href="#citation-190" id="ref-190" class="citation-mark"><sup>190</sup></a></li>
            <li>и порочным в своей практике (<em>chidracārī</em>).</li>
            <li>Но если он посвящает (<em>pariṇāmayanti</em>) [это]</li>
            <li>высшему благу пробуждения (<em>uttamaśiva bodhi</em>),</li>
            <li>он пребывает в совершенстве нравственности (<em>śīlapāramitā</em>),</li>
            <li>даже имея дело с объектами чувственных желаний (<em>kāmaguṇayukta</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.3</strong></li>
            <li>Та дхарма, благодаря которой возникают</li>
            <li>качества пробуждения (<em>bodhiguṇaāgama</em>) у кротких (<em>sūrata</em>),</li>
            <li>есть смысл нравственности (<em>śīlaartha</em>)</li>
            <li>для наделённых качествами Дхармы (<em>guṇadharmasamanvita</em>).</li>
            <li>Та дхарма, которая ведёт к утрате</li>
            <li>качеств пробуждения (<em>bodhiguṇahāni</em>) у приносящих благо (<em>hitaṃkara</em>),</li>
            <li>Наставником объявлена безнравственностью (<em>duḥśīlatā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.4</strong></li>
            <li>Если бодхисаттва наслаждается (<em>bhuñjati</em>)</li>
            <li>пятью объектами чувственных желаний (<em>pañca kāmaguṇa</em>),</li>
            <li>и прибегает к Будде, Дхарме и благородной Сангхе,</li>
            <li>направляя мысль к всеведению (<em>sarvajñatā</em>)</li>
            <li>[и размышляя]: «Я стану Буддой», —</li>
            <li>такого сведущего (<em>vijña</em>) следует признать (<em>vedayitavya</em>)</li>
            <li>утвердившимся в парамите нравственности (<em>śīlapāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.5</strong></li>
            <li>Если, практикуя десять благих путей (<em>daśakuśalapatha</em>)</li>
            <li>в течение коти кальп (<em>kalpakoṭi</em>), он порождает стремление</li>
            <li>к архатству или пратьекабуддству (<em>pratyekārhatva</em>),</li>
            <li>тогда его нравственность становится</li>
            <li>надломленной (<em>khaṇḍaśīla</em>) и с изъяном (<em>chidraśīla</em>).</li>
            <li>Такое порождение мысли (<em>cittotpāda</em>) тяжелее даже проступка,</li>
            <li>влекущего исключение из монашеской общины (<em>pārājika</em>).<a href="#citation-191" id="ref-191" class="citation-mark"><sup>191</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.6</strong></li>
            <li>Охраняя нравственность (<em>śīla</em>)</li>
            <li>и посвящая [заслуги] высшему пробуждению (<em>agrabodhi</em>),</li>
            <li>он этим не кичится (<em>na tena manyati</em>)</li>
            <li>и не возвеличивает себя (<em>na ātmānaṃ karṣayet</em>).</li>
            <li>Оставив распознавание «я» (<em>ahaṃsaṃjñā</em>)</li>
            <li>и распознавание существ (<em>sattvasaṃjñā</em>),</li>
            <li>такой бодхисаттва называется</li>
            <li>утвердившимся в парамите нравственности (<em>śīlapāramitā</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.7</strong></li>
            <li>Если бодхисаттва, шествующий по пути Победителей,</li>
            <li>разделяет существ, мысля:</li>
            <li>«Эти соблюдают нравственность, а эти нарушают её», —</li>
            <li>погружённый в распознавание многообразия (<em>nānātvasaṃjñāprasṛta</em>),</li>
            <li>он в высшей степени безнравственен (<em>paramaṃ duśīla</em>).</li>
            <li>Его нравственность порочна (<em>chidraśīla</em>),</li>
            <li>и она не является совершенно чистой (<em>pariśuddhaśīla</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.8</strong></li>
            <li>У того, кто лишён распознавания «я» (<em>ahaṃsaṃjñā</em>)</li>
            <li>и распознавания существ (<em>sattvasaṃjñā</em>),</li>
            <li>кто свободен от влечения к распознаванию (<em>saṃjñāvirāga</em>), —</li>
            <li>откуда у него может взяться несдержанность (<em>asaṃvara</em>)?</li>
            <li>Тот, у кого нет самомнения (<em>manyanā</em>)</li>
            <li>ни относительно сдерживания (<em>saṃvara</em>),</li>
            <li>ни относительно несдерживания (<em>asaṃvara</em>),<a href="#citation-192" id="ref-192" class="citation-mark"><sup>192</sup></a></li>
            <li>провозглашён Наставником</li>
            <li>пребывающим в нравственной дисциплине (<em>śīlasaṃvara</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.9</strong></li>
            <li>Тот, кто, наделённый нравственностью (<em>śīlasamanvāgata</em>),</li>
            <li>свободен от разрастания умопостроений (<em>niṣprapañca</em>),</li>
            <li>равно беспристрастен ко всему приятному</li>
            <li>и неприятному (<em>anapekṣaka sarvapriyāpriyeṣu</em>),</li>
            <li>кто, отдавая голову, руки и ноги,</li>
            <li>сохраняет великодушный ум (<em>adīnacitta</em>), —</li>
            <li>тот отдаёт всё, что имеет,</li>
            <li>и всегда остаётся неослабным (<em>satataṃ alīna</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.10</strong></li>
            <li>Познав исконную природу дхарм (<em>dharmaprakṛti</em>)</li>
            <li>как порожнюю (<em>vaśikā</em>) и лишённую «я» (<em>nirātmya</em>),</li>
            <li>он великодушно (<em>adīnacitta</em>) отдаёт</li>
            <li>даже собственную плоть (<em>ātma-māṃsa</em>) —</li>
            <li>разве он не отдаст имущество?</li>
            <li>Невозможно, чтобы он проявил скупость (<em>matsarin</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.11</strong></li>
            <li>Из распознавания «я» (<em>ahaṃsaṃjñā</em>) возникают</li>
            <li>присвоение себе (<em>mamatā</em>)<a href="#citation-193" id="ref-193" class="citation-mark"><sup>193</sup></a> и привязанность (<em>rāga</em>).</li>
            <li>Как у заблуждающихся (<em>mūḍha</em>) возникнет</li>
            <li>мысль о даянии (<em>tyāgabuddhi</em>)?</li>
            <li>Скупые (<em>mātsarya</em>) рождаются в мире претов,</li>
            <li>а если рождаются людьми, то крайне бедными (<em>daridrarūpa</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.12</strong></li>
            <li>Поняв, что эти существа бедны, бодхисаттва устремляется к дарению</li>
            <li>и всегда отдаёт свободно и щедро.</li>
            <li>Отдав четыре великолепно украшенных континента,</li>
            <li>словно плевок (<em>kheṭatulya</em>), он ликует (<em>udagra</em>),</li>
            <li>ибо не удержал эти континенты за собой.<a href="#citation-194" id="ref-194" class="citation-mark"><sup>194</sup></a></li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.13</strong></li>
            <li>Совершив даяние, мудрый и учёный бодхисаттва,</li>
            <li>обратив мысль (<em>samanvāharitvā</em>) ко всем существам трёх миров,<a href="#citation-195" id="ref-195" class="citation-mark"><sup>195</sup></a></li>
            <li>[думая]: «Пусть это даяние (<em>datta-dāna</em>) будет дано всем им!» —</li>
            <li>и посвящает его высшему пробуждению ради блага мира.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.14</strong></li>
            <li>Совершив даяние, он не делает его опорой-зависимостью (<em>vastuniśraya</em>)</li>
            <li>и никогда не ожидает созревания плода.<a href="#citation-196" id="ref-196" class="citation-mark"><sup>196</sup></a></li>
            <li>Так отпуская [дар], мудрый становится отдающим всё (<em>sarvatyāgī</em>):</li>
            <li>отдав малое, он обретает многое — неизмеримое (<em>bahu aprameyam</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.15</strong></li>
            <li>Если бы все существа без исключения, сколько их есть в трёх мирах,</li>
            <li>на протяжении бесконечных кальп, — допустим (<em>parikalpa</em>),<a href="#citation-197" id="ref-197" class="citation-mark"><sup>197</sup></a> —</li>
            <li>совершали даяния Буддам, Знающим мир,</li>
            <li>Архатам и пратьекабуддам,</li>
            <li>[но устремлялись бы] к качествам шраваков,<a href="#citation-198" id="ref-198" class="citation-mark"><sup>198</sup></a> —</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.16</strong></li>
            <li>и если мудрый бодхисаттва, искусный в средствах (<em>upāyakauśala</em>),</li>
            <li>сорадуется (<em>anumodayitvā</em>) основанию их благого деяния</li>
            <li>и посвятит [эту заслугу] высшему,</li>
            <li>превосходному пробуждению ради блага существ,</li>
            <li>то, будучи наделён таким посвящением (<em>pariṇāmayukta</em>),</li>
            <li>он превосходит весь мир.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.17</strong></li>
            <li>Подобно тому как один драгоценный камень вайдурья (<em>vaiḍūrya-ratna</em>)</li>
            <li>превосходит (<em>abhibhoti</em>) огромную кучу стеклянных самоцветов,</li>
            <li>точно так же бодхисаттва, совершающий посвящение (<em>sarvapariṇāmaka</em>),</li>
            <li>превосходит (<em>abhibhoti</em>) обширную массу дарений всего мира.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_31.18</strong></li>
            <li>Если бодхисаттва, совершая даяние миру,</li>
            <li>не порождает к этому чувства присвоения (<em>mamatā</em>)</li>
            <li>и не привязан к вещам (<em>vastu-prema</em>), —</li>
            <li>от этого возрастает его благой корень (<em>kuśalamūla</em>),</li>
            <li>наделённый великим могуществом (<em>mahānubhāva</em>),</li>
            <li>подобно сияющему диску луны в светлую половину месяца.</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается тридцать первая глава, именуемая «Дхармодгата» (<em>Dharmodgataparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

    <!-- Глава 32 -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Глава 32. О посвящении (<em>Parīndanāparivartaḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.1</strong></li>
            <li>Даянием (<em>dāna</em>) бодхисаттва отсекает удел претов,</li>
            <li>искореняет нищету и все омрачения (<em>sarvakleśa</em>).</li>
            <li>Практикуя даяние, он обретает бесконечное и обильное богатство</li>
            <li>и посредством даяния приводит к зрелости существ, попавших в беду.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.2</strong></li>
            <li>Нравственностью (<em>śīla</em>) он избегает многообразных уделов животных,</li>
            <li>отвергает восемь неблагоприятных [состояний] (<em>aṣṭa akṣaṇa</em>)</li>
            <li>и постоянно обретает благоприятную возможность (<em>kṣaṇa</em>).</li>
            <li>Терпением (<em>kṣānti</em>) он обретает превосходный (<em>parama</em>)</li>
            <li>и благородный (<em>udāra</em>) облик (<em>rūpa</em>),<a href="#citation-199" id="ref-199" class="citation-mark"><sup>199</sup></a> кожу золотистого цвета,</li>
            <li>и становится любим миром,</li>
            <li>приковывая к себе восхищённые взоры (<em>udīkṣaṇīya</em>).</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.3</strong></li>
            <li>Усердием (<em>vīrya</em>) он не допускает утраты светлых качеств (<em>śuklaguṇa</em>),</li>
            <li>обретает бесконечное (<em>ananta</em>) знание (<em>jñāna</em>) —</li>
            <li>сокровищницу Победителей (<em>jinakośagañja</em>).</li>
            <li>Дхьяной он отбрасывает презренные услады чувственных желаний,</li>
            <li>обретает ве́дение (<em>vidyā</em>),<a href="#citation-200" id="ref-200" class="citation-mark"><sup>200</sup></a> сверхзнания (<em>abhijñā</em>) и самадхи.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.4</strong></li>
            <li>Мудростью (<em>prajñā</em>), всесторонне постигнув (<em>parijānayitvā</em>)</li>
            <li>исконную природу дхарм (<em>dharmaprakṛti</em>),</li>
            <li>он совершенно выходит за пределы трёх миров и неблагих уделов.</li>
            <li>Вращая драгоценное колесо (<em>cakraratna</em>) Будд,</li>
            <li>этих быков среди людей (<em>puruṣarṣabha</em>),</li>
            <li>он возвещает (<em>deśeti</em>) Дхарму миру ради полного прекращения страдания.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.5</strong></li>
            <li>Исполнив (<em>paripūrayitvā</em>) эти дхармы, бодхисаттва охватывает</li>
            <li>и чистоту земли [Будды] (<em>kṣetraśuddhi</em>), и чистоту существ (<em>sattvaśuddhi</em>).</li>
            <li>Он охватывает (<em>parigṛhṇati</em>) и род Будды (<em>buddhavaṃśa</em>),</li>
            <li>и род Дхармы (<em>dharmavaṃśa</em>), и равно род Сангхи (<em>saṃghavaṃśa</em>);</li>
            <li>он охватывает (<em>parigṛhṇati</em>)<a href="#citation-201" id="ref-201" class="citation-mark"><sup>201</sup></a> все дхармы.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>Rgs_32.6</strong></li>
            <li>Высший врач (<em>vaidyottama</em>), исцеляющий болезни мира,</li>
            <li>изложил этот путь пробуждения</li>
            <li>как наставление в мудрости (<em>prajñopadeśa</em>).</li>
            <li>Имя ему — «Собрание драгоценных качеств» (<em>ratnaguṇasaṃcaya</em>),</li>
            <li>путь пробуждения; все существа достигнут по нему [пробуждения].</li>
        </ul>

        <p class="text-center italic text-gray-600 mt-4">Так завершается тридцать вторая глава, именуемая «О посвящении» (<em>Parīndanāparivarta</em>), в Бхагавати, «Собрании драгоценных качеств в строфах» (<em>Bhagavatyāṃ Ratnaguṇasaṃcayagāthāyām</em>).</p>
    </div>

    <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">

        <div class="absolute inset-0 flex items-center">
            <div class="w-full border-t border-sky-300"></div>
        </div>
        <span class="relative bg-sky-50 px-4 text-xl text-sky-700">
            ❈ ❈ ❈
        </span>
    </div>

</div>

<div>
    <!-- Заключительные строфы -->
    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Заключительные строфы, сочинённые ачарьей Харибхадрой (<em>ācāryaharibhadrakṛtā praśastiḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>HPr 1</strong></li>
            <li>Чтобы легко привести мир на стезю,</li>
            <li>несущую два вида блага (<em>saṃpaddvayāvāhinīm</em>),<a href="#citation-202" id="ref-202" class="citation-mark"><sup>202</sup></a></li>
            <li>[эта сутра] была явлена (<em>saṃdīpitam</em>) Благословенным Буддой,</li>
            <li>чей ум устремлён к состраданию (<em>kāruṇyāhitacetasā</em>).</li>
            <li>Пусть те, кто пришли сюда, услышав (<em>śrutvā</em>) эту сутру —</li>
            <li>вместилище истинной природы всех дхарм (<em>akhiladharmatattvanilayaṃ</em>) —</li>
            <li>и должным образом приняв её (<em>samādānataḥ</em>),</li>
            <li>достигнут [высшей] обители (<em>sthānaṃ gatvā</em>)</li>
            <li>и денно и нощно выжигают свои загрязнения.</li>
        </ul>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>HPr 2</strong></li>
            <li>В этот век Кали, переполненный множеством воззрений,</li>
            <li>когда даже чтение [текстов] пришло в упадок,</li>
            <li>увидев разночтения строф, встречающиеся во многих рукописях,</li>
            <li>ныне, согласно надлежащему рассуждению (<em>nyāyataḥ</em>),</li>
            <li>ради блага мира мной, Хари Бхадрой (<em>bhadreṇa hariṇā mayā</em>),<a href="#citation-203" id="ref-203" class="citation-mark"><sup>203</sup></a></li>
            <li>очищено и исправно устроено [это произведение].</li>
            <li>Пусть мудрые (<em>budhaiḥ</em>) примут его —</li>
            <li>яму для сокрушения лобных бугров слонов-вождей в споре.<a href="#citation-204" id="ref-204" class="citation-mark"><sup>204</sup></a></li>
        </ul>
    </div>

    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Колофон</h3>
    <div>
        <p>В соответствии с разделами (<em>parivarta</em>) «Благородной Бхагавати Праджняпарамиты в восьми тысячах [строф]» (<em>Āryāṣṭasāhasrikā Bhagavatī Prajñāpāramitā</em>) завершена «Бхагавати, Собрание драгоценных качеств в строфах» (<em>Bhagavatī Ratnaguṇasaṃcayagāthā</em>).<a href="#citation-205" id="ref-205" class="citation-mark"><sup>205</sup></a></p>

        <ul class="list-none ml-8 space-y-2 mb-8">
            <li>Те дхармы, которые возникают из причин (<em>ye dharmā hetuprabhavā</em>), —</li>
            <li>их причину (<em>hetuṃ teṣām</em>) Татхагата действительно изрёк (<em>tathāgato hy avadat</em>);</li>
            <li>и их прекращение (<em>teṣāṃ ca yo nirodhaḥ</em>) —</li>
            <li>так учит великий шрамана (<em>evaṃvādī mahāśramaṇaḥ</em>).<a href="#citation-206" id="ref-206" class="citation-mark"><sup>206</sup></a></li>
        </ul>
    </div>

    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Заключительная строфа писца (<em>lekhakapraśastiḥ</em>)</h3>
    <div>
        <ul class="list-none ml-8 space-y-2 mb-8">
            <li><strong>LPr 1</strong></li>
            <li>Кто бы ни читал Дхарму, изречённую Сугатой (<em>sugatagadita</em>),</li>
            <li>с чувством преданности (<em>bhaktibhāvāt</em>),</li>
            <li>если при чтении каким-либо образом будут пропущены или искажены</li>
            <li>метрическая мера (<em>mātrā</em>), слово (<em>pada</em>), стопа (<em>pāda</em>),</li>
            <li>строфа (<em>gāthā</em>) или слог (<em>akṣara</em>) —</li>
            <li>из-за изъянов языка (<em>jihvādoṣa</em>), движений ветра (<em>pavanacarita</em>)</li>
            <li>или проявления расстройств слизи (<em>śleṣmadoṣapracāra</em>), —</li>
            <li>вы, будды, пребывающие в благих обителях (<em>subhavanagata</em>),</li>
            <li>и бодхисаттвы, простите [эти ошибки] (<em>kṣamadhvam</em>).</li>
        </ul>
        <p class="text-center italic text-gray-600 mt-4">Завершено (<em>samāptam</em>). Благо (<em>śubham</em>).</p>
    </div>

    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Тибетский колофон</h3>
    <div>
        <p>Индийский наставник (<em>rgya gar gyi mkhan po</em>) Видьякарасимха (<em>Vidyākarasiṃha</em>)<a href="#citation-207" id="ref-207" class="citation-mark"><sup>207</sup></a> и великий редактор-переводчик (<em>zhu chen gyi lotsāba</em>), монах (<em>bande</em>) Палцег (<em>dpal brtsegs</em>)<a href="#citation-208" id="ref-208" class="citation-mark"><sup>208</sup></a> перевели [текст] (<em>bsgyur</em>), сверили [перевод] (<em>zhus</em>) и окончательно утвердили его (<em>gtan la phab pa</em>).</p>
    </div>

    <h3 class="text-center mt-6 mb-4 text-lg font-bold">Работа над переводом</h3>
<div>
    <p>
        <strong>Перевод с санскрита, предисловие и примечания:</strong> О. Л. Волошановский.
    </p>
    <p class="my-6">
        При работе над переводом учитывались тибетская версия Кангьюра D13 и китайский перевод Фасяня (T.229).
    </p>
</div>

