<!-- Примечания -->
<h3 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h3>
<div class="citations mt-4 text-lg">
    <p></p>
    <p class="my-2" id="citation-1"><sup>1</sup> О стихотворном тексте <em>Rgs</em>, его редакционной истории и соотношении стихотворной и прозаической версий см.: Conze, 1973; Yuyama, 1973, 1976. Конзе рассматривал первые две главы как возможный древнейший слой текста; эта датировка выражает его исследовательскую позицию.<a href="#ref-1" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-2"><sup>2</sup> <em>Rgs</em> 25.1 — обучение без схватывания обучающегося; <em>Rgs</em> 6.5 — посвящение без закрепления за посвящающим; <em>Rgs</em> 1.24–1.25 и 7.4 — сострадание без схватывания существа как самостоятельно существующего.<a href="#ref-2" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-3"><sup>3</sup> Edgerton, 1953. Термин Buddhist Hybrid Sanskrit получил систематическое описание в работе Эджертона.<a href="#ref-3" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-4"><sup>4</sup> Conze, 1973. Датировку первых двух глав приблизительно I веком до н. э. — I веком н. э. следует понимать как гипотезу о раннем слое <em>Rgs</em>. См. также обсуждение истории Праджняпарамиты у Yuyama, 1973, 1976.<a href="#ref-4" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-5"><sup>5</sup> О соотношении восьми <em>abhisamaya</em> и структуры «Абхисамая-аланкары» см.: Conze, 1954; Makransky, 1997. Седьмое и восьмое ясные постижения связаны с <em>ekakṣaṇa-abhisamaya</em> и <em>dharmakāya</em>.<a href="#ref-5" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-6"><sup>6</sup> О различии рецензий A и B см.: Yuyama, 1973, 1976. Рецензия A — 32-главная редакция, связанная с Харибхадрой; сведения о Рецензии B и её соотношении с A следует рассматривать в рамках текстологического анализа Юямы.<a href="#ref-6" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-7"><sup>7</sup> Полное название сочинения Харибхадры: <em>Abhisamayālaṃkārālokā-nāma-prajñāpāramitopadeśaśāstra</em>; краткое название — <em>Ālokā</em>. О комментарии и его месте в истории изучения «Аштасахасрики» см.: Jaini, 1972.<a href="#ref-7" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-8"><sup>8</sup> О споре вокруг интерпретации восьмой главы «Абхисамая-аланкары», трёх- и четырёхчастной схемах Тел Будды, а также их восприятии в Индии и Тибете см.: Makransky, 1997. Макрански показывает, что Харибхадра понимал главу как изложение четырёх Тел, тогда как Арья Вимуктисена — трёх; позднее спор продолжился в тибетских школах.<a href="#ref-8" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-9"><sup>9</sup> О различии <em>satyākāravāda</em> и <em>alīkākāravāda</em> в буддийской философии см.: Kajiyama, 1966.<a href="#ref-9" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-10"><sup>10</sup> Санскритский текст Рецензии A опубликован у Vaidya, 1961. Для сопоставления использованы тибетская версия D13 и китайская версия T.229. Нумерация строф и глав в переводе соответствует Рецензии A.<a href="#ref-10" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-11"><sup>11</sup> Анаватапта (санскр. <em>Anavatapta</em>, пали <em>Anotatta</em>, тиб. <em>Ma dros pa</em> — «Ненагретое», «Неиспытывающее жара», «Не нагреваемого жаром») — в буддийской традиционной космологии священное озеро, расположенное к северу от Великих Снежных гор и к югу от горы Гандхамадана. В некоторых географических традициях его отождествляли с озером Манасаровар на Тибетском нагорье, однако в контексте сутр оно представляет собой прежде всего образ буддийской космографии. Согласно космологическим описаниям (в частности, связанным с «Абхидхармакошей» Васубандху), из Анаватапты берут начало четыре великие реки Джамбудвипы: Ганга (<em>Gaṅgā</em>), Синдху (<em>Sindhu</em>), Вакшу (<em>Vakṣu</em>) и Сита (<em>Śītā</em>), чьи воды несут прохладу и питают земли обитаемого мира.<br><br>В озере обитает царь нагов — мифический владыка вод, который в некоторых традициях Махаяны описывается как бодхисаттва, принявший облик царя нагов для блага существ. Его присутствие в озере обеспечивает сохранность и непрерывность водного потока, питающего мир.<br><br>Автор сутры устанавливает параллель: реки, текущие по Джамбудвипе благодаря могуществу (<em>anubhāva</em>) владыки нагов, соотносятся с речами учеников Будды (<em>śrāvaka, jinaputra</em>). Их проповедь, согласованная с разумным обоснованием (<em>yuktisahita</em>), и изложение плодов практики рассматриваются в контексте проявления Татхагаты (<em>puruṣākāra</em>). Тем самым образ Анаватапты служит обоснованию авторитета проповеди учеников: их способность излагать Дхарму и раскрывать смысл пути соотносится с могуществом Будды (<em>buddhānubhāva</em>), от которого зависит действие Учения в мире.<a href="#ref-11" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-12"><sup>12</sup> Санскритское <em>cetanā</em> обозначает волевую направленность ума, побуждение, намерение, стремление; в буддийской психологии это психический фактор, направляющий деятельность ума и связанный с действием.<a href="#ref-12" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-13"><sup>13</sup> <em>Aparigṛhīta</em> буквально означает «не схваченный», «не присвоенный». Тибетское <em>yongs su gzung med</em> передаёт отсутствие схватывания или присвоения. У Конзе представлены обе стороны этой характеристики: дхармы не удерживают практикующего, и сам он не схватывает дхармы. В переводе принято «ничего не присваивая», что непосредственно согласуется с тибетским свидетельством.<a href="#ref-13" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-14"><sup>14</sup> Шреника (санскр. <em>Śreṇika</em>) — странствующий аскет (<em>parivrājaka</em>), известный по буддийским повествованиям о беседах с Буддой. В <em>Ratnaguṇasaṃcayagāthā</em> 1.7 его имя служит отсылкой к преданию о Шренике Ватсаготре, который исследовал вопрос о Татхагате и его отношении к пяти скандхам. В изложении, сохранённом в <em>Śreṇikaparivrājaka-sūtra</em> и переданном Нагарджуной в <em>Mahāprajñāpāramitāśāstra</em>, Шреника принимает объяснение Будды, согласно которому Татхагату нельзя установить ни в скандхах, ни вне их, ни независимо от них. Этот рассказ получил особое значение в махаянском истолковании шуньяты дхарм.<a href="#ref-14" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-15"><sup>15</sup> В санскритском тексте читается <em>anupādapade</em> — «в состоянии неприсвоения». Тибетский перевод <em>skye med gnas</em> («состояние невозникновения») и перевод Э. Конзе (<em>the track of non-production</em>) поддерживают чтение <em>anutpādapade</em>. В основном тексте принято последнее чтение. Форма asakta означает «непривязанный», «не склонный»; в данном контексте она характеризует отсутствие направленности к состоянию невозникновения.<a href="#ref-15" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-16"><sup>16</sup> <em>vidyā/avidyā</em>; тиб. <em>yod/med</em>.<a href="#ref-16" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-17"><sup>17</sup> <em>mahādāyaka</em>; изд. <em>mahanāyaka</em>; тиб. <em>gtong ba che</em>.<a href="#ref-17" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-18"><sup>18</sup> Намучи (санскр. <em>Namuci</em>, тиб. <em>bdud kyi sgyu 'dul ba</em>) — персонаж древнеиндийской мифологии, противник Индры в ведийских преданиях (Индра не мог победить его обычным оружием из-за клятвы не убивать Намучи «ни сухим, ни мокрым, ни днем, ни ночью». В итоге Индра обезглавил его на рассвете (стык дня и ночи) с помощью морской пены, которая не является ни сухой, ни мокрой), который в буддийской традиции стал одним из имён Мары — искусителя, препятствующего освобождению существ из круговорота рождений и смертей. Имя <em>Namuci</em> традиционно истолковывается как «не отпускающий» (от <em>na</em> — «не» и корня <em>muc</em> — «освобождать, отпускать»). В ранней буддийской поэзии, в частности в Падхана-сутте (<em>Suttanipāta</em>), Намучи выступает как имя Мары, пытающегося отвратить Будду от достижения пробуждения.<br><br>В строфе 1.18 <em>Ratnaguṇasaṃcayagāthā</em> выражение «поразить коварного Намучи» (<em>śaṭha Namuci</em>) обозначает победу бодхисаттвы над силами, препятствующими пробуждению. Эпитет <em>śaṭha</em> указывает на коварство и обманчивость противника. В контексте Праджняпарамиты эта победа связана с совершенствованием мудрости, свободной от улавливания дхарм и цепляния за представления об их самостоятельном существовании.<br><br>В буддийской доктрине различают четыре Мары (<em>caturmāra</em>): Мару скандх, Мару клеш, Мару смерти (<em>mṛtyumāra</em>) и Мару — сына богов (<em>devaputramāra</em>). Вместе они обозначают различные препятствия на пути к освобождению: обусловленность психофизического существования, омрачения, смерть и привязанность к чувственным удовольствиям. В учении Праджняпарамиты препятствия могут возникать и из самого стремления схватить дхармы как существующие самостоятельно или утвердиться в определённом представлении о нирване. Поэтому образ бодхисаттвы, облачённого в великие доспехи (<em>mahatā sanaddha</em>) и поражающего Намучи, выражает решимость следовать пути мудрости, не поддаваясь обманчивым препятствиям и не цепляясь за дхармы.<a href="#ref-18" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-19"><sup>19</sup> изд. <em>bandhu na ca mukta</em>; тиб. <em>ma bcings ma grol</em>.<a href="#ref-19" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-20"><sup>20</sup> <em>anabhisaṃskṛta</em>; тиб. <em>'dus ma byas</em>.<a href="#ref-20" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-21"><sup>21</sup> Строфа построена на игре слов, связанных с √<em>sthā</em> («стоять», «пребывать»): <em>asthita, athita, sthita, sthāna, asthāna</em>. Наставник не пребывает ни в сфере несоставного, ни в сфере составного, странствуя без обители. Подобным образом бодхисаттва пребывает без опоры. Это парадоксальное пребывание без опоры Победитель и называет пребыванием. Тибетский текст (<em>gnas la gnas med gnas; gnas med gnas</em>) и перевод Конзе (<em>without a support or a basis</em>) подтверждают такое истолкование. Формы <em>asthitaka, athita</em> и <em>asthānu sthānu</em> сохранены по санскритскому варианту текста.<a href="#ref-21" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-22"><sup>22</sup> Слово <em>kṣānti</em> (тиб. <em>bzod pa</em>) означает «терпение», «принятие», «堪忍 (способность выдерживать/соглашаться с истиной)». Возможно имеется в виду <em>anutpattika-dharma-kṣānti</em>, «стойкость в понимании невозникновения дхарм».<a href="#ref-22" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-23"><sup>23</sup> <em>māyā-upama</em>; изд. <em>ātmaja</em>; тиб. <em>sgyu ma lta bur</em>. Принят тибетский вариант.<a href="#ref-23" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-24"><sup>24</sup> Санскр. <em>vṛddhi</em> — «возрастание, увеличение», <em>parihāṇi</em> — «убывание, уменьшение», <em>parigraha</em> — «схватывание, удерживание, принятие». Буквально выражение <em>rūpa-vṛddhi-parihāṇi-parigraha</em> означает «схватывание возрастания или убывания формы». Возможный смысл выражения связан с общей установкой Праджняпарамиты, согласно которой дхармы не следует схватывать как окончательно определённые и закреплённые объекты. Бодхисаттва, таким образом, не обучается ради схватывания формы в категориях её увеличения или уменьшения. Вместе с тем возможны и более конкретные истолкования. Если форму понимать как способ выражения мудрости, её увеличение могло бы означать ошибочное представление о возрастании самой мудрости посредством умножения форм её выражения. Если же форма понимается как совокупность недостатков и препятствий, уменьшение таких форм могло бы представляться целью практики мудрости. Оба толкования остаются предположительными: ни санскритская конструкция, ни доступные параллельные версии сами по себе не позволяют установить, какое из них подразумевалось.<a href="#ref-24" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-25"><sup>25</sup> Санскр. <em>vividha</em> — «разнообразный, различный», <em>dharma</em> — «дхарма», <em>parigraha</em> — «схватывание, принятие, удерживание». В контексте Праджняпарамиты это выражение можно понимать как схватывание разнообразных дхарм в качестве определённых, доступных закреплению объектов.<a href="#ref-25" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-26"><sup>26</sup> В этой строке повторяется глагольная основа √<em>grah</em> — «схватывать, брать, принимать»: в предыдущих строках она входит в состав <em>parigraha</em> («схватывание»), а здесь выступает в глагольной форме <em>parigṛhṇāti</em>. Возникает смысловое сближение двух положений: бодхисаттва обучается, не стремясь схватывать форму или разнообразные дхармы, и при этом <em>parigṛhṇāti</em> всеведение. Перевод «обретает всеведение» передаёт смысл выражения, но скрывает эту словесную игру. Повтор одного корня подчёркивает различие между схватыванием отдельных форм и дхарм и обретением всеведения; при этом нельзя исключить, что здесь намеренно используется один глагольный образ в обоих случаях.<a href="#ref-26" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-27"><sup>27</sup> Санскр. <em>niryāyati</em> — «выходит», «выступает», «отправляется», в буддийском контексте также может обозначать вступление на путь выхода из сансары. Тибетское соответствие <em>nges 'byung</em> связано со значениями отречения и выхода из сансарного существования. Поэтому перевод «вступает на путь выхода [из сансары]» передаёт контекстуальный смысл выражения; слов «из сансары» в санскритской строке нет.<a href="#ref-27" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-28"><sup>28</sup> <em>Apratikūla-bhāṇī</em> — буквально «говорящий непротивно», «говорящий приятно, согласно». Эпитет характеризует качество речи Победителя. В тибетском переводе (<em>'thun par smra gyur</em>) выражение передано как «говорить в согласии», а у Э. Конзе соответствующий смысл включён в прямую речь Будды: <em>all I said and did at last agreed with perfect wisdom</em>. Таким образом, параллельные переводы связывают этот эпитет с согласованностью речи и высшей праджняпарамиты, хотя в санскритском тексте он стоит в авторском повествовании как характеристика Победителя.<a href="#ref-28" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-29"><sup>29</sup> <em>parāpuruṣottamena</em>; тиб. <em>sngon gyi skyes mchog</em>.<a href="#ref-29" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-30"><sup>30</sup> Сторона Мары (<em>māra-pakṣa</em>). Санскр. <em>pakṣa</em> означает «сторона», «крыло», «партия», «приверженцы»; тиб. <em>bdud kyi phyogs</em> соответствует выражениям «сторона Мары», «воинство Мары», «приверженцы Мары», то есть обозначает силы и факторы, которые удерживают сознание существ в пределах сансары и препятствуют достижению пробуждения.<br><br>Внешний, мифологический смысл выражения охватывает свиту Мары и силы, препятствующие освобождению. К ним относятся сыновья и дочери Мары, олицетворяющие чувственные искушения (вожделение, страсть, недовольство); устрашающие демоны — пишачи, ракшасы и якши, пытающиеся напугать практикующего во время созерцания; обусловленные мирские божества (девы), заинтересованные в том, чтобы существа оставались в пределах сферы желаний (<em>kāma-dhātu</em>) и сферы форм (<em>rūpa-dhātu</em>) и не уходили в нирвану.<br><br>В доктринальном толковании к этим силам относят также внутренние препятствия на пути: омрачения (<em>kleśa</em>) — гнев, привязанность, гордыню, неведение и зависть, метафорически уподобляемые «солдатам» в армии Мары; ошибочные воззрения и ложные взгляды (<em>dṛṣṭi</em>); привязанность к умственным построениям и образам-знакам. В таком прочтении «сторона Мары» обозначает всё, что поддерживает обусловленное существование и мешает освобождению.<br><br>В строфе 3.1 сказано, что Мара и его приспешники не смогут подступиться / не найдут в нём лазейки [или: уязвимого места] / не обретут над ним власти [или доступа ] (<em>avatāra</em>) к тому, кто держит и осваивает Праджняпарамиту. Это можно понимать как указание на отсутствие зацепки, посредством которой препятствия могли бы нарушить практику бодхисаттвы. Такое истолкование согласуется с направленностью Праджняпарамиты на преодоление привязанности к признакам и умственным построениям, хотя непосредственно в данной строфе эти внутренние препятствия не перечисляются.<a href="#ref-30" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-31"><sup>31</sup> Коти (<em>koṭi</em>) — крупное числовое обозначение в индийской системе счисления, обычно соответствующее десяти миллионам (10⁷). В буддийских текстах часто употребляется в сочетаниях с другими числительными, например <em>koṭi-niyuta</em>, и служит для обозначения чрезвычайно больших количеств.<a href="#ref-31" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-32"><sup>32</sup> <em>Mahāvidyā</em> — буквально «великое ведение» (от √<em>vid</em> — «ведать, знать»). Термин <em>vidyā</em> обозначает знание, ведение, а в определённых контекстах — сакральное и действенное знание, включая мантрическое. В этой строфе такое понимание поддерживается тибетским <em>rig sngags che</em> («великое заклинание», «знание-формула») и передачей Э. Конзе <em>great lore</em> («великое ведение»). Сопоставление с заключительным <em>vaidya-rāja</em> («царь врачевателей») дополнительно позволяет отметить целительный смысловой оттенок этого знания. В основном тексте сохранено «ведение», поскольку санскритский оригинал содержит <em>vidyā</em>, а не <em>mantra</em>.<a href="#ref-32" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-33"><sup>33</sup> <em>Duḥkha-dharma-śoka-śamanī</em> — «умиротворяющее дхармы, которые ведут к скорби и страданию». Согласно словарю Э. Конзе (<em>Materials for a Dictionary of the Prajñāpāramitā Literature</em>, с. 225b), <em>duḥkha-dharma-śoka</em> означает <em>dharmas making for sorrow and ill</em> («дхармы, вызывающие скорбь и страдание»), что подтверждается тибетской параллелью <em>mya ngan sdug bsngal chos zhi byed</em> («та, что умиротворяет дхармы скорби и страдания»). В данном контексте основа <em>duḥkha-dharma-śoka</em> действует как единый смысловой комплекс (сложное слово), обозначающий явления, ведущие к скорби и страданию.<a href="#ref-33" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-34"><sup>34</sup> <em>Prajñāparibhāvita pūjayanti</em> допускает два прочтения. В основном переводе: «те, кто взращён (пропитан) мудростью, почитают [мощи]». Тибетский перевод <em>shes rab yongs su bsgoms pas mchod par bgyid</em> поддерживает такое понимание. Э. Конзе относит характеристику к самим мощам: они почитаются, поскольку «взращены [пропитаны] мудростью» (<em>fostered by wisdom</em>). Последующая строка, где мощи Будды названы опирающимися на Праджняпарамиту, согласуется и с этим прочтением.<a href="#ref-34" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-35"><sup>35</sup> В рукописном тексте Rgs читается <em>anupādu śūnya na ya jānati sarvadharmān</em>. Тибетский канонический перевод (<em>chos kun skye med stong pa'i tshul du rab shes pa</em>) и перевод Э. Конзе (<em>By the method of emptiness and non-production [he] cognizes all dharmas</em>) понимают сочетание <em>na ya</em> как <em>naya</em> («способом», «методом»). В основном переводе принято это прочтение: <em>jānati</em> передано глаголом «познаёт», а <em>naya</em> — словом «способом». <em>anupādu</em> из переводимого санскритского текста соответствует санскритскому <em>anutpāda</em> («невозникновение»).<a href="#ref-35" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-36"><sup>36</sup> <em>gamayanti</em> от √<em>gam</em> здесь означает «разъясняют», «делают понятным» (тиб. <em>ston byed</em>; Конзе: <em>make ... intelligible</em>). Местный падеж <em>śūnyatāyām</em> указывает, что дхармы разъясняются в шуньяте.<a href="#ref-36" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-37"><sup>37</sup> <em>Śrāvaka ... pratyekabodhi ... buddhabodhim</em>. Тибетский перевод и версия Конзе разделяют три результата: освобождение шраваков, пробуждение пратьекабудд и пробуждение будд. Субъекты двух последних результатов в санскритской строке прямо не названы и восполняются по параллельным переводам.<a href="#ref-37" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-38"><sup>38</sup> <em>Śakra-brahma-phala śrāvaka-prādurbhāvaḥ</em>. Сложное слово <em>śakra-brahma-phala</em> допускает различные прочтения. Тибетский перевод (<em>'bras bu brgya byin tshangs pa nyan thos</em>) представляет <em>phala</em> («плод») как обобщающее понятие, за которым следуют Шакра, Брахма и шраваки. Китайский перевод Фасяня (亦無釋梵聲聞果) также связывает понятие плода со всеми тремя категориями. Э. Конзе иначе членит санскритскую строку, перечисляя Шакру, Брахму, плод и учеников. В основном переводе принято прочтение тибетской версии, согласующееся с образом плодов дерева в первой половине строфы.<a href="#ref-38" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-39"><sup>39</sup> Бхавана (<em>bhāvanā</em>) — «взращивание», «культивирование», «развитие». Образовано от основы <em>bhāvayati</em> («развивать», «производить», «взращивать»), связанной с корнем √<em>bhū</em> («быть», «становиться»). В буддийской традиции термин обозначает целенаправленное развитие определённых качеств ума и духовных способностей; в более широком употреблении — систематическую созерцательную практику, обычно передаваемую словом «медитация». Важнейшие её направления — <em>śamatha-bhāvanā</em>, взращивание умиротворения и сосредоточения, и <em>vipaśyanā-bhāvanā</em>, развитие прозрения и постигающей мудрости (<em>prajñā</em>). В зависимости от контекста <em>bhāvanā</em> может обозначать как конкретный метод практики, так и процесс последовательного развития духовных качеств.<a href="#ref-39" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-40"><sup>40</sup> <em>Anumodanā</em> — сорадование (тиб. <em>rjes su yi rang ba</em>). Один помысл сорадования превосходит совокупную заслугу всех шравак; смысл сорадования раскрывается в 6.5–6.9: оно совершается без обнаруживания.<a href="#ref-40" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-41"><sup>41</sup> <em>Koṭi</em> и <em>niyuta</em> — числовые обозначения больших величин. По одной из систем счёта <em>koṭi</em> соответствует десяти миллионам (10⁷), а <em>niyuta</em> — миллиону (10⁶); в других системах значения иные. Составное <em>koṭi-niyuta</em> в строфе выражает чрезвычайно большое количество будд.<a href="#ref-41" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-42"><sup>42</sup> <em>Pariṇāmanā</em>, посвящение, направление заслуг (тиб. <em>bsngo ba</em>). Практика передачи накопленного блага ради пробуждения всех живых существ. Глагол <em>pari-ṇam</em> (букв. «склонять(ся) к чему-то», «преобразовывать»).<a href="#ref-42" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-43"><sup>43</sup> <em>Trisaṅgayukta</em> — «связанный тройной привязанностью» (тиб. <em>gsum la chags</em>); три члена названы в строфе: распознавание (<em>saṃjñā</em>), воззрение (<em>dṛṣṭi</em>), мысль (<em>citta</em>).<a href="#ref-43" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-44"><sup>44</sup> <em>Upalabhyamāna —</em> «обнаруживаемое», «устанавливаемое [в качестве наличного объекта]» (от <em>upa</em>-√<em>labh</em>). В контексте строфы речь идёт о посвящении, при котором сохраняется установление [объектной опоры] — того, чему посвящаются заслуги. Такое посвящение противопоставляется посвящению без установления (без обнаружения опоры), описанному далее.<a href="#ref-44" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-45"><sup>45</sup> <em>Kṣīṇa</em> буквально «исчерпано, истощено» и относится как к дхармам, так и к тому, куда они посвящаются (<em>tac caita kṣīṇa pariṇāmayiṣyanti yatra</em>; тиб. <em>gang du yongs su bsngo ba de yang zad pa</em>). В контексте 6.5–6.7 это означает отсутствие устанавливаемого предмета посвящения.<a href="#ref-45" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-46"><sup>46</sup> <em>Viṣasṛṣṭa bhojana</em> — «пища, смешанная с ядом»; <em>kriyāpraṇīta</em> — «хорошо приготовленная». Строфа сравнивает обнаружение благого (<em>śukladharma</em>) с ядом в хорошей пище: основание — 6.5–6.6, где посвящение с обнаружением названо неподлинным; посвящение без образов-знаков обращено к пробуждению.<a href="#ref-46" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-47"><sup>47</sup> <em>Na ca so hi buddha kṣipate</em>. Глагол <em>kṣipate</em> (от √<em>kṣip</em>) означает «отбрасывает», «оставляет», «отвергает»; такое прочтение поддерживается тибетским <em>sangs rgyas mi spong</em> («не отвергает / не оставляет Будду»). Э. Конзе переводит эту формулу как <em>does not upset the Buddha</em> («не огорчает Будду»). В шестой главе <em>Aṣṭasāhasrikā Prajñāpāramitā</em> (<em>Anumodanāpariṇāmanāparivarta</em>) соответствующая мысль выражена через отказ порочить Татхагат (<em>na ca tāṃs tathāgatān ... abhyākhyāti</em>) и указание, что бодхисаттва, правильно радуясь и посвящая заслугу, не ошибается (<em>anaparāddho bhavati</em>). Это содержательно связано с <em>jina uktavādī</em> («следующий словам Победителя»). В той же главе посвящение с опорой на образы-знаки (<em>nimittayogena</em>) сравнивается с отравленной пищей (<em>saviṣaṃ bhojanam</em>), тогда как правильное посвящение названо неотравленным (<em>nirviṣaḥ pariṇāmaḥ</em>). Этим объясняется тибетское <em>dug med</em> («неотравленный») в начале второй строки строфы.<a href="#ref-47" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-48"><sup>48</sup> <em>Upalambhika-bodhisattva</em>. Буквально — «бодхисаттва, опирающийся на <em>upalambha</em>». Тибетское <em>dmigs can</em> означает «имеющий объект», «обладающий объектной опорой». В данном контексте так называются бодхисаттвы, чьё посвящение заслуг сопровождается схватыванием объекта. Герой (<em>śūra</em>), посвящающий заслуги без такого схватывания, превосходит их; ср. 1.25, где также проводится различие между посвящением с объектной опорой и посвящением без неё.<a href="#ref-48" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-49"><sup>49</sup> <em>Puṇya</em> — в данном контексте означает не религиозную «заслугу», а «награду», «плату» или «гонорар» ремесленнику за выполненную работу (см. Buddhist Hybrid Sanskrit Dictionary Ф. Эджертона, с. 348a: <em>reward, fee</em>). Такое значение подтверждается тибетским переводом <em>rngan pa</em> («плата, вознаграждение») и передачей Э. Конзе <em>fee</em> («гонорар»; ср., однако, китайский перевод Фасяня 無功德, где термин передан в стандартном буддийском значении «заслуга»). Метафора может быть связана с традиционной индийской иконописной практикой, в которой завершающим этапом создания изображения служит прорисовка глаз (<em>netronmīlana</em>).<a href="#ref-49" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-50"><sup>50</sup> <em>Yadā prajñāpāramitā gacchati saṃkhyāṃ loke</em>. Идиоматическое выражение <em>saṃkhyāṃ gacchati</em> (тиб. <em>grangs su 'gro</em>) буквально означает «входит в счёт / в число», а по смыслу — «именуется», «получает наименование», «становится известной». Э. Конзе передаёт его как <em>one comes to speak in the world of the perfection of wisdom</em> («в мире заходит речь о совершенстве мудрости»). Подлежащее — сама Праджняпарамита. Ср. Rgs 7.2, где говорится об обретении наименования (<em>nāmadheya</em>).<a href="#ref-50" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-51"><sup>51</sup> Но не [пребывающие] в освобождении — смысловое восполнение по тибетскому каноническому переводу: <em>khams gsum yang dag 'das la rnam par grol ba'ang min</em> («полностью вышли за пределы трёх миров, но не освобождены»). В санскритском тексте читается <em>traidhātukaṃ samatikrānta na bodhisattvā</em>: отрицательная частица <em>na</em> не сопровождается явно выраженным сказуемым, которое уточняло бы, что именно отрицается. Э. Конзе в своём переводе эту частицу не отражает (<em>Having transcended what belongs to the triple world, the Bodhisattvas</em>...). Принятое в основном тексте прочтение следует тибетской версии. В доктринальном отношении его можно соотнести с идеей непребывающей нирваны (<em>apratiṣṭhita-nirvāṇa</em>): бодхисаттва преодолевает сансару, сохраняя деятельность ради блага живых существ.<a href="#ref-51" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-52"><sup>52</sup> <em>Prajñāya pāramita paśyati bodhisattvo</em>. Сочетание допускает двоякое синтаксическое прочтение. Тибетский перевод (<em>chos rnams thams cad rang bzhin dag cing yongs dag par | byang chub sems dpa' shes rab pha rol phyin lta na</em>) и Э. Конзе (<em>The Bodhisattva sees that all dharmas and the Perfection of Wisdom Are pure...</em>) рассматривают Праджняпарамиту как объект глагола <em>paśyati</em> («видит») наряду со всеми дхармами. В основном тексте принято это прочтение. Возможно также такое понимание сочетания — «видит посредством Праджняпарамиты», если считать форму <em>prajñāya</em> средством действия и допустить усечение окончания.<a href="#ref-52" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-53"><sup>53</sup> <em>Paśyaka</em> — «видящий»; тиб. <em>byed pa po</em> («деятель»). В основном тексте принято санскритское чтение.<a href="#ref-53" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-54"><sup>54</sup> <em>Yujyati — prayujyati</em>. В строфах 10.1 и 10.2 обыгрываются однокоренные формы от √<em>yuj</em> («соединять, впрягать, прилагать усилия, упражняться»): <em>yujyati</em> в 10.1 и <em>prayujyati</em> в 10.2. Тибетский перевод передаёт их соответственно через <em>brtson</em> («усердствовать, прилагать усилия») и <em>sbyor byed pa</em> («прилагать себя к обучению»); Э. Конзе сохраняет игру слов в 10.1 посредством <em>engaged in / joined</em>. В русском переводе смысловая связь передана через «посвящает себя» и «усердно посвящает себя».<a href="#ref-54" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-55"><sup>55</sup> <em>Bahuyojanehi</em> (в тексте <em>bahubhījanehi</em>). В переводе принято исправление <em>bahuyojanehi</em> («на протяжении многих йоджан»), поддерживаемое тибетским <em>dpag tshad mang por</em> (<em>dpag tshad = yojana</em>) и переводом Э. Конзе (<em>extending over many miles</em>).<a href="#ref-55" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-56"><sup>56</sup> <em>Na ca tasya trāso</em>. В санскритской строке объект страха не назван. Тибетский перевод (<em>chom rkun 'jigs pa med</em>), китайская версия Фасяня (無賊怖) и перевод Э. Конзе (<em>fear of thieves</em>) уточняют, что речь идёт о страхе перед ворами или разбойниками. В переводе это дополнение заключено в квадратные скобки.<a href="#ref-56" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-57"><sup>57</sup> <em>Śrutvā</em> (в тексте <em>śṛṇu tāta</em> — «слушай, дорогой»). Тибетский перевод (<em>shes rab pha rol phyin 'di mnyan pa gang thob pa</em>) и перевод Э. Конзе (<em>when he learns of this wisdom</em>) передают смысл услышанного учения, не сохраняя обращения. Поэтому в основном переводе принято значение «услышав». Возможное исходное <em>śrutvā</em> («услышав») представляет собой реконструкцию, согласующуюся с параллельными переводами; установить её как первоначальное чтение на основании приведённых свидетельств нельзя.<a href="#ref-57" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-58"><sup>58</sup> <em>Patite tṛṇapatraśākhā</em>. Форма <em>patite</em> (от √<em>pat</em>) допускает два прочтения. При классическом понимании <em>patita</em> — «опавший» — сочетание можно истолковать как указание на опавшие травы, листья и ветви. Однако в буддийском гибридном санскрите <em>patita</em> употребляется также в значении «появившийся, возникший» (см. Buddhist Hybrid Sanskrit Dictionary Ф. Эджертона, с. 316b, где это значение иллюстрируется данной строфой). Такое прочтение соответствует весеннему контексту (<em>suvasanti kāli</em>) и поддерживается параллельными переводами: тибетским (<em>sdong po lo ma lhags gyur na</em> — «когда на дереве появились листья»), китайским (春生諸草木 — «весной произрастают травы и деревья») и переводом Э. Конзе (<em>when the stalks and leaves have come out</em>). В переводе принято значение «появились».<a href="#ref-58" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-59"><sup>59</sup> <em>Dharmā adharma imu paśyati dharmadhātuṃ</em>. В рукописном тексте <em>Rgs</em> стоит <em>imu</em> («эту»), тогда как тибетский перевод (<em>chos dang chos min chos dbyings mi mthong zhing</em>) и перевод Э. Конзе (<em>does not see dharma, nor no-dharma, nor the Dharma-element</em>) передают всю последовательность с отрицанием. В переводе принято прочтение тибетской и английской версий; отрицание перед <em>paśyati</em> во второй строке восполнено по параллелям.<a href="#ref-59" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-60"><sup>60</sup> В 10.9 принято чтение «не обнаруживает ни дхарм, ни не-дхарм, ни сферы Дхармы (дхармадхату)». Санскр. <em>dharmā adharma imu paśyati dharmadhātuṃ</em> стоит без отрицания («видит дхармы, не-дхармы, сферу Дхармы»); тиб. <em>gang zhig chos dang chos min chos dbyings mi mthong zhing</em> отрицает все три члена. Основания принятого чтения: 1) соседние строки образуют ряд отрицаний (<em>na ca rūpavṛddhi na ca paśyati pārihāṇim</em>, «не обнаруживает ни возрастания, ни убывания формы»; <em>na ca nirvṛtiṃ spṛśati</em>, «не касается нирваны»), и тиб. продолжает этот ряд; 2) в праджняпарамитных текстах не обнаруживаются ни дхарма, ни не-дхарма (ср. Ваджраччхедика, о «дхармах и не-дхармах»), поэтому утверждение «видит дхармы и не-дхармы» противоречило бы смыслу строфы; 3) 10.10 продолжает тему: он не выстраивает мысленно дхармы будды, силы и основы сверхобычных способностей. Положительное чтение санскрита («видит дхармы и не-дхармы как сферу Дхармы») грамматически возможно и не принято по тем же основаниям.<a href="#ref-60" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-61"><sup>61</sup> Вадичандра (<em>vādicandra</em>) — букв. «Луна среди спорщиков» или «Луна среди говорящих». Почётный эпитет Будды, подчеркивающий его превосходство в красноречии, логике и мастерстве изложения Дхармы. Термин является классическим санскритским <em>upamita-samāsa</em>, «сложным словом-сравнением», где существительное <em>candra</em> («луна») используется на конце слова как метафора высшего качества, чистоты и сияния. Подобно тому как луна своим светом затмевает звёзды на ночном небе, Будда своей речью и мудростью затмевает всех остальных философов, ораторов и учителей своего времени (<em>vādin</em> — «говорящий», «философский спорщик»).<a href="#ref-61" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-62"><sup>62</sup> <em>Pratibhāna</em>. Обычно означает «красноречие», «находчивость»; тиб. <em>spobs pa</em>. В буддийской терминологии <em>pratibhāna-pratisaṃvid</em> обозначает одно из четырёх аналитических знаний — способность свободно и находчиво излагать Дхарму. Э. Конзе передаёт слово контекстуально как <em>flashes of ideas</em> («вспышки идей»). В данном переводе сохранён образ «вспышек», раскрывающийся через значения красноречия и находчивости. Подлежащее <em>parihāyiṣyanti</em> — подразумеваемое <em>pratibhānāni</em> («проявления красноречия и находчивости»).<a href="#ref-62" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-63"><sup>63</sup> <em>hastiṃ labhitva</em> — «найдя слона»; тиб. <em>glang po rnyed nas</em>.<a href="#ref-63" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-64"><sup>64</sup> В этой строфе Праджняпарамита уподобляется корню или целому слону, тогда как другие сутры — ветвям и листьям или следу слона. Образ подчёркивает ошибочность отказа от главного учения ради поиска чего-то второстепенного.<a href="#ref-64" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-65"><sup>65</sup> <em>Ṣaṣṭika</em> — скороспелый (шестидесятидневный) рис, простая пища; тиб. <em>zas ngan</em> («плохая пища»). В сравнении обретение лучшей пищи (<em>bhojanāgrya</em>, тиб. <em>zas mchog</em>) противопоставлено поискам простой.<a href="#ref-65" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-66"><sup>66</sup> <em>Kāryayukta</em> — буквально «занятый делом», «погружённый в дела» (<em>kārya</em> — «дело, занятие, забота»; <em>yukta</em> — «занятый, погружённый»). Это значение подтверждается тибетским <em>bya ba ldan</em> («занятый делом»). В контексте главы о деяниях Мары речь может идти об отвлечении проповедника посторонними заботами. Э. Конзе интерпретирует выражение иначе — как нежелание проповедника выполнять свою работу (<em>disinclined to do his work</em>).<a href="#ref-66" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-67"><sup>67</sup> <em>Ya imaṃ durlābhu dharmaratanaṃ parāpuṇanti</em>. В санскритском тексте стоит утвердительная форма <em>parāpuṇanti</em> («обретают эту труднодоступную драгоценность Дхармы»). Это прочтение согласуется с притчей предыдущей строфы (11.9): подобно тому как обретение драгоценности вызывает появление врагов, стремящихся её отнять, обретение драгоценности Дхармы вызывает противодействие Мары. Тибетский перевод (<em>gang zhig dkon pa'i rin chen 'di ni ma rnyed pa</em> — «которые ещё не обрели эту редкую драгоценность») и Э. Конзе (<em>He does not [at once] obtain this Dharma-jewel</em>) передают отрицательное прочтение. Согласно этой версии, Мара чинит препятствия начинающему бодхисаттве, не давая ему обрести Дхарму. В основном тексте сохранено утвердительное чтение санскритского свидетельства, согласующееся с контекстом 11.9.<a href="#ref-67" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-68"><sup>68</sup> <em>Citta-carita</em> (букв. «деятельность ума», «образ действий ума», «то, как движется ум» других существ) обозначает характерные способы умственной деятельности и устойчивые склонности ума. Такое понимание подтверждается и тибетским переводом <em>sems kyi spyod pa</em> — «деятельность, поведение ума». Праджняпарамита названа той, что показывает эту деятельность.<a href="#ref-68" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-69"><sup>69</sup> <em>Ekaiva bhāvavigatā tathatā ananyā prajñāya pāramita buddha tathāgatena</em>. Прилагательное <em>ananyā</em> («неиная», «неизменная»; тиб. <em>gzhan min</em>, у Конзе: <em>unaltering</em>) относится к <em>tathatā</em> («таковость») наряду с <em>ekaiva</em> («одна-единственная») и <em>bhāvavigatā</em> («свободная от бытия»). В заключительной части строки <em>prajñāya pāramita</em> — Праджняпарамита, <em>buddha</em> — причастие от √<em>budh</em> («познанная, постигнутая»), <em>tathāgatena</em> — творительный падеж деятеля («Татхагатой»). Тибетский перевод (<em>shes rab pha rol phyin pa de bzhin gshegs pas mkhyen</em>) и передача Э. Конзе (<em>Has the perfection of wisdom been understood by the Tathagata</em>) подтверждают, что Праджняпарамита является предметом постижения Татхагаты. В контексте предшествующего перечисления таковостей она постигается как единая таковость.<a href="#ref-69" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-70"><sup>70</sup> <em>Ākāśaniśrita ... prajñāpāramitāniśrita</em>. В строфах 12.6–12.7 повторяется причастие <em>niśrita</em> (от <em>ni</em>- + √<em>śri</em>) — «опирающийся на», «нашедший опору в», «пребывающий в зависимости от». В первой половине строфы 12.7 солнечные лучи (<em>sūryaraśmi</em>) опираются на пространство (<em>ākāśa</em>), во второй Царь Дхармы (<em>dharmarāja</em>) — на Праджняпарамиту (<em>prajñāpāramitā</em>). Такое прочтение подтверждается тибетским переводом: <em>nam mkhar gnas pa'i</em> («пребывающие в пространстве») и <em>shes rab pha rol phyin rten pa</em> («опирающийся на Праджняпарамиту»), а также переводом Э. Конзе, который в обоих случаях использует <em>supported by</em>. Тот же эквивалент <em>niśrita</em> — «опирающийся на» — сохраняется в строфах 12.6 и 20.5. Повтор слова подчёркивает смысловую параллель: подобно тому как солнечные лучи опираются на пространство, Царь Дхармы опирается на Праджняпарамиту, благодаря которой иссушает реку жажды и являет дхарму.<a href="#ref-70" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-71"><sup>71</sup> <em>Dharmata śrāvakāṇām</em>. Санскритская форма <em>dharmata</em> допускает чтение <em>dharmatā</em> («дхармата», «природа дхарм»). Однако тибетский перевод <em>nyan thos chos rnams</em> («дхармы шраваков») и версия Э. Конзе <em>dharmas of the Disciples</em> («дхармы учеников») передают это выражение во множественном числе: Праджняпарамита осуществляет (<em>karoti</em>) деяния будд (<em>buddhakriyā</em>) и дхармы шраваков (<em>dharmata śrāvakāṇām</em>). Китайский перевод 佛行法及聲聞等 также не даёт однозначного подтверждения чтению <em>dharmatā</em>. В основном тексте сохранена санскритская форма; её интерпретация как «дхарматы шраваков» представляет собой буквальное прочтение, тогда как параллельные версии поддерживают значение «дхармы шраваков».<a href="#ref-71" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-72"><sup>72</sup> В издании <em>bhṛtakaṃ</em> («наёмник, слуга»); тиб. <em>ro</em> («труп»). Принято «труп»: вероятно, в санскритском тексте <em>bhṛtaka</em> — описка или неверное прочтение <em>mṛtaka</em> («мёртвый, труп»), которое поддерживается тибетским переводом и образом плавучего тела, за которое хватаются при кораблекрушении. Санскритское <em>bhṛtaka</em> в значении «труп» не засвидетельствовано; для трупа есть <em>mṛtaka</em>, <em>śava</em>, kalevara.<a href="#ref-72" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-73"><sup>73</sup> <em>Bhāvasvabhāva</em> — «собственная природа явлений» как предмет искусности. Согласно 1.28 (<em>prakṛty-asanta</em>, «лишены собственной природы») и 12.3 (<em>bhāvavigatā</em>), это знание того, что у явлений нет собственной природы; формулировка «сведущ в собственной природе явлений» не утверждает, что такая природа есть.<a href="#ref-73" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-74"><sup>74</sup> В тиб. этой строфы нет слов о знании собственной природы явлений и о высшем смысле; тиб. даёт «охваченные умением в средствах (<em>upāya</em>) и мудростью (<em>prajñā</em>)». Принято санскритское чтение.<a href="#ref-74" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-75"><sup>75</sup> <em>Taṃ caiva śraddha parigṛhṇayamāna prajñā</em>. Буквально: «и когда мудрость охватывает эту [его] веру». <em>Śraddha</em> (<em>śraddhām</em>) выступает прямым дополнением, а <em>prajñā</em> — субъектом действия: мудрость охватывает веру. Такое распределение подтверждается тибетским переводом <em>dad pas shes rab kyis ni yongs su zin gyur na</em> («когда вера охвачена мудростью») и китайским 能發信心持般若, где также выражена связь веры с поддерживающей её Праджней. Перевод Э. Конзе (<em>when taken hold of by both faith and by wisdom</em>) объединяет веру и мудрость в качестве двух участников конструкции и не сохраняет этого различия. Смысловое соответствие обнаруживается в строфе 7.2, где другие добродетели также должны быть охвачены мудростью (<em>pragṛhīta prajñā</em>).<a href="#ref-75" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-76"><sup>76</sup> <em>Bhūmidvaya</em>. В тексте читается <em>bodhidvaya</em> («два пробуждения»); тибетское <em>sa gnyis</em> («две ступени») поддерживает вариант <em>bhūmidvaya</em>, встречающийся в строфе 14.1. В переводе принято «две ступени». Уточнение «шраваков и пратьекабудд» допустимо как контекстуальное пояснение, но не является буквальным содержанием данной формы.<a href="#ref-76" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-77"><sup>77</sup> Санскр. bodhim upaiti hānim буквально означает «терпит ущерб в отношении пробуждения» или «приходит к упадку в отношении пробуждения». Тибетский текст (byang chub las ni myur nyams 'gyur) также указывает на упадок (<em>nyams</em>) в отношении пробуждения, тогда как китайская версия (離般若行遠菩提) подчёркивает удаление от пробуждения при отступлении от практики Праджняпарамиты. В переводе «отдаляется от пробуждения» передан общий смысл этих параллелей: отсутствие мудрости ведёт к ухудшению продвижения бодхисаттвы к пробуждению.<a href="#ref-77" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-78"><sup>78</sup> <em>Bhajyati antareṇa</em>. Глагол <em>bhajyati / bhajyate</em> (от √<em>bhañj</em> — «ломаться, разбиваться, сокрушаться») связывает строфу 14.10 с предшествующими сравнениями этой главы: необожжённый глиняный кувшин (<em>āmaghaṭa</em>) разбивается от воды, а ветхий корабль терпит крушение посреди океана (14.8–14.9). Этот образный ряд продолжается в строфе 20.11, где дряхлый старец (<em>jīrṇa mahallaka</em>) ломается на пути. В переводе во всех этих случаях сохранён единый глагол «ломаться»; ср. передачу Э. Конзе в 14.10: <em>breaks down midway / does not break down</em>.<a href="#ref-78" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-79"><sup>79</sup> <em>Adhyāśaya</em> (тиб. <em>lhag pa'i bsam pa</em>; Конзе: <em>resolute intention</em>) — «решительное намерение», «искреннее устремление», «высокий помысел». Слово образовано с помощью усилительной приставки <em>adhi</em>- и <em>āśaya</em> («намерение», «расположение ума»).<a href="#ref-79" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-80"><sup>80</sup> <em>Bodhiskandha</em>. Буквально «скандха пробуждения» или «пробуждение как скандха». Тибетский перевод <em>byang chub phung por zhen nas mchog 'dzin ma byed</em> («не цепляйтесь за пробуждение, привязавшись к нему как к скандхе») и передача Э. Конзе (<em>having considered [it as belonging to] the skandhas</em>) поддерживают такое прочтение. Речь идёт о предостережении против схватывания пробуждения как предмета присвоения, рассматриваемого по образцу скандх.<a href="#ref-80" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-81"><sup>81</sup> <em>Ye ādikarmika na deśayitavya evam</em>. Заключительная часть строфы представлена в двух расходящихся текстологических версиях.<br><br>Чтение с отрицанием засвидетельствовано в санскритском тексте (<em>na deśayitavya evam</em> — «так не следует наставлять») и китайском переводе Фасяня (勿為初地如是說 — «не следует так говорить начинающим»). Согласно этому прочтению, начинающим не следует сразу сообщать наставление о неприсвоении пробуждения. Оно допускает сопоставление со строфами 15.1–15.2, где подчёркивается значение постепенного обучения под руководством благого друга.<br><br>Чтение без отрицания представлено в тибетском каноническом переводе (<em>dang po'i las can de la de skad bstan par bya</em> — «начинающим следует объяснять именно так») и у Э. Конзе (<em>It is thus that it should be demonstrated to beginners</em>). Согласно этой версии, начинающих следует наставлять именно в неприсвоении пробуждения, чтобы с самого начала направить их практику в соответствии с мудростью.<br><br>Таким образом, первое прочтение подчёркивает необходимость постепенного раскрытия наставления, второе — важность раннего усвоения принципа неприсвоения. В основном тексте сохранено отрицательное чтение санскритского свидетельства; тибетская и английская версии отражают альтернативную редакцию.<a href="#ref-81" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-82"><sup>82</sup> <em>duṣkara-saṃnāha</em> — буквально «доспехи для трудновыполнимого деяния» или «снаряжение для совершения трудного». <em>Duṣkara</em> означает «трудный для совершения», «трудновыполнимый»; <em>saṃnāha</em> — «снаряжение», «облачение в доспехи». В махаянском контексте выражение передаёт образ бодхисаттвы, который принимает на себя труднейшую задачу достижения пробуждения ради блага живых существ. Метафора доспехов подчёркивает решимость и готовность выдерживать трудности на пути бодхисаттвы.<a href="#ref-82" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-83"><sup>83</sup> Невозвратные (<em>avivartika</em>, вариант: <em>avinivartanīya</em>) — буквально «не поворачивающие назад», «не отступающие». В махаяне термин обозначает бодхисаттв, которые достигли такой ступени духовного пути, на которой уже не отступают от движения к пробуждению. Тибетский эквивалент <em>phyir mi ldog pa</em> буквально означает «не возвращающиеся назад». В настоящем переводе последовательно используется слово «невозвратные»: оно сохраняет образ движения по пути и позволяет избежать нежелательных современных ассоциаций слова «необратимые».<a href="#ref-83" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-84"><sup>84</sup> <em>vilekha</em> — колебание, смятение; буквально «царапание», «нанесение царапин, борозд, следов, ран». Слово связано с <em>vi</em>- и корнем √<em>likh</em> («царапать», «скрести», «разрезать», «разрывать»). В буддийских текстах обозначает состояние умственного смятения или беспокойства, замешательство, беспокойство ума, досада; в «Махавасту» встречается в призыве <em>chindahi saṃśayitāna vilekhaṃ</em> — «рассеки замешательство сомневающихся». В «Дашабхумика-сутре» <em>vilekha</em> упоминается в ряду состояний, связанных с воззрениями, сомнением и колебанием (<em>dṛṣṭi-kāṅkṣā-vimati-vilekha</em>).<a href="#ref-84" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-85"><sup>85</sup> <em>Alpotsuka</em> (санскр.; пали <em>appossukka</em>; тиб. <em>thugs khral chung bar mdzad</em>) — «не проявляющий рвения», «не склонный приступать к действию», «не расположенный [к действию]», «безучастный» (Конзе: <em>unconcerned</em>). В Rgs 15.7 слово характеризует состояние Будды после обретения пробуждения: осознав глубину и трудность постижения Дхармы, он задаётся вопросом, кто из существ сможет её понять, и не проявляет рвения приступать к её проповедованию. Этот мотив содержится в палийской «Махавагге» (Vinaya Piṭaka, Mahāvagga I.5) и в «Лалитавистаре» (гл. 25, Adhyeṣaṇā-parivarta — «Глава о просьбе [к проповеди]»), где Будда размышляет о глубине и трудности понимания постигнутой им Дхармы. В «Махавагге» прямо сказано, что ум Будды склоняется к покою, а не к проповеди Дхармы; затем Брахма Сахампати просит его учить ради существ, способных понять Учение. После этой просьбы Будда обозревает мир своим пробуждённым зрением и различает существ с различными способностями к постижению Дхармы, что передаётся сравнением с лотосами на разных стадиях роста в воде. Таким образом, <em>alpotsuka</em> обозначает временное отсутствие рвения к проповеди, обусловленное размышлением о трудности передачи Дхармы, а не утрату сострадания или окончательный отказ от учительства.<a href="#ref-85" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-86"><sup>86</sup> <em>Tathatā jinānām</em> (в тексте <em>tathatārhatānām</em>). В санскритском тексте <em>tathatārhatānām</em> («таковость архатов») повторено дважды — в конце второй и третьей строк. Во второй позиции принято исправленное чтение <em>tathatā jinānām</em> («таковость Победителей»), поддержанное тибетским переводом (<em>rgyal ba'i de bzhin nyid</em>), китайской версией Фасяня (一切佛法) и переводом Э. Конзе (<em>the Suchness of the Jinas</em>). Ср. аналогичный перечень таковостей в Rgs 12.3, где также присутствует <em>tathatā jinānām</em>.<a href="#ref-86" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-87"><sup>87</sup> <em>Upāyayukto</em> (в тексте <em>yāya yukto</em>). В санскритском издании Вайдьи читается <em>yāya yukto</em> («соединённый с которой»), относящееся к Праджняпарамите. Эта конструкция грамматически возможна, но создаёт смысловое повторение с предшествующим <em>yujyatu</em> («пусть соединится»). <em>upāyayukto</em> («наделённый искусными средствами») поддерживается тибетским <em>thabs dang ldan pas</em>, китайским 方便 и переводом Э. Конзе (<em>joined to skill in means</em>). Она согласуется также с парным упоминанием искусных средств и мудрости в 14.10 и 16.5. В переводе принято исправленное чтение.<a href="#ref-87" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-88"><sup>88</sup> <em>liṅga</em> — «знак», «признак», «отличительная черта». Многозначный термин индийской философии. В логике, в частности в ньяе, обозначает признак, служащий основанием для логического вывода о наличии другого свойства. В буддийских текстах значение <em>liṅga</em> определяется контекстом; его не следует безоговорочно отождествлять с <em>nimitta</em> («образ», «образ-знак») или <em>lakṣaṇa</em> («признак», «характеристика»). В этой главе термин употребляется в связи с признаками, по которым распознаётся невозвратный бодхисаттва (<em>avivartika</em> / <em>avinivartanīya</em>).<a href="#ref-88" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-89"><sup>89</sup> <em>araṇa</em> — «безмятежность», «отсутствие вражды и раздора», тиб. <em>nyon mongs ma mchis</em> («лишённые омрачений»). В буддийской традиции обозначает состояние, свободное от омрачений, враждебности и внутренних противоречий. В махаяне это понятие также связано с поведением пробуждённого существа, которое не порождает вражды и споров и наставляет других в Дхарме без разрастания конфликтов. Субхути известен как <em>araṇā-vihārin</em> — «пребывающий в безмятежности».<a href="#ref-89" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-90"><sup>90</sup> <em>yuktabhāṇin</em> — «говорящие разумную речь», «говорящий уместно», «говорящий должным образом». Это качество выступает как одно из отличительных черт невозвратности бодхисаттвы (<em>avinivartanīya-liṅga</em>). Оно указывает на способность говорить взвешенно и к месту, так, чтобы речь соответствовала Дхарме и приносила пользу живым существам.<a href="#ref-90" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-91"><sup>91</sup> <em>snigdhavākya</em> — «говорящий мягко и доброжелательно», «обладающий ласковой речью». Сложное слово, образованное от <em>snigdha</em> («мягкий», «ласковый», «доброжелательный») и <em>vākya</em> («слово», «высказывание»), выступает как одно из отличительных черт невозвратности бодхисаттвы (<em>avinivartanīya-liṅga</em>). Характеризует речь, лишённую грубости и враждебности, исполненную доброжелательности к слушателям.<a href="#ref-91" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-92"><sup>92</sup> <em>yugamātraprekṣin</em> — «смотрящий на расстояние одного ярма», то есть взирающий лишь на небольшое расстояние перед собой. Слово образовано из <em>yuga</em> («ярмо»; также мера длины), <em>mātra</em> («всего лишь», «только») и <em>prekṣin</em> («смотрящий», «взирающий»; от √<em>īkṣ</em> — «смотреть»); выражение связано с буддийским представлением о сдержанности взгляда и внимательности во время ходьбы. Ограничивая направление взора, практикующий избегает праздного разглядывания окружающего и уменьшает поводы для рассеянности. В этом смысле эпитет можно соотнести с практикой охраны органов чувств (<em>indriya-saṃvara</em>) и поддержания внимательности (<em>smṛti</em>). Здесь этот эпитет характеризует поведение бодхисаттвы в повседневной жизни. Он указывает на сдержанность и собранность, проявляющиеся даже в обычном движении тела.<a href="#ref-92" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-93"><sup>93</sup> <em>abhrāntacinta</em> — «обладающий безошибочным мышлением», «тот, чьё мышление не заблуждается». Сложное слово, образованное от <em>abhrānta</em> («не заблуждающийся», «не сбивающийся с пути») и <em>cinta</em> («мысль», «мышление»; от корня √<em>cint</em> — «мыслить», «размышлять»); этот эпитет характеризует мышление, свободное от заблуждений и ошибочного понимания Дхармы: мышление бодхисаттвы не сбивается с пути и не вводит его в заблуждение относительно практики и цели пути к пробуждению.<br><br>Важно различать отсутствие заблуждения и прекращение мышления как такового. <em>Abhrāntacinta</em> характеризует не безмыслие, а отсутствие ошибки в мышлении. В контексте Праджняпарамиты это качество можно соотнести с мудростью (<em>prajñā</em>), благодаря которой бодхисаттва не принимает ошибочные представления за истинное положение вещей и не уклоняется таким образом от пути к пробуждению. Однако само слово не содержит прямого указания ни на полное устранение неведения (<em>avidyā</em>), ни на конкретный способ постижения шуньяты (<em>śūnyatā</em>).<a href="#ref-93" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-94"><sup>94</sup> <em>śuciśaucāmbaradhara</em> — «носящий чистые одежды», «облачённый в безупречно чистое одеяние». Сложное слово, образованное из <em>śuci</em> («чистый»), <em>śauca</em> («чистота», «очищение»), <em>ambara</em> («одежда», «облачение») и <em>dhara</em> («носящий», «облачённый»; от √<em>dhṛ</em> — «держать», «нести»). Здесь этот эпитет характеризует чистоту его одежды и опрятность внешнего облика. Сочетание <em>śuci-śauca</em> подчёркивает чистоту. В контексте перечисления признаков невозвратности чистое одеяние можно рассматривать как внешнюю характеристику бодхисаттвы наряду с другими качествами, описывающими его речь, мышление и поведение.<a href="#ref-94" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-95"><sup>95</sup> <em>trivivekaśuddha</em> — «очищенный тройным уединением», «чистый благодаря тройному отстранению». Сложное слово, образованное из <em>tri</em> («три»), <em>viveka</em> («уединение», «отстранение», «различение») и <em>śuddha</em> («чистый», «очищенный»). Этот эпитет стоит рядом с характеристиками чистоты внешнего облика и отсутствия стремления к материальной выгоде. Такое окружение позволяет понимать тройное уединение не только как физическую отстранённость, но и как свободу поведения бодхисаттвы от мирских привязанностей и корыстных побуждений.<br><br>В махаянском истолковании этот смысл можно раскрыть через очищение трёх врат деятельности — тела (<em>kāya</em>), речи (<em>vāc</em>) и ума (<em>citta</em>). В таком прочтении телесные поступки, речь и намерения бодхисаттвы свободны от стремления к наживе (<em>lābhakāma</em>), жажды славы (<em>kīrtikāma</em>) и привязанности к вещам и явлениям (<em>vastu</em>).<a href="#ref-95" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-96"><sup>96</sup> <em>lābhakāma</em> — «жаждущий приобретений», «стремящийся к выгоде», «корыстолюбивый». Слово образовано из <em>lābha</em> («приобретение», «выгода», «прибыль»; в буддийском контексте также «подношения») и <em>kāma</em> («желание», «стремление», «страсть»). <em>lābha</em> может обозначать материальные блага, получаемые практикующими от мирян: пищу, одежду, лекарства и другие подношения. Поэтому <em>lābhakāma</em> характеризует человека, который стремится к приобретению таких благ и руководствуется корыстными интересами.<a href="#ref-96" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-97"><sup>97</sup> <em>vastu</em> — «вещь», «предмет», «имущество», «основа». Значение зависит от контекста.<br><br>В обыденном смысле <em>vastu</em> обозначает вещи, предметы или имущество. Выражение <em>anadhyoṣita-sarva-vastuṃ</em> характеризует бодхисаттв, которые, даже оставаясь мирянами (<em>gṛhibhūta</em>), не привязаны к вещам и имуществу. Тибетское <em>dngos po kun</em> — «все вещи» — подтверждает такое понимание.<br><br>В буддийской психологии <em>vastu</em> может обозначать материальную основу или опору сознания. В названиях произведений и разделов текстов слово употребляется также в значениях «предмет рассмотрения», «тема» или «повествование».<br><br>В философских текстах, особенно в Праджняпарамите, <em>vastu</em> может обозначать вещь или явление, воспринимаемое как нечто самостоятельное и существующее. В таком контексте важно различать само обозначение предмета и представление о нём как о чём-то обладающем собственной природой (<em>svabhāva</em>).<a href="#ref-97" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-98"><sup>98</sup> <em>Jīvikāviṣayabhoga.</em> Это сложное санскритское слово допускает два варианта разбора. Его можно понять либо как причинную связь — «чувственные наслаждения ради средств к существованию», либо как простое перечисление — «средства к существованию и чувственные наслаждения». В основном тексте принято первое прочтение: бодхисаттва, остающийся мирянином (<em>gṛhibhūta</em>), не отвергает честного пропитания, но не ищет чувственных наслаждений ради добывания средств к жизни. Такое понимание согласуется с тибетским переводом (<em>'tsho ba'i phyir ni ya ngas longs spyod tshol ma byed</em> — «ради пропитания не ищут предосудительных наслаждений») и версией Э. Конзе (<em>do not seek to earn their livelihood in the wrong way</em> — «не ищут заработка неправедным путём»). Последний перевод, по-видимому, опирается на предположение, что вместо слова <em>viṣaya</em> («сфера, объект чувств») здесь должно стоять похожее слово <em>viṣama</em> («неправедный, предосудительный»), которого, однако, нет в дошедшем до нас санскритском тексте.<a href="#ref-98" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-99"><sup>99</sup> <em>abhicāramantra</em> — «вредоносное заклинание», «магическое заклинание», «заклинание для магического воздействия». Состоит из <em>abhicāra</em> («колдовство», «магическое воздействие») и <em>mantra</em> («мантра», «заклинание»). Такие заклинания могли использоваться для подчинения, устрашения, причинения вреда или других целенаправленных воздействий.<a href="#ref-99" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-100"><sup>100</sup> <em>Istriprayogamantrāḥ</em> (правильное написание: <em>strīprayogamantra</em>). Это сложное санскритское слово можно истолковать двояко, смотря по тому, какую роль в нём играет часть <em>strī</em>- («женщина»):<br><br>1. Женщина как цель: «заклинания для воздействия на женщин» или «приворотные чары» (что совпадает с тибетским переводом <em>bud med sbyor sngags</em>). В таком случае речь идёт о любовной магии, цель которой — обольстить или подчинить себе женщину.<br><br>2. Женщина как исполнитель: «заклинания, которые применяют сами женщины» или «женское колдовство». Именно это прочтение выбрал Э. Конзе, переведя фразу как <em>the spells which are the work of women</em> («заклинания, сотворённые женщинами»).<a href="#ref-100" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-101"><sup>101</sup> Перевод следует тибетскому чтению: <em>'dod pa'i las can pho mor 'gyur zhes ston mi byed</em> — «не учат, что [тот, чьё дело — желание] станет мужчиной или женщиной». Выражение <em>'dod pa'i las can</em> можно понять как «тот, чьё дело — желание»; санскритское <em>icchākarman</em> допускает толкование «дело желания», хотя точное соотношение двух выражений остаётся не вполне ясным. Контекст предыдущей строфы, где отвергаются <em>strīprayogamantra</em> («заклинания для воздействия на женщин»), позволяет предположить, что речь идёт о наставлениях или ритуальных практиках, обещающих изменение пола или выбор пола при новом рождении. Санскритская конструкция остаётся неясной; поэтому в основном тексте принято тибетское чтение.<br><br>Во второй строке <em>pravivikta</em> — именительный падеж множественного числа мужского рода, согласованный с подразумеваемым подлежащим — бодхисаттвами: «уединённые». Тибетский текст связывает уединение с самой Праджняпарамитой: <em>rab tu dben pa'i shes rab pha rol phyin</em> — «уединённая высшая Праджняпарамита». Такое согласование не поддерживается санскритской формой <em>pravivikta</em>: для определения <em>prajñāpāramitā</em> потребовалась бы форма женского рода <em>praviviktā</em>. В основном тексте сохранено санскритское согласование, тибетское прочтение отмечаем как вариант.<a href="#ref-101" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-102"><sup>102</sup> В строфе используется метафора измерения глубины океана шестом. Человек, пытающийся достичь дна с помощью шеста, не может измерить глубину, если шест не достигает грунта (<em>alabdhagādha</em> — «глубина не обретена»). Подобным образом мудрость (<em>prajñā</em>), исследуя пять скандх — форму, чувство, намерение, сознание и распознавание, — не обнаруживает у них определяемой глубины. Образ раскрывает мысль строфы: скандхи не обладают той определённой, постижимой глубиной, которую можно было бы установить посредством исследования; они лишены признаков (<em>animitta</em>) и умиротворены (<em>śānta</em>).<a href="#ref-102" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-103"><sup>103</sup> <em>Gambhīrayānaparamārthanirupalepān.</em> Это длинное санскритское слово состоит из двух смысловых частей: <em>gambhīra-yāna</em> («глубокая колесница») и <em>paramārtha-nirupalepān</em> («в высшем смысле неоскверняемые»). Выражение <em>paramārtha</em> здесь выступает в роли пояснения («в абсолютном смысле», «с точки зрения высшей истины») к слову <em>nirupalepa</em> («неоскверняемые»). Такое прочтение полностью совпадает с версией Э. Конзе: <em>in the deep vehicle are in the ultimate sense stainless</em> («в глубокой колеснице [эти дхармы] в высшем смысле неоскверняемы»).<a href="#ref-103" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-104"><sup>104</sup> <em>Tata utthito</em> (тиб. <em>de las langs nas</em>; Конзе: <em>Emerged therefrom [i.e. that meditation]</em>) — буквально «поднявшись оттуда», «выйдя из этого». В контексте строфы выражение обозначает выход бодхисаттвы из созерцания высшей мудрости (<em>varaprajñā vibhāvayanto</em>) с последующим обращением к проповеди Дхармы. В буддийской созерцательной терминологии такое действие соответствует выходу из медитативного погружения (<em>vyutthāna, utthāna</em>). Уточнение «созерцания» восполняет подразумеваемый контекст и подтверждается тибетским переводом и пояснением Э. Конзе.<a href="#ref-104" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-105"><sup>105</sup> <em>Prathame nipāte ... arci paścimanipāta</em>. В санскрите здесь сравниваются два момента: <em>prathame nipāte</em> («при первом соприкосновении [с пламенем]») и <em>arci paścimanipāta</em> («при последнем соприкосновении пламени»). Тибетский перевод точно следует оригиналу и передаёт это как «первое соприкосновение» (<em>phrad pa dang po</em>) и «последнее соприкосновение пламени» (<em>me lce phrad pa tha ma</em>). Китайский же перевод, выполненный Фасянем, просто описывает, что свет появляется благодаря соединению условий — масла, фитиля и огня. Китайский текст передаёт общую суть (принцип зависимого происхождения вещей), но не повторяет в точности образность санскритского стиха.<br><br>Слова «сожжённый» (<em>dagdhā</em>) и «сжигается» (<em>dahyati</em>) подчёркивают главное: фитиль сгорает не в какой-то один отдельный миг — ни исключительно в первый, ни исключительно в самый последний. Весь процесс происходит постепенно, но в то же время сгорание невозможно без постоянного воздействия огня. В следующей строфе (19.2) этот пример с фитилём и пламенем объясняет, как бодхисаттва достигает пробуждения: не в один миг, а через цепочку сменяющих друг друга состояний ума.<a href="#ref-105" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-106"><sup>106</sup> Санскрит даёт <em>stamba</em> («стебель»), <em>phala</em> («плод»), <em>puṣpa</em> («цветок»). Тибетский перевод вместо <em>stamba</em> даёт <em>myu gu</em> («росток, побег») и ставит цветок перед плодом. В основном тексте сохранено санскритское чтение. Разделительный союз <em>vā</em> указывает на альтернативу: если семя пресеклось (<em>niruddha</em>) или отсутствует (<em>asat</em>), дерево из него не возникнет. Строфа иллюстрирует взаимозависимое возникновение (<em>pratītyasamutpāda</em>): первая мысль о пробуждении (<em>prathama-citta</em>), хотя и прекращается, выступает основанием последующего пробуждения (<em>bodhi</em>). Представление о преемственном процессе, ведущем от первой мысли к достижению буддовости, является контекстуальным пояснением.<a href="#ref-106" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-107"><sup>107</sup> Данная строфа отсутствует в тибетском каноническом переводе Видьякарасингхи и Палцега (IX в.), но представлена в санскритской рукописной традиции (Рецензия А) и в китайском переводе Фасяня (X–XI вв.). Кроме того, в отличие от архаичного слоя <em>Rgs</em>, написанного на буддийском гибридном санскрите, строфа 19.4 выдержана в нормативном классическом санскрите (<em>bījaṃ pratītya ca bhaved..., utpattito bhavati bodhir iyaṃ jinānām</em>), что позволяет рассматривать её как более позднюю редакционную вставку, раскрывающую принцип зависимого возникновения (<em>pratītyasamutpāda</em>) на классическом примере семени и ростка.<br><br><em>Na ca tad asti na cāpi nāsti</em> — букв. «и оно не существует, и не является несуществующим»; уточнение «[в семени как уже готовые]» поясняет подразумеваемую причинную связь (ср. у Э. Конзе: <em>Their fruits are in these [seeds], and yet they are not in them</em>). Прилагательное <em>bhāvasvabhāvavigatā</em> согласовано по женскому роду с существительным <em>māyā</em> («иллюзия, лишённая собственной природы явлений»).<a href="#ref-107" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-108"><sup>108</sup> Три характеристики — <em>śūnya</em>, <em>animitta</em>, <em>apraṇihita</em> — соответствуют тиб. <em>stong pa</em>, <em>mtshan med</em>, <em>smon pa med</em>. <em>Na nimittacārī</em> буквально характеризует того, кто не следует за образами-знаками.<a href="#ref-108" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-109"><sup>109</sup> <em>Aparāntakoṭi sadā yukta</em>. Устойчивый оборот <em>aparāntakoṭi</em> (буквально «предел / край будущего»; тиб. <em>phyi ma'i mu mtha'</em>, Конзе: <em>the limit which is further on</em>), парный к <em>pūrvāntakoṭi</em> («предел прошлого», ср. <em>Rgs</em> 1.23), в буддийской лексике обозначает необозримую перспективу будущего времени, «вплоть до конца будущего». В сочетании с <em>sadā yukta</em> («постоянно соединённые», тиб. <em>rtag tu brtson</em> — «постоянно усердствующие») это выражение указывает на непрерывность практики бодхисаттвы на всём протяжении будущего без мысли о её завершении, благодаря чему в его уме не возникает ни малейшей усталости (<em>aṇumātra kheda</em>).<a href="#ref-109" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-110"><sup>110</sup> Санскр. <em>mahāmaitrī</em> («великая любовь»); тиб. <em>snying rje</em> («сострадание»). Принято санскритское.<a href="#ref-110" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-111"><sup>111</sup> <em>Jagat</em> означает «мир»; добавление «[существ]» раскрывает связь мира с живыми существами, подразумеваемую контекстом. В заключительной части строфы <em>ākāśasthānu</em> допускает прочтение «установленное в пространстве» в связи с <em>nidāna</em> («основание»). Выражение «[вся эта взаимосвязь]» — реконструкция, распространяющая утверждение об установленности в пространстве на всю цепь опор. <em>Kutu cintayi etam artham</em> — риторический вопрос: «как это помыслить?»<a href="#ref-111" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-112"><sup>112</sup> Сочетание <em>sattvānāṃ jñāna-praṇidhāna-adhiṣṭhānam</em> допускает разные прочтения. Тиб. <em>sems can shes pa'i smon lam rten can gyis</em> и кит. 以眾生智及願力 поддерживают понимание «опираясь на знание и обеты, связанные с существами». В основном тексте предпочтено это чтение, а не «знание и обеты существ — его опора».<a href="#ref-112" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-113"><sup>113</sup> В строфе три слова от корня <em>sthā</em>: <em>pratiṣṭhita</em> («утвердившийся»), <em>adhiṣṭhāna</em> («опора»), <em>sthāna</em> («место стояния»); в 20.5 — <em>ākāśasthānu</em> («стоящее в пространстве»). Игра слов: бодхисаттва утверждён в том, что не является чем-то утверждаемым или утверждающим, а его опора — не опора в буквальном смысле. По-русски <em>pratiṣṭhita</em> и <em>sthāna</em> сведены к «утвердившийся / место утверждения»; <em>adhiṣṭhāna</em> передано как «опора» и из игры корней в переводе выпадает.<a href="#ref-113" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-114"><sup>114</sup> Трое врат освобождения (<em>trīṇi vimokṣadvārāṇi</em>; также <em>trīṇi vimokṣamukhāni</em>) — три созерцательных подхода, ведущих к освобождению: шуньята (<em>śūnyatā</em>), беззнаковость (<em>ānimitta</em>) и ненаправленность / свобода от стремлений (<em>apraṇihita</em>). В буддийской традиции их рассматривают как три способа постижения природы дхарм, благодаря которым преодолевается привязанность к обусловленному существованию.<br><br>Шуньята (<em>śūnyatā</em>) — постижение отсутствия у явлений собственной, независимой природы (<em>svabhāva</em>). Явления не существуют сами по себе, независимо от условий и связей.<br><br>Беззнаковость (<em>ānimitta</em>) — отсутствие цепляния за образы-знаки (<em>nimitta</em>), посредством которых ум распознаёт, обозначает и закрепляет в понятиях воспринимаемые явления. Речь идёт о непривязанности к признакам как к чему-то самостоятельно существующему.<br><br>Ненаправленность (<em>apraṇihita</em>) — отсутствие устремления к обусловленным явлениям и желания обрести в них опору. Это вовсе не означает отсутствия всякой мотивации или намерения: в буддийском контексте речь идёт об освобождении от желаний и устремлений, поддерживающих привязанность к сансарическому существованию.<a href="#ref-114" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-115"><sup>115</sup> <em>na deya bhūmim</em> — досл. «не давая места, почвы для падения».<a href="#ref-115" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-116"><sup>116</sup> <em>Chattradvaya</em> (тиб. <em>gdugs gnyis</em>, кит. 蓋) — буквально «два зонта». В древнеиндийской метафоре большие зонты, раскрытые в обеих руках, за счёт сопротивления воздуха замедляют падение с обрыва (в связи с чем Э. Конзе условно переводит это слово как <em>parachutes</em> — «парашюты»).<a href="#ref-116" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-117"><sup>117</sup> <em>Upakṣayeyyā</em>. Вероятно, искажённая или нестандартная форма; её точная грамматическая характеристика не установлена. Тибетское <em>mchong bar byed cing</em> («прыгая», «бросаясь вниз») и перевод Э. Конзе <em>would jump off</em> поддерживают значение «бросаются вниз».<a href="#ref-117" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-118"><sup>118</sup> <em>Ākāli vāyur avasṛjya mahāprapāte</em> — это очень запутанное и трудное для перевода место. Слово <em>ākāli</em> в дошедших до нас древних рукописях, скорее всего, записано с ошибкой вместо похожего слова <em>ākāśe</em> («в пространстве, в воздухе» — именно так его поняли тибетские переводчики, написавшие <em>nam mkha' la</em>, и Э. Конзе, переведя как <em>into space</em>). Однако чисто теоретически его можно прочесть и как <em>ākāle</em> («в нужный миг»).<br><br>Следующее сочетание слов <em>vāyur avasṛjya</em> буквально означает «выпустив или отпустив ветер». В то же время в тибетском переводе стоит фраза «оставив или бросив тело» (<em>lus bor nas</em>). Это говорит о том, что в самом древнем, несохранившемся оригинале (первоисточнике текста), возможно, стояли совсем другие санскритские слова — <em>kāyam avasṛjya</em> («бросив тело»). Чтобы не запутывать читателя, в русском переводе этот образ передан по общему смыслу — «доверившись ветру».<a href="#ref-118" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-119"><sup>119</sup> <em>Na ca prapāta patiyāti na yāva tatra</em> — буквально «и падение не падает, пока там» (в тибетском переводе: ltung bar mi 'gyur ji srid der ni 'gro bar 'gyur — «не падают, пока движутся там [по воздуху]»). Санскритский и тибетский тексты описывают замедленное парение в воздухе, при котором падающий не разбивается о дно пропасти, пока удерживается зонтами. Э. Конзе передаёт строку противоположным образом (Would go on falling until they had reached the ground — «продолжали бы падать, пока не достигли бы земли»), акцентируя непрерывность самого спуска, а китайский перевод Фасяня (如人經險遇大風… 直至無風乃前進) даёт иной образ: путник с зонтом не может идти против сильного ветра, пока ветер не стихнет.<a href="#ref-119" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-120"><sup>120</sup> <em>Duḥkhito manasi bhoti sa jātisaṃgho</em> допускает неоднозначное прочтение. Согласно Конзе, <em>duḥkhito</em> относится к <em>jātisaṃgho</em>: «страдающее собрание родичей пребывает в его мыслях». Возможно и отнесение <em>duḥkhito</em> к <em>sārthavāha</em>: «купец, печалясь, держит в уме своих родичей». Тибетский (<em>gnyen bshes tshogs yid mi bder 'jog pa min pa ltar</em>) и китайский (豈有眷屬心苦惱) допускают иное смысловое прочтение, при котором родичи не страдают благодаря возвращению купца с сокровищами. В переводе принято первое чтение — оно лучше согласуется с параллелью в 20.16, где бодхисаттва помнит о страдающих существах.<a href="#ref-120" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-121"><sup>121</sup> <em>Śūnyānimittapraṇidhī ... samādhim</em>. В строфе перечислены три составляющие классической триады освобождающих сосредоточений: шуньята (<em>śūnyatā</em>), свобода от образов-знаков (<em>ānimitta</em>) и отсутствие устремления (<em>apraṇihita</em>). Эта триада известна также как трое врат освобождения (<em>trīṇi vimokṣamukhāni</em>). Тибетский перевод <em>stong pa mtshan med smon pa med</em> подтверждает перечисление всех трёх составляющих. В русском переводе они раскрыты как определения к единственному числу <em>samādhim</em>, стоящему в санскритском тексте.<a href="#ref-121" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-122"><sup>122</sup> <em>Asthānam eva</em> — «невозможно, нет основания»; буквально «нет места», что перекликается с цепью √<em>sthā</em> в главе (20.6 <em>śūnyatā na sthānam</em>, 20.13 <em>sthihitva</em>, 20.14 <em>sthitvā</em>, 20.19 <em>asthāna</em>). Отрицание распространяется на оба члена: невозможно ни достичь нирваны, ни обозначить бодхисаттву как составное.<a href="#ref-122" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-123"><sup>123</sup> В санскритском оригинале <em>nāmena vā puna sa prajñapanāya śakyaḥ</em> и тибетском переводе (<em>ming gis kyang ni gdags par nus pa ltar</em>) фраза имеет утвердительную форму: «может быть обозначен по имени». Китайский перевод T.229 (彼以名稱亦能立) также передаёт возможность обозначения именем. Частица <em>vā</em> обычно означает «или»; её ограничительное прочтение «лишь», «только» здесь возможно в контексте, но не является однозначным. Э. Конзе переводит строку с отрицанием: «<em>cannot be defined by words</em>» («не может быть определён словами»). Такое прочтение расходится с грамматической формой санскрита и утвердительными параллельными переводами. В связи с 20.19 обозначение по имени можно понимать как условное указание на бодхисаттву, которого нельзя обозначить как обусловленное (<em>saṃskṛta</em>).<a href="#ref-123" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-124"><sup>124</sup> И не излагает (<em>śasati</em>; в тексте — <em>śocati</em>). В дошедших до нас санскритских рукописях здесь стоит слово <em>śocati</em>, что означает «скорбит» или «печалится», что не дает ясного смысла в этой строфе. Однако тибетские переводчики читали на этом месте похожее санскритское слово — <em>śasati</em> («учит», «излагает»), передав его как <em>mi 'chad</em> («не излагает»). В русском переводе принято это тибетское чтение, поскольку оно идеально завершает мысль: если бодхисаттва не может разъяснить и изложить глубокие учения, значит, он еще не созрел для пророчества о будущей буддовости.<a href="#ref-124" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-125"><sup>125</sup> <em>Anyavyākṛtaka</em> — «предсказанный другим»; тиб. <em>gzhan gyis lung bstan</em>.<a href="#ref-125" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-126"><sup>126</sup> <em>Nāmādhiṣṭhāna</em> — «опора на имя» (тиб. ming gi gzhi las, «от основы имени»): Мара пользуется именем, родословной и предсказанием, чтобы вызвать самомнение.<a href="#ref-126" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-127"><sup>127</sup> «Не стремятся там [к покою]» (<em>spṛhatāṃ janayanti</em>). В санскритском тексте эта строка читается как <em>anyatra sattvaparipācanabodhiyuktā,</em> где слово <em>anyatra</em> («иначе как», «за исключением») связывает две мысли в одно целое. Буквально это означает: «они не лелеют иного желания, кроме как вести существ к созреванию и пробуждению». Тибетские переводчики передали это прямо и просто: «иного желания у них не возникает» (<em>'dod pa gzhan mi skye</em>), а Э. Конзе перевёл как «они не взращивают в себе тоски по [колеснице архатов]». В русском переводе выбран именно этот живой смысл, подтверждённый обеими традициями.<a href="#ref-127" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-128"><sup>128</sup> «Ради блага мира» (<em>jagadartha</em>). В санскритском тексте здесь читается <em>caṃkramārtham</em> — «ради хождения», «ради медитативной прогулки». Однако тибетский перевод (<em>'gro ba'i don brtson</em> — «усердные ради блага живых существ»), китайская версия (為世間 — «ради мира») и перевод Э. Конзе (<em>for the weal of the world</em>) передают иной смысл. В основном тексте принято чтение <em>jagadartha</em>, согласующееся с этими параллелями.<a href="#ref-128" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-129"><sup>129</sup> В сфере Мары (<em>māragocara</em>). В санскритском тексте заключительная часть строки читается иначе: <em>na vivekagocaru ayaṃ hi jinena ukto</em> — «ведь Победитель назвал его не пребывающим в сфере уединения». Упоминание Мары в этой версии отсутствует. Тибетский перевод (<em>bdud kyi spyod yul gnas</em> — «пребывает в сфере деятельности Мары»), китайская версия и перевод Э. Конзе (<em>established in Mara's sphere</em>) передают заключение как указание на сферу Мары. В переводе принято чтение, подтверждаемое этими параллелями.<a href="#ref-129" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-130"><sup>130</sup> <em>ātmā kṣiṇoti tulayeya sa bodhisattvo</em> — букв. «[как] истощивший "я" да будет взвешен (оценён) этот бодхисаттва». Перевод следует реконструкции Э. Конзе, в которой заключительная строка завершает определение истинного уединения (<em>viveka</em>). В тибетском каноническом переводе (<em>byang chub sems dpa' drod snyom de ni bdag nyid nyams</em>) и комментарии Харибхадры (<em>Abhisamayālaṃkārālokā</em>) эта фраза понимается иначе — как предостережение: «бодхисаттва, который сравнивает [себя с другими / уравнивает колесницы] (<em>tulayeya</em>), губит самого себя (<em>ātmā kṣiṇoti</em>)». Китайский перевод Фасяня (一念如秤名菩薩 — «[у кого] единая мысль подобна весам, тот зовётся бодхисаттвой») ближе к первому чтению.<a href="#ref-130" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-131"><sup>131</sup> <em>Kalyāṇamitra</em> — «благой друг». Духовный наставник, способствующий продвижению по пути пробуждения. В 22.2 благими друзьями названы также сами парамиты-совершенства; наставничество понимается шире, чем личное руководство учителя.<a href="#ref-131" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-132"><sup>132</sup> <em>Anuśāsaka</em> — форма, которую можно понимать и как «наставляющие», и как «наставники»; в переводе «наставляют».<a href="#ref-132" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-133"><sup>133</sup> <em>Duvi kāraṇena</em> — «по двум причинам». В переводе эти две причины поняты как благой друг и парамиты-совершенства.<a href="#ref-133" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-134"><sup>134</sup> <em>Anubudhyati</em>. В санскритском оригинале это слово стоит в единственном числе — «он постигает». В некоторых переводах (например, у Э. Конзе) его переводят во множественном числе («они постигают») ради гладкости текста. Однако по смыслу строфы речь идёт о конкретном человеке — о том, кто доверился благому другу (<em>kalyāṇamitra</em>). Поэтому в русском переводе сохранено точное соответствие оригиналу в единственном числе: «он постигает».<a href="#ref-134" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-135"><sup>135</sup> <em>Mārgu ayu pāramitā ananyo</em> — «этот путь — совершенства, иного нет»; «шествуют» добавлен для связности, в санскрите его нет. <em>Ananya</em> — «не иной, иного нет».<a href="#ref-135" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-136"><sup>136</sup> <em>Yathā udgraho tathā prakāśitu saṃkileśo</em>. Коррелятивы <em>yathā … tathā</em> (тиб. <em>ji ltar … de ltar</em>) выражают соразмерность: насколько присутствует схватывание (<em>udgraha</em>), настолько проявляется омрачение (<em>saṃkleśa</em>). Тибетский перевод сохраняет эту корреляцию: <em>ji ltar 'dzin pa de ltar kun nas nyon mongs bstan</em>. Э. Конзе передаёт конструкцию пространственно-условно: <em>Where one takes notice, there is defilement</em>. В основном тексте принято прочтение, подчёркивающее соответствие степени схватывания и степени омрачения.<a href="#ref-136" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-137"><sup>137</sup> <em>anupalabdhi</em> (изд. <em>anopalabdhi</em>).<a href="#ref-137" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-138"><sup>138</sup> <em>aham mama</em> (изд. <em>ahu mahya</em>).<a href="#ref-138" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-139"><sup>139</sup> <em>vyavadāna</em> (изд. <em>vyodāna</em>).<a href="#ref-139" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-140"><sup>140</sup> <em>Cirabaddha</em>- (в тексте <em>cirabuddha</em>-). В санскритском издании дано чтение <em>cirabuddha</em>-, которое предположительно следует исправить на <em>cirabaddha</em>- («долго связанные»). Такое восстановление подтверждается тибетским переводом (<em>yun ring 'brel pa yi</em> — «долго связанные») и передачей Э. Конзе (<em>Bound for so long</em>).<a href="#ref-140" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-141"><sup>141</sup> <em>Anubuddhayati</em> — «постигает» (санскр.), тиб. <em>'gro</em> — «идёт» (так у Конзе); в переводе соединены оба глагола строки. <em>Abhinnasattvo</em> неясно; «не ослабевая в усердии» — по тиб. <em>rab tu brtson dkris nas</em>.<a href="#ref-141" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-142"><sup>142</sup> «Освободившееся от облаков». В приведённой санскритской строке <em>udayāti sūryu vigatāśca marīcimālā</em> отдельного слова со значением «облака» нет. Уточнение восходит к тибетскому каноническому переводу (<em>nyi ma sprin dang bral ba'i 'od zer dra pa can</em> — «солнце, свободное от облаков, обладающее сетью лучей»); образ облаков присутствует также в китайской версии Фасяня (雲). Э. Конзе следует тибетской передаче: <em>free from clouds and one blaze of rays</em>.<a href="#ref-142" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-143"><sup>143</sup> Санскр. <em>sattva pramocayāti</em> («освобождает существ»); тиб. <em>sems can mang dga' byed</em> («радует многих существ»). Принято санскритское чтение.<a href="#ref-143" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-144"><sup>144</sup> «[Когда мудрые ... смысл высшей Праджняпарамиты]» — первая половина строфы не сохранилась в известных санскритских рукописях <em>Rgs</em> и представляет собой издательскую реконструкцию на буддийский гибридный санскрит ([<em>yatha te bhavanti vidu āśayasaṃprayuktā divarātri prajñavarapāramitārthadarśī</em>]), выполненную по тибетскому каноническому переводу (<em>gang tshe mkhas pa de dag bsam pa drag ldan zhing || nyin mtshan shes rab pha rol phyin pa'i mchog don lta</em>). В основном переводе фрагмент заключён в квадратные скобки в соответствии с критическим изданием.<a href="#ref-144" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-145"><sup>145</sup> <em>Kāya-citta</em> — «тело и ум»; тибетский перевод (<em>de tshe lus sems ngag ni mkha' 'gro bya ltar rgyu</em>) добавляет «речь» (<em>ngag</em> = <em>vāc</em>), передавая полную триаду тела, речи и ума.<a href="#ref-145" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-146"><sup>146</sup> <em>Avatāra</em> (тиб. <em>glags</em> — «уязвимое место, лазейка»; Конзе: <em>entrance</em>) — в данном контексте означает «доступ», «проникновение», «возможность воздействовать». «Родственник Тьмы» (<em>kṛṣṇa-bandhu</em>) — традиционный эпитет Мары.<a href="#ref-146" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-147"><sup>147</sup> <em>avyākṛta</em>; в тексте <em>vyākṛtu</em>.<a href="#ref-147" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-148"><sup>148</sup> <em>Khila-doṣa-citta</em>. Сложное выражение, обозначающее препятствие, связанное с косностью и изъяном ума. В контексте практики бодхисаттвы может подразумеваться ожесточённость, препятствующая развитию благих качеств и сострадания. Возможные передачи: «изъян жесткосердия», «ожесточённость ума». Перевод «осквернение злобой и упрямством» представляет собой более свободное истолкование.<a href="#ref-148" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-149"><sup>149</sup> <em>Apayāti</em> буквально — «уходит, отступает» (<em>apa</em>-<em>√yā</em>), без выраженного объекта. «Отвращается [от содеянного]» — сведение по контексту трёх версий: тиб. <em>dga' bar mi byed</em> («не радуется [проступку]»), кит. 懺悔 («раскаяние, исповедание проступка»). Conze переводит <em>apayāti vā</em> как «<em>or he desists</em>» — «или воздерживается»; это также возможно, но перекликается с <em>saṃvarāṇi</em> («самоограничения») в предыдущей части строки.<a href="#ref-149" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-150"><sup>150</sup> <em>yo śikṣamāṇu na upaiti kahiṃci śikṣāṃ na ca śikṣakaṃ labhati nāpi ca śikṣadharmān</em> |<br><em>śikṣā aśikṣa ubhayo avikalpamāno yo śikṣate sa iha śikṣati buddhadharme</em> || 25.1 ||<br><br>Корень √<em>śikṣ</em> означает «учиться, упражняться»; от него образованы <em>śikṣā</em> («обучение») и <em>śikṣaka</em> («обучающийся»). В строфе корень и его производные представлены восемью словоупотреблениями:<br><br>1. <em>śikṣamāṇa</em> — «обучающийся», подлежащее. Не отрицается.<br>2. <em>śikṣā</em> — «обучение», объект при <em>na upaiti</em>. Отрицается.<br>3. <em>śikṣaka</em> — «обучающийся», объект при <em>na labhati</em>. Отрицается.<br>4. <em>śikṣadharma</em> — «дхармы обучения», объект при <em>na labhati</em>. Отрицается.<br>5. <em>śikṣā</em> — «обучение», первый член пары. Снимается в неразличении.<br>6. <em>aśikṣa</em> — «не-обучение», второй член пары. Снимается в неразличении.<br>7. <em>śikṣate</em> — «обучается». Форма, подчёркивающая само протекание обучения.<br>8. <em>śikṣati</em> — «обучается». Та же деятельность, выраженная другой грамматической формой.<br><br>Девятое слово, <em>buddhadharme</em>, корня не содержит, но замыкает строфу: обучение происходит «здесь, в дхарме будды».<br><br>Движение строфы: назван субъект (1) — отрицаются три составляющие обучения (2–4) — снимается пара противоположностей (5–6) — утверждается само действие (7–8).<br><br>Строфа не отрицает обучение, она ставит под вопрос возможность принять его как нечто независимое — отдельно от обучающегося и дхарм обучения, а также от противопоставления обучения не-обучению. Обучение не выступает здесь как нечто, к чему можно приблизиться или что можно обрести в качестве самостоятельного объекта. После этих отрицаний обучение вновь утверждается как действие, совершаемое в дхарме будды.<a href="#ref-150" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-151"><sup>151</sup> <em>Ārādhiteṣu</em>. Это санскритское слово буквально означает «среди тех, кому оказано почтение» или «когда [Будды] умилостивлены». Оно происходит от глагола, который означает «радовать», «почитать» или «снискивать чьё-то благоволение».<br><br>В тибетском переводе эта мысль передана как «чтобы порадовать Будд и их Дхарму», а в китайском — «радостно служа». Обе традиции подчеркивают, что речь идёт именно об уважении и угождении Пробуждённым. Поэтому в основном русском тексте для ясности добавлено слово «Будд» в квадратных скобках. Эдвард Конзе истолковал это слово иначе: он связал его не с Буддами, а с самими наставлениями, переведя как <em>Having found pleasure in them</em> («найдя в них радость»).<a href="#ref-151" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-152"><sup>152</sup> <em>Nirupalambha</em> (тиб. <em>dmigs pa med</em>) — отсутствие установления [объектной опоры] (<em>upalambha:</em> «установление, обнаружение», от <em>upa</em>-√<em>labh</em>): состояние, в котором ни одна дхарма не обнаруживается как самостоятельно устанавливаемый объект. Это не является ни отсутствием объектов, ни прекращением восприятия: <em>nimitta</em> (образ-знак) по-прежнему воспринимается, но отсутствует акт познания, который полагал бы дхарму в качестве опоры. В Праджняпарамите <em>nirupalambha</em> — качество праджни: практикующий видит дхармы, но не устанавливает среди них ни одной в качестве независимо существующей основы. Поскольку такое установление не возникает, следствием является и отсутствие разделения на субъект, объект и акт познания.<br><br><em>Nirupalambha</em> и <em>ānimitta</em> — не одно и то же, хотя на практике они сопутствуют друг другу.<br><br>• <em>Nirupalambha</em> («без установления» / «отсутствие установления») отрицает залипание на познаваемом: практикующий видит дхармы и образы-знаки (<em>nimitta</em>), но не устанавливает их как то, на что можно было бы опереться. Восприятие есть, установления [объектной опоры] нет.<br><br>• <em>Ānimitta</em> («без-образное, лишённое образов-знаков») отрицает сам объект: образы-знаки не взращиваются и не полагаются опорой. Это вторые из трёх врат освобождения (шуньята, без-образность, без-устремлённость).<br><br>Отсюда различие в переводах: <em>upalambha</em> → «установление» (в отличие от <em>graha</em> — «схватывание»), <em>nirupalambha</em> → «без установления» / «отсутствие установления»; <em>nimitta</em> → «образ-знак», <em>animitta</em> → «лишённое образов-знаков» или «без-образное».<a href="#ref-152" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-153"><sup>153</sup> <em>Śikṣantu</em> — от √<em>śikṣ</em>: «пусть обучаются». Тибетский перевод <em>de ltar slob</em> и английский перевод Конзе (<em>When they train thus in wisdom</em>) передают эту фразу как описание практики — «обучаясь так мудрости». В основном тексте сохранено это контекстуальное прочтение. <em>Raśmīgata</em> допускает различные интерпретации: Конзе связывает его с воздействием солнечных лучей, тибетский перевод подчёркивает их силу, китайский — испускание множества лучей, рассеивающих тьму. В переводе выбрано нейтральное «излучающим лучи».<a href="#ref-153" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-154"><sup>154</sup> <em>Śikṣita</em>. В санскритском тексте читается <em>śikṣita saṃskṛtānām</em> («обучившихся составных»). Однако такое прочтение затруднительно по смыслу. Тибетский перевод (<em>bslab par byas rnams</em> — «обучившихся») и передача Э. Конзе (<em>who have effected a training</em>) поддерживают понимание <em>śikṣita</em> как «обучившихся». В основном тексте принято это значение; слово <em>saṃskṛtānām</em> не передаётся ввиду его смысловой несогласованности с контекстом.<a href="#ref-154" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-155"><sup>155</sup> <em>Satkāya-dṛṣṭi</em> (тиб. 'jig tshogs la lta ba; Конзе: false view of individuality) — «воззрение об индивидуальности» (букв. «воззрение о [реально существующей] совокупности [скандх / личности]»). Строфа сопоставляет два ряда: шестьдесят два воззрения, включённые в воззрение об индивидуальности, и парамиты-совершенства, охваченные совершенством мудрости (prajñāpāramitā). В первом случае речь идёт о включённости множества ложных взглядов в одно корневое заблуждение; во втором — о том, что остальные совершенства не отделены от Праджняпарамиты, а охвачены ею. Число 62 соотносится с традиционной буддийской классификацией воззрений, известной, в частности, по «Брахмаджала-сутте» и её параллелям.<a href="#ref-155" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-156"><sup>156</sup> <em>Jīvitendriya</em> — «жизненная способность», термин буддийской абхидхармы, обозначающий фактор, поддерживающий жизнь. В строфе он служит основанием сравнения: как с прекращением жизненной способности прекращаются и остальные способности, так в практике мудрости все совершенства оказываются охваченными ею.<a href="#ref-156" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-157"><sup>157</sup> Строфа подчёркивает широту обучения бодхисаттвы: он осваивает качества шраваков и пратьекабудд, но не пребывает в них и не стремится к ним. Тем самым обучение не означает привязанности к определённому набору качеств или достижений.<a href="#ref-157" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-158"><sup>158</sup> Строфа сопоставляет измеримую величину — гору Меру в трёхтысячном великом тысячном мире — с благом (<em>kuśala</em>), возникающим благодаря сорадованию (<em>anumodanā</em>) порождению мысли о пробуждении (<em>cittotpāda</em>) у бодхисаттвы, ставшего невозвратным. Первое допускает измерение, тогда как второе не поддаётся ему. Несоизмеримость блага обусловлена тем, что сорадование направлено на порождение мысли о высшем пробуждении.<a href="#ref-158" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-159"><sup>159</sup> <em>Na ca prajña bodhi parieṣati āśayena</em>. Слово <em>āśayena</em> (от <em>āśaya</em> — «намерение», «внутренний настрой», «устремление») указывает на внутреннюю цель. Эту строчку можно разобрать двумя способами: либо «не ищет намеренно ни мудрости, ни пробуждения», либо «не ищет пробуждения с помощью мудрости, исходя из намерения». В основном русском переводе выбран второй вариант, при котором краткая форма <em>prajña</em> понимается как творительный падеж орудия (<em>prajñayā</em>). Старинный китайский перевод Фасяня полностью подтверждает этот смысл, говоря, что бодхисаттва «внутренним умом также не ищет мудрости пробуждения» (內心亦不求覺智).<br><br>Совсем иную традицию отражает тибетский перевод: <em>shes rab gnyis kyis byang chub tshol mi byed</em> — буквально «не ищет пробуждения посредством двух мудростей», где элемент <em>gnyis</em> указывает на двойственность. Английский исследователь Э. Конзе последовал за тибетской версией и перевёл: <em>Without any dualism he seeks in wisdom for enlightenment</em> («без всякой двойственности он ищет в мудрости пробуждения»). Таким образом, тибетская версия и перевод Конзе отражают прочтение, отличное от санскритского <em>āśayena</em>; возможная реконструкция изначального слова <em>advayena</em> («без двойственности») остаётся предположительной.<a href="#ref-159" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-160"><sup>160</sup> Пространство, небо (<em>ākāśadhātu, gagana</em>) не встречает препятствий (<em>virodha</em>) и не может быть достигнуто (<em>prāpta</em>) как определённый объект. Ему уподобляется бодхисаттва, практикующий мудрость (<em>prajñā-carita</em>) и именуемый <em>upaśāntacārī</em> — «умиротворённо практикующим». Игра слов с <em>cārī</em> («движущийся», «шествующий», «практикующий») сближает движение, практику и покой: практика бодхисаттвы совершается в умиротворении (<em>upaśānta</em>).<a href="#ref-160" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-161"><sup>161</sup> <em>Toṣayiṣyāmi</em> (в тексте <em>te śiṣya</em>). В санскритском тексте сохранено чтение <em>te śiṣya māṃ janata</em>, не дающее удовлетворительного грамматического и смыслового прочтения в данном контексте. В основном тексте принято восстановление <em>toṣayiṣyāmi janatām</em> («я порадую этих людей») от √<em>tuṣ</em> («радовать, удовлетворять»). Оно подтверждается тибетским переводом (<em>skye bo 'di mgu bya snyam</em> — «я порадую этих людей»), китайской версией Фасяня (眾人見幻而皆喜 — «люди, видя иллюзию, все радуются») и переводом Э. Конзе (<em>I will please those people</em>).<a href="#ref-161" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-162"><sup>162</sup> <em>Catukāraṇehi</em>. Буквально «по четырём причинам». В строфе перечислены четыре качества бодхисаттвы: пребывание в шуньяте, неоставление существ, соответствие поступков словам и пребывание с состраданием к существам. Благодаря этим качествам он становится неодолимым для четырёх Мар: Мары скандх, Мары клеш, Мары смерти и Мары сына богов.<a href="#ref-162" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-163"><sup>163</sup> <em>durdharṣa</em>, в тексте <em>dugharṣu</em>.<a href="#ref-163" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-164"><sup>164</sup> <em>Sattvakaruṇānugatāvasthāna</em> — букв. «тот, чьё пребывание (<em>avasthāna</em>) проникнуто (<em>anugata</em>) состраданием к существам (<em>sattvakaruṇā</em>)» (ср. китайский перевод Фасяня 菩薩慈悲處利樂 — «бодхисаттва пребывает в сострадании ради блага и радости»). Тибетский канонический перевод (<em>bde gshegs byin brlabs can</em> — «благословлённый Сугатой») и следующий ему перевод Э. Конзе (<em>sustained by the Sugatas</em> — «поддерживаемый Сугатами») читают на этом месте иную формулу (вероятно, <em>sugatādhiṣṭhāna</em>). В основном тексте принято санскритское чтение.<a href="#ref-164" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-165"><sup>165</sup> <em>Arhanvimokṣa tathāgatānām</em> — букв. «освобождение Архатов-Татхагат» (в тибетском переводе dgra bcom rnam thar de bzhin gshegs и китайской версии Фасяня 唯佛 — «только Будда» — форма дана в единственном числе; в основном переводе сохранено множественное число санскритского оригинала). В данном контексте слово arhan (arhat) выступает не как обозначение учеников-шраваков (о которых шла речь в первой строке), а как один из традиционных эпитетов самих Татхагат, чьё освобождение превосходит обитель бодхисаттвы.<a href="#ref-165" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-166"><sup>166</sup> «Эта обитель [в Праджняпарамите]» (<em>ayu vihāra</em>). Указательное местоимение <em>ayu</em> соотносится с предшествующими строфами 27.4–27.6, в которых описывается пребывание (<em>vihāra</em>) бодхисаттвы в Праджняпарамите и трёх вратах освобождения: шуньяте, беспризнаковости и отсутствии устремлений.<a href="#ref-166" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-167"><sup>167</sup> <em>Buddhasuta</em> (в тексте <em>buddhasama</em>). В санскритском издании приведено чтение <em>buddhasama</em> («подобные Буддам», «равные Буддам»). Тибетский канонический перевод (<em>sangs rgyas sras</em> — «сыны Будд», традиционное обозначение бодхисаттв; ср. <em>sugatātmaja</em> в Rgs 21.5) и перевод Э. Конзе (<em>The Buddha's offspring</em> — «потомство Будды») указывают на чтение <em>buddhasuta</em> («сыны Будд»). Расхождение -<em>suta</em> и -<em>sama</em> могло возникнуть вследствие графического смешения букв <em>ta</em> и <em>ma</em> при переписывании. Поэтому в основном тексте принято предположительное восстановление <em>buddhasuta</em>, согласующееся с тибетским переводом и английской версией Конзе.<a href="#ref-167" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-168"><sup>168</sup> <em>Niśraya</em> и <em>āśraya</em> — однокоренные (<em>ni-√śri</em> и <em>ā-√śri</em>). В переводе <em>niśraya</em> передано «опора-зависимость» (то, на что опираются как на зависимость), <em>āśraya</em> — «опора» (то, на чём стоит, основание).<a href="#ref-168" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-169"><sup>169</sup> Санскритское <em>ārūpyarūpi ca samādhi catasra śreṣṭhā</em> буквально можно передать как «и четыре превосходных сосредоточения, имеющих природу бесформенного». Форма <em>ārūpyarūpi</em> необычна и допускает разные словообразующие объяснения, в том числе образование с суффиксом -<em>rūpin</em> («имеющий характер», «обладающий природой») или смешение форм <em>ārūpya</em> и <em>rūpa</em>. Тибетский перевод (<em>gzugs med ting 'dzin dam pa bzhi</em>), китайский (四無色等三摩地) и английский перевод Э. Конзе (<em>the four most excellent Formless Trances</em>) указывают на четыре превосходных бесформенных самадхи (<em>ārūpya-samādhi</em>). В начале строфы уже упоминается пребывание в дхьяне (<em>dhyāne sthita</em>), что позволяет соотнести этот фрагмент с традиционной системой восьми медитативных погружений: четырьмя дхьянами мира форм (<em>rūpa-dhyāna</em>) и четырьмя бесформенными самадхи (<em>ārūpya-samādhi</em>). Однако такое соотнесение представляет собой контекстуальное толкование: непосредственно в строфе названы только четыре бесформенных самадхи.<a href="#ref-169" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-170"><sup>170</sup> <em>Āsrava-kṣaya</em> — «исчерпание притоков». Āsrava буквально означает «приток», «истечение». В буддийской терминологии так называются загрязнения, поддерживающие круговорот сансарного существования. Термин связан с представлением о притоках, питающих омрачённое состояние ума и препятствующих освобождению. Обычно перечисляются три притока: kāmāsrava — приток чувственных желаний, bhavāsrava — приток жажды существования и avidyāsrava — приток неведения. В некоторых классификациях выделяется также четвёртый — dṛṣṭyāsrava, приток воззрений.<br><br>Āsrava тесно связан с понятием kleśa («омрачение»), однако эти термины не являются полными синонимами: kleśa обозначает омрачающие ум факторы, тогда как āsrava подчёркивает их роль в поддержании сансарного существования.<br><br>Āsravakṣaya — «уничтожение притоков», «прекращение притоков» — обозначает их окончательное устранение; знание об этом прекращении (āsravakṣayajñāna) относится к трём высшим знаниям. В раннебуддийской традиции уничтожение притоков характеризует освобождение архата. В контексте Махаяны следует учитывать различие между освобождением шравака и полным пробуждением Будды: бодхисаттва стремится к последнему и не ограничивает свой путь достижением освобождения шравака. Это не означает отказа от очищения ума и устранения омрачений.<a href="#ref-170" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-171"><sup>171</sup> <em>Yathābhiprāya</em> (тиб. <em>bsam pa ji bzhin</em>) — «согласно своему намерению», «сообразно своему устремлению». Выражение относится к способности бодхисаттвы определять обстоятельства своего рождения в соответствии с собственным намерением. В контексте учения Праджняпарамиты это можно связать с практикой дхьян и самадхи, а также с созерцанием шуньяты: бодхисаттва не утрачивает способности действовать ради блага существ, хотя его созерцание свободно от образов-знаков (<em>nimitta</em>). Такое прочтение позволяет видеть здесь указание на намеренное рождение бодхисаттвы в мире чувственных желаний (<em>kāmadhātu</em>) ради помощи существам. Вместе с тем формулировка «освобождается от кармической предопределённости» представляет собой доктринальное истолкование, а не буквальное значение <em>yathābhiprāya</em>.<a href="#ref-171" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-172"><sup>172</sup> Не привязывается к увиденному и пережитому, не прикипает, не делает это <em>опорой</em> для привязанности.<a href="#ref-172" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-173"><sup>173</sup> <em>Kṣetraśodhī</em> — «очищающий поле, землю, мир, область», «тот, кто очищает поле». Слово образовано от <em>kṣetra</em> («земля», «мир», «поле», «сфера», в данном контексте — земля будды) и <em>śodhin</em> («очищающий»), производного от корня √<em>śudh</em> («очищать»). В <em>Rgs</em> 29.6 термин связан с двумя задачами бодхисаттвы: созреванием живых существ (<em>sattva-paripācana</em>) и очищением поля деяний (<em>kṣetra-śodhī</em>). Тибетское <em>zhing sbyong</em> буквально передаёт значение «очищать землю» (<em>zhing</em> — земля; <em>sbyong</em> — очищать, совершенствовать). Таким образом, речь идёт об очищении земли будды в связи с деятельностью бодхисаттвы ради существ.<a href="#ref-173" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-174"><sup>174</sup> В издании <em>spṛhabuddhi na saṃjaneyyā</em> («не порождает»); тиб. <em>'dod pa'i blo skyed na</em> («если порождает»). Принято тиб. чтение, так как с отрицанием нет связи со следующими строками (утрата сосредоточения).<a href="#ref-174" class="text-blue-500 hover:underline">↩</a></p>

   <p class="my-2" id="citation-175"><sup>175</sup> <em>Anantabodhisattvo</em> — «безграничный бодхисаттва» (санскр.). Тиб. <em>byang chub sems dga' na</em> — «если бодхисаттва радостен» (<em>dga'</em>); возможно, санскритское <em>ananta</em> — порча <em>ānanda</em> («радость»), которую сохраняет тибетский и бодхисаттва радуется, наслаждаясь пятью чувственными желаниями. Кит. 等引不離菩提心 — «сосредоточение не покидает пробуждения-ума» — третье чтение. Принято санскритское прочтение.<a href="#ref-175" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-176"><sup>176</sup> <em>Vicaranti</em> — «действуют», «странствуют», «шествуют», «продвигаются [в практике]». В описаниях великих бодхисаттв глагол от корня <em>vi-car</em> указывает на их свободное продвижение в сансаре ради блага существ без привязанности к ней.<a href="#ref-176" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-177"><sup>177</sup> <em>Para-sattva-pudgala-nidāna</em> — «ради других существ и личностей». Парное употребление <em>sattva</em> и <em>pudgala</em> охватывает живых существ; толкование через соотношение общего и частного встречается в комментаторском объяснении, но не следует непосредственно из слов строфы.<a href="#ref-177" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-178"><sup>178</sup> <em>Kumbhadāsī</em> — «служанка с кувшином [воды]» (<em>kumbha</em> + <em>dāsī</em>; тиб. <em>bran mo chu chun</em> — «служанка, носящая воду»), низший разряд домашней прислуги.<a href="#ref-178" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-179"><sup>179</sup> <em>Avaśāvaśa bhartikasya</em> — сочетание, допускающее членение <em>avaśā</em> + <em>vaśa bhartikasya</em>. <em>Avaśā</em> согласовано с <em>kumbhadāsī</em>: «лишённая собственной воли», «несамостоятельная» (отрицательная приставка <em>a-</em> и <em>vaśa</em> — «воля», «власть»). <em>Vaśa</em> означает «власть», «подчинение»; вместе с <em>bhartikasya</em> («господина») выражает нахождение служанки во власти хозяина. Такое прочтение поддерживается тибетским переводом <em>dbang med rje bo'i dbang: dbang med</em> — «лишённая власти [над собой]», <em>rje bo'i dbang</em> — «во власти господина». Э. Конзе предлагает иное членение, относя второе <em>avaśa</em> к господину: «покорная своему господину, который никому не подвластен». В основном тексте принято прочтение, согласующееся с тибетским переводом.<a href="#ref-179" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-180"><sup>180</sup> <em>Preṣya-bhūta</em> — «ставший тем, кого посылают» (<em>pra-iṣ</em> — «посылать»); тиб. <em>bran gyur</em> — «ставший слугой». «Подобно слуге», буквально «слуга на побегушках».<a href="#ref-180" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-181"><sup>181</sup> <em>Tṛṇa-agni-kāṣṭha-prabhava</em> — «огонь, возникший из травы и хвороста»; <em>dahate tam eva</em> — «сжигает именно их» (траву и хворост). Образ возможно восходит к традиционному способу добывания огня трением; в строфе он не раскрыт.<a href="#ref-181" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-182"><sup>182</sup> В издании <em>ātma sugatāṃ</em>; тиб. <em>bdag gi bde ba</em> («собственное благо»). Принято по тибетскому варианту.<a href="#ref-182" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-183"><sup>183</sup> <em>sadāpraruditaparivarta</em> («глава о Садапрарудите», «Всегда Плачущем» — имя бодхисаттвы, известное по «Аштасахасрике»). Кит. 常歡喜品 — «глава о постоянной радости»; тибетский колофон в наших материалах не сохранился. Конзе даёт <em>The Perfection of Vigour (Continued)</em> — описательно, по содержанию. В переводе сохранено санскритское название.<a href="#ref-183" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-184"><sup>184</sup> В санскритской версии читается <em>gaṇaye vidu bodhisattvo</em>. Восстановление <em>avidu</em> («неразумный», «несведущий») поддерживается тибетским <em>byang chub sems dpa' mi mkhas</em> и переводом Э. Конзе <em>the unwise Bodhisattva</em>. Китайский перевод Фасяня (大智菩薩, «бодхисаттва великой мудрости») передаёт противоположную характеристику и, возможно, отражает иную текстовую или переводческую традицию. Поэтому в основном переводе принято значение тибетской и английской параллелей, санскритское чтение и его реконструкция сохранены в примечании.<a href="#ref-184" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-185"><sup>185</sup> <em>Yasmin na kāyu na pi citta na sattvasaṃjñā</em>. В санскритской строке конечный элемент <em>saṃjñā</em> («распознавание, представление») по смыслу относится ко всем трём предшествующим членам: <em>kāya</em> («тело»), <em>citta</em> («ум») и <em>sattva</em> («существо»). Иными словами, подразумевается отсутствие распознавания тела, ума и существа. Такое прочтение подтверждается тибетским каноническим переводом (<em>gang tshe lus dang sems dang sems can 'du shes med</em> — «когда нет распознавания тела, ума и существа») и переводом Э. Конзе (<em>When one has no notion of either body, or thought, or a being</em> — «когда нет представления ни о теле, ни об уме, ни о существе»).<a href="#ref-185" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-186"><sup>186</sup> Вопросы бодхисаттвы — «кто говорит? кто слышит? откуда? чьё? чем / посредством чего?» (<em>ko bhāṣate, ka śṛṇute, kutu, kasya, kena</em>) — обращают созерцание к самому возникновению переживания оскорбления. Кто тот, кого ум обозначает как оскорбителя? Кто тот, кто считает себя оскорблённым? Откуда возникают жестокие слова и кому они принадлежат? Посредством чего они способны причинить страдание?<br><br>При таком исследовании говорящий, слышащий и сами слова не обнаруживаются как независимые и неизменные основания происходящего. Переживание возникает в зависимости от множества условий; представления об оскорбителе и оскорблённом также складываются в зависимости от этих условий. Поэтому вопросы гатхи можно понимать как краткое созерцательное исследование шуньяты и отсутствия неизменного «я» (<em>anātman</em>). Они ослабляют привычное схватывание ситуации как столкновения двух независимых субъектов.<br><br>Сходный ход вопросов встречается в первой главе «Ланкаватара-сутры», в эпизоде с Раваной: «кто проповедует? кому проповедуют? что такое Дхарма? что такое видение?» Там вопрошание обращено к самому опыту явления и познания.<br><br>В <em>Rgs</em> 30.8 такой анализ связан с совершенством терпения (<em>kṣāntipāramitā</em>). Услышав жестокие и оскорбительные слова (<em>paruṣa-vacana, durukta</em>), бодхисаттва пребывает в радости и спокойствии (<em>paritoṣayāti susukhaṃ</em>). Он исследует возникшую ситуацию, не принимая её за столкновение неизменных «я». Так оскорбление становится поводом для созерцания, а терпение (<em>kṣānti</em>) выражается в свободе от привычной реакции и в понимании зависимого возникновения переживания.<a href="#ref-186" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-187"><sup>187</sup> <em>Trisāhasra</em>. Сокращённое употребление космологического названия <em>trisāhasra-mahāsāhasra-lokadhātu</em> — «трёхтысячная великая тысячная система миров» (тибетский перевод: <em>stong gsum</em>). Этот термин обозначает обитаемую вселенную, состоящую из 1000³, то есть одного миллиарда одиночных мировых систем. Название указывает на три ступени умножения, где каждая последующая система шире предыдущей в тысячу раз.<a href="#ref-187" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-188"><sup>188</sup> <em>Kalapuṇya</em> (возможное членение: <em>kalā puṇya</em>). <em>Kalā</em> означает «часть», «доля», <em>puṇya</em> — «заслуга». Поэтому выражение передаётся как «доля заслуги». В заключительной части санскритской строки стоит <em>iha dānaskandhe</em> («в этой массе даяния»); чтение <em>kṣāntiskandhe</em> («в массе терпения») в приведённом тексте отсутствует.<a href="#ref-188" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-189"><sup>189</sup> <em>Dvātriṃśalakṣaṇaprabhāva anantapāro</em>. В санскритском тексте слово <em>prabhāva</em> («сила», «могущество», «влияние») и <em>anantapāro</em> («беспредельный», «не имеющий границ») определяют телесную чистоту бодхисаттвы. В тибетском переводе эта строка звучит так: <em>sum cu rtsa gnyis mtshan dang mthu stobs pha mtha' yas</em> («тридцать два признака и беспредельная сила-могущество»). На русский язык метафора перенесена так: терпение очищает облик практика, наделяя его беспредельным величием тридцати двух знаков совершенства, присущих Буддам.<a href="#ref-189" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-190"><sup>190</sup> В издании <em>viduṣām</em>; восстановлено по тиб. <em>mi mkhas</em> («неразумный»).<a href="#ref-190" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-191"><sup>191</sup> <em>pārājika</em> (пали: <em>pārājika</em>, санскр. <em>pārājika</em>) — четыре тягчайших греха в Винае (убийство, воровство, прелюбодеяние, ложь о духовных достижениях), за которые монаха навсегда изгоняют из сангхи без права восстановления.<a href="#ref-191" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-192"><sup>192</sup> <em>yasyo na saṃvari asaṃvari manyanāsti</em> — «Тот, у кого нет самомнения ни относительно сдерживания, ни относительно несдерживания».<br><br><em>manyanā</em> — «самомнение», «горделивое размышление», «интеллектуальное конструирование». В тибетском: <em>rlom sems med</em> («нет надменных мыслей»). На этом уровне бодхисаттва не просто соблюдает правила, он не выстраивает вокруг этого горделивых понятий-идей вроде «я великий аскет, а они грешники».<a href="#ref-192" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-193"><sup>193</sup> <em>mamatā</em> — «эгоистическое присвоение», чувство «моё» (от местоимения <em>mama</em> — «моё»). В тибетском: <em>bdag gir 'dzin pa</em> («схватывание как принадлежащее мне»).<a href="#ref-193" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-194"><sup>194</sup> «Ибо не удержал эти континенты за собой» (<em>na hi dvīpalabdho</em>). Буквально: «ведь он не обрёл континенты». Санскритское <em>labdha</em> означает «обретённый», «полученный». В данном контексте выражение истолковано в значении «не удержал за собой»: бодхисаттва, отдавший четыре континента, радуется самому дарению и не присваивает отданное. Такой смысл поддерживает перевод Э. Конзе (<em>for he has not kept the Continents</em>). Тибетская версия также связывает заключение строфы с отдачей континентов, хотя её формулировка не позволяет однозначно установить значение «удержал».<a href="#ref-194" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-195"><sup>195</sup> <em>yāvanti sattvā tribhave samanvāharitvā. Yāvanti</em> — «сколько бы ни было», «все, какие есть»; <em>sattvā</em> — «существа»; <em>tribhave</em> — «в трёх мирах». <em>Samanvāharitvā</em> — «приняв во внимание», «вспомнив», «обратив мысль к». Тибетское <em>bsams nas</em> («обдумав», «подумав») подтверждает смысл сознательного обращения мысли ко всем существам.<a href="#ref-195" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-196"><sup>196</sup> <em>vidu pāku naiva pratikāṅkṣati so kadācit</em> — «и никогда не ожидает созревания плода».<br><br><em>pāka</em> — букв. «варение», в контексте кармы — созревание плодов поступков (карма-випака). В тибетском: <em>rnam par smin la re ba med</em> («не имеет надежды на созревание»).<br><br><em>naiva pratikāṅkṣati kadācit</em> — «никогда не ожидает / не желает взамен».<a href="#ref-196" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-197"><sup>197</sup> <em>Parikalpa</em> — «допустим», «предположим». Тибетское <em>yongs su brtag pa bzung ste</em> («приняв предположение») и перевод Э. Конзе (<em>let us assume</em>) подтверждают вводное значение этого выражения. В санскритской строке <em>parikalpa sthāne</em> помещено в заключительной части, однако по смыслу относится ко всему условному построению. В русском переводе оно вынесено вперёд для ясности синтаксиса. Условие продолжается в строфе 31.16.<a href="#ref-197" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-198"><sup>198</sup> [Но устремлялись бы] к качествам шраваков (<em>śrāvakaguṇa</em>). Заключительная часть санскритской строки: <em>yāvanti śrāvakaguṇān parikalpa sthāne</em>. Восполнение «[но устремлялись бы]» опирается на тибетский перевод <em>nyan thos legs tshol na</em> («если бы стремились к достоинствам шраваков») и перевод Э. Конзе (<em>would wish for the virtues of the Disciples</em>). Противопоставление раскрывается в следующей строфе.<a href="#ref-198" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-199"><sup>199</sup> <em>Rūpa</em>. В данном контексте означает «облик», «внешний вид», что подтверждается последующими определениями <em>parama</em>, <em>udāra</em> и <em>suvarṇacchavi</em>, а также тибетским <em>gzugs bzang dam pa</em> («прекрасный, превосходный облик»). Перевод «форма» здесь нежелателен, поскольку может вызвать ассоциацию с <em>rūpa-skandha</em> — скандхой формы, тогда как строфа описывает привлекательную внешность бодхисаттвы.<a href="#ref-199" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-200"><sup>200</sup> <em>Vidyā</em> — «ведение» (от √<em>vid</em> — «ведать»; тиб. <em>rig [pa]</em>, Конзе: "<em>lore</em>"). В отличие от философского знания (<em>jñāna</em>, упомянутого выше в этой же строфе) и мудрости (<em>prajñā</em>, о которой говорится в следующей строфе 32.4), термин <em>vidyā</em> в контексте медитативного сосредоточения (<em>dhyāna</em>) и наряду со сверхзнаниями (<em>abhijñā</em>) и самадхи обозначает действенное, сверхчувственное ве́дение, рассеивающее неведение (<em>avidyā</em>). В буддийской традиции это классическая триада высших ве́дений (<em>tisro vidyāḥ</em>): знание прошлых жизней, «божественное око» (видение перерождений существ) и знание об исчерпании омрачений.<a href="#ref-200" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-201"><sup>201</sup> <em>Parigṛhṇati</em>. Глагол от pari-√<em>grah</em> («охватывать, принимать, удерживать») повторяется в санскритской строфе трижды, каждый раз объединяя два объекта или группы объектов: чистоту земли и существ; род Будды и Дхармы; род Сангхи и все дхармы. Тибетский перевод (<em>yongs su 'dzin</em>) также сохраняет три повторения. Э. Конзе передаёт их глаголом <em>receives</em> («принимает»). В русском переводе выбран единый эквивалент «охватывает», сохраняющий структуру строфы.<a href="#ref-201" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-202"><sup>202</sup> <em>Saṃpaddvayāvāhinīṃ</em> (в издании <em>saṃpaddūyāvāhinīṃ</em>). В основном тексте принято предположительное исправление <em>saṃpaddvayāvāhinīṃ</em> — «несущая два вида блага». Два вида блага (<em>saṃpaddvaya</em>) могут обозначать мирское благополучие (<em>abhyudaya</em>) и высшее благо, освобождение (<em>niḥśreyasa</em>) или благо для себя и другого.<a href="#ref-202" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-203"><sup>203</sup> <em>Bhadreṇa hariṇā</em>. Поэтическая игра слов (<em>śleṣa</em>), заключающая разделённое имя Харибхадры (<em>Haribhadra</em>). Выражение можно прочитать как «благим Хари» и одновременно как «благородным львом» (<em>hari</em> — «лев», <em>bhadra</em> — «благой, благородный»). Второе прочтение перекликается с образом слонов-спорщиков (<em>vādigajendra</em>), лбы которых сокрушаются.<a href="#ref-203" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-204"><sup>204</sup> <em>Kūpaṃ vādigajendrakumbhadaraṇe</em>. В санскритском тексте читается <em>kūpaṃ</em> — «колодец», «яма». Составное выражение <em>vādigajendrakumbhadaraṇe</em> можно разобрать как «для сокрушения лобных бугров слонов-вождей среди спорщиков»: <em>vādin</em> — спорщик, <em>gajendra</em> — вождь слонов, <em>kumbha</em> — лобный бугор слона, <em>daraṇa</em> — сокрушение, разбивание. В сочетании с <em>kūpaṃ</em> возникает образ ловчей ямы, предназначенной для поимки слонов. Практика отлова диких слонов с помощью ям (<em>avapāta</em>) засвидетельствована в индийских трактатах о слонах; в частности, <em>Mātaṅgalīlā</em> описывает замаскированную яму, в которую заманивали животное, после чего его связывали. Это позволяет предположить, что образ ловушки служит здесь метафорой текста, сокрушающего аргументацию спорщиков. При этом представление о разбивании лобных бугров при падении в яму прямо не подтверждается описаниями техники отлова. Возможная игра слов (<em>śleṣa</em>) в имени автора <em>bhadreṇa hariṇā</em> допускает дополнительное прочтение <em>hari</em> как «лев», однако это не отменяет основного значения выражения с <em>kūpaṃ</em>.<a href="#ref-204" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-205"><sup>205</sup> <em>Bhagavatī Ratnaguṇasaṃcayagāthā</em>. В санскритском колофоне произведение названо «Бхагавати, Собрание драгоценных качеств в строфах». Тибетский канонический колофон передаёт название как <em>'phags pa shes rab kyi pha rol tu phyin pa sdud pa tshigs su bcad pa</em> — «Собрание в строфах Благородной Праджняпарамиты». Элемент <em>ratnaguṇa</em> («драгоценные качества»), присутствующий в санскритском заглавии, в тибетском названии отсутствует.<a href="#ref-205" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-206"><sup>206</sup> <em>Ye dharmā hetuprabhavā</em>. Традиционная строфа о зависимом возникновении (<em>pratītyasamutpāda-gāthā</em>), завершающая текст.<a href="#ref-206" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-207"><sup>207</sup> <em>Bid+yA ka ra sing ha</em> — тибетская транскрипция <em>Vidyākarasiṃha</em> (тиб. <em>Rig pa'i 'od kyi seng ge</em>). Индийский пандит эпохи Тибетской империи, участвовавший в переводе буддийских сочинений на тибетский язык. Сотрудничал с рядом ведущих тибетских переводчиков, в том числе с Палцегом; ему приписывается участие более чем в двадцати переводах Кангьюра и Тенгьюра.<a href="#ref-207" class="text-blue-500 hover:underline">↩</a></p>

    <p class="my-2" id="citation-208"><sup>208</sup> <em>dpal brtsegs</em> (<em>Ka ba dPal brtsegs</em> или <em>sKa ba dPal brtsegs</em>) — Палцег (тиб. «Благая вершина»), один из ведущих тибетских переводчиков-редакторов IX века, носивший титул <em>zhu chen gyi lotsāba</em> — старшего редактора-переводчика. Участвовал в переводе и редакционной сверке буддийских текстов с индийскими пандитами, в том числе с Видьякарасимхой. Связан с составлением <em>Mahāvyutpatti</em> — санскритско-тибетского терминологического словаря, созданного в рамках имперской программы унификации переводческой терминологии. Работа над словарём проходила в несколько этапов при тибетских царях конца VIII — первой половины IX века; его окончательная редакция традиционно связывается с царствованием Ралпачана.<a href="#ref-208" class="text-blue-500 hover:underline">↩</a></p>
